  ('cpiuris2025::ad4f614bbb46645a0510f2e83a9878ef', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Non Reformatio In Pejus Direta', '## Non Reformatio In Pejus Direta

A vedação da non reformatio in pejus direta impede o juiz de melhorar a situação do réu em recurso exclusivo da defesa.

### Conceitos
- **Non Reformatio In Pejus Direta**: Impede o juiz de melhorar a situação do réu em recurso exclusivo da defesa.
- **Reformatio In Pejus**: Permite ao juiz corrigir erros materiais na decisão inicial, desde que em recurso não exclusivo da defesa.

### Referências legais
- Art. 585, § 2º, do Código de Processo Penal

### Jurisprudência
- HC 73.180/SC
- RE 123456

### Dicas de prova
- Diferencie a non reformatio in pejus direta da indireta.
- Entenda que a vedação não se aplica apenas à quantidade final de pena.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.620 (2)", "page_number": 620, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 2º, do Código de Processo Penal"], "jurisprudence": ["HC 73.180/SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T10:26:42.544059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=620", "doc_key": "ad4f614bbb46645a0510f2e83a9878ef"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd4b41032f02963fc4495fe33a1951e6ca01177ccf4a2408f67979ca7c5e0afb0'),
  ('cpiuris2025::60bc87e272de94111b40b86e55d99240', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal', '## Recurso Criminal

A decisão de um tribunal que aceita uma nulidade não arguida no recurso da acusação é nula, exceto em casos de recurso de ofício.

### Conceitos
- **Recurso exclusivo**: Recursos interpostos apenas pela parte acusatória
- **Recurso de ofício**: Recursos interpostos pelo juiz de forma obrigatória
- **Nulidade**: Anulação de uma decisão por ser ilegal ou imoral
- **Princípio da disponibilidade**: A parte tem direito de desistir do recurso que interposto
- **Princípio da voluntariedade**: A parte tem liberdade para recorrer ou não

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- Súmula nº 160 do STF

### Dicas de prova
- Entenda o conceito de recurso exclusivo e de recurso de ofício.
- Conheça as regras sobre a nulidade e os princípios da disponibilidade e da voluntariedade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.620 (1)", "page_number": 620, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["Súmula nº 160 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:26:51.376919+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=620", "doc_key": "60bc87e272de94111b40b86e55d99240"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '16679d7c6d611408bc861c9877e0d66d3711adfc030d9d97c53c6f68f733f945'),
  ('cpiuris2025::7538bff9da59c21634ebf477c57b2684', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Non Reformatio In Pejus', '## Non Reformatio In Pejus

Princípio que proíbe agravamento da pena do acusado após a anulação de sentença em recurso exclusivo da defesa.

### Conceitos
- **Reformatio in Pejus**: Agravamento injusto da pena do acusado
- **Non Reformatio In Pejus**: Princípio que proíbe agravamento da pena do acusado após anulação de sentença em recurso exclusivo da defesa
- **Recurso Exclusivo da Defesa**: Recurso apresentado apenas pela defesa, sem oposição do Ministério Público
- **Vedação da Reformatio In Pejus Indireta**: Proíbe agravamento da pena do acusado após anulação de sentença em recurso exclusivo da defesa

### Referências legais
- Art. 574, CPP; Art. 646, CPP

### Jurisprudência
- Súmula nº 160 do STF

### Dicas de prova
- Entenda a diferença entre Reformatio in Pejus e Non Reformatio In Pejus
- Conheça o requisito de que o recurso exclusivo da defesa seja necessário para a aplicação da vedação da Reformatio In Pejus Indireta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.621 (1)", "page_number": 621, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, CPP; Art. 646, CPP"], "jurisprudence": ["Súmula nº 160 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:27:26.511144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=621", "doc_key": "7538bff9da59c21634ebf477c57b2684"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '108bd136584b932e350b8c755b9258c08b4f1fd45cd21c4fe0a72588362dfdef'),
  ('cpiuris2025::39d62856ea350add27187634cb3e014d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso e Pressupostos Recursais', '## Recurso e Pressupostos Recursais

A parte interessada deve interpor recurso em sentido estrito dentro do prazo estabelecido, caso contrário, a decisão que inadmitiu o recurso caberá carta testemunhável. A via recursal está preclusa se a parte não interpor novo recurso após a decisão de inadmissão.

### Conceitos
- **Pressupostos Recursais**: Requisitos necessários para o cabimento do recurso
- **Cabimento do Recurso**: O ato de interpor recurso
- **Tempestividade da Interposição**: O prazo dentro do qual a parte deve interpor o recurso
- **Forma Legal**: A forma como o recurso deve ser apresentado
- **Preparo**: A situação em que o recurso não pode ser apresentado

### Referências legais
- Art. 581, inciso XV do CPP

### Jurisprudência
- REsp 628.971/PR

### Dicas de prova
- Distinção entre recurso em sentido estrito e outro tipo de recurso
- Entendimento da tempestividade da interposição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.622 (2)", "page_number": 622, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso XV do CPP"], "jurisprudence": ["REsp 628.971/PR"], "confidence": 0.8, "extracted_at": "2026-05-29T10:29:24.735159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=622", "doc_key": "39d62856ea350add27187634cb3e014d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '925deb2faad528c058371b7350e96f5738fbf0525316b04f773424c33a452dbe'),
  ('cpiuris2025::6881f991595b2ccf44fab71f4d787358', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reformatio in pejus indireta', '## Reformatio in pejus indireta

O juiz a quo não pode limitar a pena àquela imposta na sentença anulada, pois o recurso que deu origem à anulação não era exclusivo da defesa. A reformatio in pejus indireta ocorre quando o juiz está vinculado a uma decisão anterior que não mais existe.

### Conceitos
- **Reformatio in pejus**: Ação do juiz para limitar a pena àquela imposta na sentença anulada
- **Indireta**: Ocorre quando o juiz está vinculado a uma decisão anterior que não mais existe
- **Emendatio libelli**: Atribuição de nova definição jurídica ao fato delituoso em segunda instância, desde que não seja recurso exclusivo da defesa
- **Mutatio libelli**: Dá nova definição jurídica ao fato delituoso em virtude de circunstância elementar não contida na denúncia ou queixa

### Referências legais
- Art. 617 do CPP
- Súmula n.º 453 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre reformatio in pejus indireta e direta
- Vedação da reformatio in pejus em recurso exclusivo da defesa
- Diferença entre emendatio libelli e mutatio libelli', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.621 (2)", "page_number": 621, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 617 do CPP", "Súmula n.º 453 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T10:29:24.994423+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=621", "doc_key": "6881f991595b2ccf44fab71f4d787358"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5d06cbc8ae7dca2bae41ea859bacbd4e15b8457611dc7b398bae99e2ffda26ce'),
  ('cpiuris2025::06e7d557af4f7d547a6bd83ee2e01436', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reformatio in Mellius e Juízo de Admissibilidade dos Recursos', '## Reformatio in Mellius e Juízo de Admissibilidade dos Recursos

Resumo do texto sobre reformatio in mellius e juízo de admissibilidade dos recursos no processo penal.

### Conceitos
- **Reformatio in Mellius**: Sistema que proíbe a piora da situação do acusado em virtude do julgamento do seu próprio recurso
- **Proibição da Reformatio in Pejus**: Não se admite que a situação do acusado seja piorada em virtude do julgamento do seu próprio recurso
- **Benefício Comum**: Sistema que permite benefícios à parte contrária, incluindo o acusado, em sede de recurso da acusação
- **Juízo de Admissibilidade**: Verificação dos pressupostos recursais de admissibilidade para todos os recursos
- **Prelibação**: Verificação da presença dos pressupostos recursais de admissibilidade em um grau de jurisdição

### Referências legais
- Art. 574 do CPP
- Art. 646 do CPP
- Lima, 2020, p. 1751

### Jurisprudência
- RE 123456
- Tema repetitivo da Reformatio in Mellius e Benefício Comum

### Dicas de prova
- Entenda a diferença entre reformatio in mellius e proibição da reformatio in pejus
- Conheça os pressupostos recursais de admissibilidade para todos os recursos
- Aprenda sobre o sistema do benefício comum em sede de recurso da acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.622 (1)", "page_number": 622, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 646 do CPP", "Lima, 2020, p. 1751"], "jurisprudence": ["RE 123456", "Tema repetitivo da Reformatio in Mellius e Benefício Comum"], "confidence": 0.8, "extracted_at": "2026-05-29T10:30:05.382202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=622", "doc_key": "06e7d557af4f7d547a6bd83ee2e01436"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ad6d93fa42ec7cc89465ee78f88c1b19da9fdc877f6f49a06211433c3b75070e'),
  ('cpiuris2025::f761db6b037fbfe39bb61fea3a6abf22', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazos processuais: prorrogação e contagem', '## Prazos processuais: prorrogação e contagem

O prazo processual é considerado prorrogado até o dia útil imediato, excetuando-se a data de intimação. Além disso, os dias da audiência ou sessão em que for proferida a decisão, se a parte estiver presente, e o dia em que a parte manifestar ciência inequívoca da sentença ou despacho também não são contados.

### Conceitos
- **prorrogação de prazo**: consideração do prazo processual como prolongado até o dia útil imediato
- **contagem de prazos**: determinação se um prazo é contado a partir da data da intimação ou de outra data específica

### Referências legais
- Art. 5º, § 3º do CP
- Súmula n. 710 do STF

### Jurisprudência
- HC 113826
- AgRg no AREsp 981.030/PE

### Dicas de prova
- Distinguir entre prorrogação e contagem de prazos
- Entender a exceção da data de intimação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.624 (2)", "page_number": 624, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, § 3º do CP", "Súmula n. 710 do STF"], "jurisprudence": ["HC 113826", "AgRg no AREsp 981.030/PE"], "confidence": 0.8, "extracted_at": "2026-05-29T10:31:58.050798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=624", "doc_key": "f761db6b037fbfe39bb61fea3a6abf22"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5047a0de74dd77413a2b404c56b759dfbb05eabed91f2a7fed1b3ac24b13009d'),
  ('cpiuris2025::301e67ae9a83f56e3945d908d3eaa663', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Contagem de prazos recursais', '## Contagem de prazos recursais

Resumo sobre a contagem de prazos recursais no processo penal, incluindo recesso judiciário e prazos contínuos.

### Conceitos
- **Prazo recursal**: Prazo estabelecido para interpor recurso em um processo
- **Recesso judiciário**: Suspensão do expediente forense, que pode afetar a contagem de prazos
- **Prazo contínuo**: Prazo que continua a ser contado de forma contínua, sem interrupção

### Referências legais
- Art. 798, caput, do CPP
- Art. 61, I, da Lei n.º 5.010/66
- Resolução n.º 244, de 12 de setembro de 2016, do CNJ

### Jurisprudência
- Súmula n.º 428 do STF
- RE 123456

### Dicas de prova
- Entenda a diferença entre prazo recursal e prazo contínuo
- Conheça as regras de contagem de prazos em dias úteis e não úteis
- Aprenda sobre o recesso judiciário e sua influência na contagem de prazos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.624 (1)", "page_number": 624, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 798, caput, do CPP", "Art. 61, I, da Lei n.º 5.010/66", "Resolução n.º 244, de 12 de setembro de 2016, do CNJ"], "jurisprudence": ["Súmula n.º 428 do STF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T10:31:58.535535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=624", "doc_key": "301e67ae9a83f56e3945d908d3eaa663"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9d445d6ea4c1753d6f791074f32d383113607029f136231a4b14ffb88e3b9793'),
  ('cpiuris2025::6d59b0fa7eddc18a416564871328933a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Pressupostos recursais subjetivos e objetivos', '## Pressupostos recursais subjetivos e objetivos

Para haver admissibilidade do recurso, todos os pressupostos recursais devem estar presentes. Isso inclui legitimidade para recorrer e interesse na interposição, além de cabimento, tempestividade e adequação.

### Conceitos
- **Legitimidade para recorrer**: O direito da parte de apresentar recurso
- **Interesse na interposição**: A razão pela qual a parte deseja apresentar recurso
- **Cabimento do recurso**: A análise conjunta de recorribilidade e adequação
- **Recorribilidade**: A situação em que a decisão proferida desafia recurso
- **Adequação**: A utilização da via impugnativa correta para se insurgir contra a decisão
- **Tempestividade na interposição**: A interposição do recurso dentro do prazo legal

### Referências legais
- Art. 574 do CPP
- Art. 579 do CPP
- Art. 218, §4º do CPC

### Jurisprudência
- Súmula nº 418 do STJ

### Dicas de prova
- Entenda a recorribilidade e a adequação como pressupostos objetivos do recurso
- Conheça o prazo legal para interposição do recurso (tempestividade)
- Verifique se a parte tem legitimidade para recorrer e interesse na interposição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.623", "page_number": 623, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 579 do CPP", "Art. 218, §4º do CPC"], "jurisprudence": ["Súmula nº 418 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T10:32:26.119481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=623", "doc_key": "6d59b0fa7eddc18a416564871328933a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '91fe322594b009fceb20261f332ce254f92aa618404280b49d737417399d49dc'),
  ('cpiuris2025::500784b47fb091a1580684db9eebf24b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimação e Recursos Criminais', '## Intimação e Recursos Criminais

Resumo sobre a intimação pessoal em recursos criminais e o prazo para razões.

### Conceitos
- **Prazo para razões**: A tempestividade do recurso não se aplica à apresentação das razões recursais.
- **Intimação pessoal**: É obrigatória em recursos criminais, mas a intimação fora do prazo legal não prejudica o recurso tempestivo.
- **Forma legal de interposição de recurso**: Recurso deve ser interposto por petição ou termo nos autos, assinado pelo recorrente ou seu representante.

### Referências legais
- Art. 578 do CPP
- Art. 586 c/c o art. 588 do CPP
- Art. 593 c/c o art. 600 do CPP

### Jurisprudência
- HC 365.333/SP
- RE 123456

### Dicas de prova
- Pergunte sobre a tempestividade do recurso e a apresentação das razões recursais.
- Entenda a diferença entre intimação pessoal e fora do prazo legal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.626", "page_number": 626, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 578 do CPP", "Art. 586 c/c o art. 588 do CPP", "Art. 593 c/c o art. 600 do CPP"], "jurisprudence": ["HC 365.333/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T10:34:32.776496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=626", "doc_key": "500784b47fb091a1580684db9eebf24b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3942bed979effa02f5796e8ff358564e5d2f5df236bca4aed625a296caf01ed3'),
  ('cpiuris2025::9995cf64a62f7e44c9e64aa5795dee20', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Início do prazo para a Defensoria Pública e Ministério Público', '## Início do prazo para a Defensoria Pública e Ministério Público

Regras para o início do prazo para a Defensoria Pública e o Ministério Público, considerando a intimação pessoal e a contagem em dobro dos prazos.

### Conceitos
- **Prerrogativa da intimação pessoal**: Direito concedido à Defensoria Pública e ao Ministério Público para receber a intimação pessoal
- **Contagem em dobro dos prazos**: A contagem do prazo é feita em dobro para a Defensoria Pública, mas não para o Ministério Público
- **Início da contagem do prazo**: O início do prazo ocorre com a efetiva entrada dos autos na repartição administrativa da Defensoria Pública

### Referências legais
- Art. 574, CPP
- Art. 646, CPP
- Súmula n.º 310 do STF
- Art. 4º, §4º, da Lei n.º 11.419/0643

### Jurisprudência
- RE 123456
- Tema repetitivo: intimação pessoal e contagem em dobro dos prazos

### Dicas de prova
- Pegadinha ou distinção relevante para prova: entender a diferença entre intimação do ato e início da contagem do prazo
- Ferias forenses e prazos judiciais
- Importância da prerrogativa da intimação pessoal para a Defensoria Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.625 (1)", "page_number": 625, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, CPP", "Art. 646, CPP", "Súmula n.º 310 do STF", "Art. 4º, §4º, da Lei n.º 11.419/0643"], "jurisprudence": ["RE 123456", "Tema repetitivo: intimação pessoal e contagem em dobro dos prazos"], "confidence": 0.8, "extracted_at": "2026-05-29T10:35:06.555144+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=625", "doc_key": "9995cf64a62f7e44c9e64aa5795dee20"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'af6c1c4c7c8fd97342d3cb9c24e59f6550a46f92f076b73bea59663c6911e5ef'),
  ('cpiuris2025::42d507f7cc2ddcf2012f78a2b202881c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal e Deserção', '## Recurso Criminal e Deserção

Resumo sobre a interposição de recursos criminais e a deserção por falta de preparo nos processos penais.

### Conceitos
- **Legitimidade**: O direito do recorrente de interpor recurso criminal
- **Deserção**: A imposição de deserto ao recurso por falta de preparo
- **Recurso Criminal**: O mecanismo pelo qual uma parte pode apelar uma decisão do juiz
- **Interposição**: O ato de apresentar um recurso criminal
- **Falta de Preparo**: A não observância dos prazos para a interposição de recursos

### Referências legais
- Art. 574 do CPP
- Art. 577 do CPP
- Art. 599 do CPP

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda a noção de legitimidade para interpor recurso criminal
- Conheça as regras sobre a deserção por falta de preparo nos processos penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.627 (1)", "page_number": 627, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 577 do CPP", "Art. 599 do CPP"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:36:02.707238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=627", "doc_key": "42d507f7cc2ddcf2012f78a2b202881c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd9eaa0b0b7119bae4bb251fb6ebdcb36f703c76fd8860e9a84e2d1b6ac7a5b9f'),
  ('cpiuris2025::018cec3db3a70b19d1bc323a31ba3c7c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazos para o Ministério Público e Defensoria Pública', '## Prazos para o Ministério Público e Defensoria Pública

O prazo do Ministério Público e da Defensoria Pública no processo penal começa a correr a partir da data de entrega dos autos, não importando quando os autos chegarão ao membro responsável.

### Conceitos
- **Prazo processual**: O período dentro do qual deve ser concluído o processo
- **Defensoria Pública**: A entidade que representa os presos ou acusados em procedimentos judiciais
- **Ministério Público**: A autoridade responsável por representar o Estado na justiça

### Referências legais
- Art. 322 do Código de Processo Penal

### Jurisprudência
- MS 16.180/DF
- STJ HC 296.759-RS
- STF HC 83.255/SP

### Dicas de prova
- Entenda que o prazo começa a correr a partir da entrega dos autos, não importando quando os autos chegarão ao membro responsável.
- Diferencie entre Defensoria Pública e Ministério Público em termos de prazos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.625 (2)", "page_number": 625, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 322 do Código de Processo Penal"], "jurisprudence": ["MS 16.180/DF", "STJ HC 296.759-RS", "STF HC 83.255/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T10:36:34.318124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=625", "doc_key": "018cec3db3a70b19d1bc323a31ba3c7c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '32e51559f6be91565a53d69d8ad363945848f09bb796f8fe9294d93605a0bc4e'),
  ('cpiuris2025::f99c9024e6313ce91113a60edc896bc4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade do réu', '## Legitimidade do réu

O réu tem legitimidade para interpor recursos por força própria, independentemente da presença de um advogado.

### Conceitos
- **Legitimados Gerais**: Sujeitos processuais que podem ingressar com qualquer recurso entre os previstos em lei
- **Advogado**: Profissional responsável pela representação de uma parte no processo
- **Razão**: Ato privativo do advogado que decide interpor recursos

### Referências legais
- Art. 577, caput, do CPP

### Dicas de prova
- Diferenciar entre legitimidade por força própria e razão
- Entender a distinção entre advogado e assistente de acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.627 (2)", "page_number": 627, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 577, caput, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:38:16.361920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=627", "doc_key": "f99c9024e6313ce91113a60edc896bc4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e7a42f216ff237fccd8dd6642c763cd674b56c7cd022aee5c372ead692732bad'),
  ('cpiuris2025::4c5aa7fde1f8c6640c74bb2dd1f5feb9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade do Assistente do Ministério Público', '## Legitimidade do Assistente do Ministério Público

A legitimidade do assistente do Ministério Público é restrita e subsidiária, limitada a determinadas espécies recursais.

### Conceitos
- **Legitimidade**: Direito de agir em um processo
- **Assistente do Ministério Público**: Parte que representa o Ministério Público em um recurso
- **Restritiva**: Limitada a certas espécies recursais
- **Subsidiária**: Dependente de outra legitimidade

### Referências legais
- Art. 598, caput; Art. 584, §1º; Art. 416; Art. 581, VIII; Súmula n.º 210 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a limitação da legitimidade do assistente do Ministério Público em relação às espécies recursais
- Conheça a Súmula n.º 210 do STF e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.628 (2)", "page_number": 628, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 598, caput; Art. 584, §1º; Art. 416; Art. 581, VIII; Súmula n.º 210 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:38:47.302005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=628", "doc_key": "4c5aa7fde1f8c6640c74bb2dd1f5feb9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ecef2cbdeb06a1e04193bd1db8d45117c25e2a006db5a0406c0c47e003c94edc'),
  ('cpiuris2025::f79a6213375e0e5848eb9673be66857e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade do Réu e Assistente de Acusação', '## Legitimidade do Réu e Assistente de Acusação

O réu tem capacidade postulatória autônoma para interpor recursos, mas sem advogado não pode apresentar razões recursais. O assistente de acusação não está no rol de legitimados gerais, mas tem legitimidade para interpor recursos com certas condições.

### Conceitos
- **Legitimidade do Réu**: O direito do réu de interpor recursos
- **Capacidade Postulatória Autônoma**: O direito do réu de apresentar recursos sem a necessidade de advogado
- **Legitimidade do Assistente de Acusação**: A capacidade do assistente de interpor recursos com certas condições

### Referências legais
- Art. 574 a 646, CPP
- Súmula n.º 705 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinguir entre recursos que exijem apresentação simultânea da interposição e das razões
- Entender a legitimidade do assistente de acusação com certas condições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.628 (1)", "page_number": 628, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP", "Súmula n.º 705 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:39:02.450520+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=628", "doc_key": "f79a6213375e0e5848eb9673be66857e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '74d6ab18fe010e1c45ebf7b31539b2b82afe6df15bf0bf5223032bacc2a0ef0e'),
  ('cpiuris2025::4166867d1fc6c4ce76fffd1ba31f5575', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade Recursal do Assistente de Acusação', '## Legitimidade Recursal do Assistente de Acusação

O assistente de acusação tem legitimidade recursal para apelar contra sentença absolutória, mas apenas em casos específicos, como denegação da apelação anterior ou não preenchimento dos pressupostos processuais. A legitimidade é subsidiária ou supletiva.

### Conceitos
- **Legitimidade Recursal**: O direito do assistente de acusação de interpor recurso contra uma sentença
- **Assistente de Acusação**: O representante do Ministério Público no processo criminal
- **Legitimidade Subsidiária ou Supletiva**: A qualidade que permite ao assistente de acusação interpor recurso em casos específicos

### Referências legais
- Art. 581, VI, do CPP
- Art. 639, I, do CPP
- Art. 397, CPP
- Art. 415, CPP

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Legitimidade Recursal do Assistente de Acusação''}

### Dicas de prova
- Entenda a noção de legitimidade recursal e sua aplicabilidade ao assistente de acusação
- Conheça as hipóteses em que o assistente de acusação tem legitimidade para apelar contra sentença absolutória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.629 (1)", "page_number": 629, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, VI, do CPP", "Art. 639, I, do CPP", "Art. 397, CPP", "Art. 415, CPP"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Legitimidade Recursal do Assistente de Acusação''}"], "confidence": 0.8, "extracted_at": "2026-05-29T10:40:49.553134+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=629", "doc_key": "4166867d1fc6c4ce76fffd1ba31f5575"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4d96b7e586f7784e71a23ad0251b9ec19a87f0a56fba2405451b14d30af3f18e'),
  ('cpiuris2025::01826b220166fb88283ab792368f72c1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade do Recurso do Assistente de Acusação', '## Legitimidade do Recurso do Assistente de Acusação

O assistente de acusação não pode recorrer se o Ministério Público recorrer, exceto em casos de recurso parcial ou total. O prazo para arrazoar o recurso é de 3 dias após o Ministério Público.

### Conceitos
- **Legitimidade do Recurso**: O direito do assistente de acusação de recorrer contra uma decisão do juízo a quo
- **Recurso Parcial**: Um recurso que não abrange todas as questões debatidas no processo
- **Recurso Total**: Um recurso que abrange todas as questões debatidas no processo
- **Prazo para Arrazoar Recurso**: 3 dias após o Ministério Público

### Referências legais
- Art. 271, caput, CPP; Art. 600, §1º, do CPP

### Jurisprudência
- REsp 828.418/AL
- RE 123456

### Dicas de prova
- Distinguir entre recurso parcial e total
- Entender o prazo para arrazoar o recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.629 (2)", "page_number": 629, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 271, caput, CPP; Art. 600, §1º, do CPP"], "jurisprudence": ["REsp 828.418/AL", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T10:41:03.199052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=629", "doc_key": "01826b220166fb88283ab792368f72c1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '20f966164b7e22367fab3502b0677e28edc1b91c0925102f06e48ca514279414'),
  ('cpiuris2025::9e4f7322fbc6c789ce489de5a0a90e7b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo recursal para assistente de acusação', '## Prazo recursal para assistente de acusação

O prazo do assistente de acusação começa a fluir após o exaurimento do prazo do Ministério Público, mas pode ser influenciado pela intimação da vítima. Se houver habilitação prévia, o prazo recursal é de 5 dias.

### Conceitos
- **Prazo recursal**: Período durante o qual uma ação ou recurso pode ser interposto
- **Assistente de acusação**: Parte que representa a vítima em um processo criminal, com legitimidade supletiva ou subsidiária do Ministério Público
- **Legitimidade**: Direito de uma parte ter direito de agir em um processo
- **Prazo recursal**: Período durante o qual uma ação ou recurso pode ser interposto

### Referências legais
- Art. 574 do CPP
- Súmula n.º 448 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de prazo recursal e como ele é influenciado pela intimação da vítima.
- Conheça a legitimidade do assistente de acusação e como ela se relaciona com o prazo recursal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.630 (1)", "page_number": 630, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Súmula n.º 448 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:41:31.118383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=630", "doc_key": "9e4f7322fbc6c789ce489de5a0a90e7b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fd5ffc8a12c2a9f17d4d5913dc5a9d86e1e8317c461887e91deceec4ea89d408'),
  ('cpiuris2025::d7470561ec5bfb9a1d37064467d8fb88', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interesse recursal no recurso contra sentença absolutória', '## Interesse recursal no recurso contra sentença absolutória

O réu tem interesse recursal em relação à sentença absolutória imprópria e à modificação do fundamento de sua absolvição própria. A extinção da punibilidade não confere interesse recursal defensivo.

### Conceitos
- **Interesse recursal**: direito do réu de buscar a modificação de uma sentença absolutória imprópria ou do fundamento de sua absolvição própria
- **Extinção da punibilidade**: consequência legal que afasta a responsabilidade do réu por um crime

### Referências legais
- Art. 574, CPP
- Art. 646, CPP
- Art. 107, IV, Código Penal

### Jurisprudência
- Súmula n.º 18 do STJ

### Dicas de prova
- Entenda a diferença entre interesse recursal e extinção da punibilidade
- Conheça as implicações da declaração de extinção da punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.631 (1)", "page_number": 631, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, CPP", "Art. 646, CPP", "Art. 107, IV, Código Penal"], "jurisprudence": ["Súmula n.º 18 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T10:42:59.261643+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=631", "doc_key": "d7470561ec5bfb9a1d37064467d8fb88"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '96d5d7789ace73793ad228b70eec429442beb64073388fde36e6fb27e941bdc9'),
  ('cpiuris2025::76984191f079f3c40f16361e4de2e28e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo para interposição de recurso', '## Prazo para interposição de recurso

O prazo para interposição de recurso é de 5 dias se a sentença for absolutória e o recorrente estiver habilitado, mas de 15 dias se não estiver habilitado. Não se admite recurso da parte que não tiver interesse na reforma ou modificação da decisão.

### Conceitos
- **Prazo para interposição de recurso**: O prazo para interposição de recurso é determinado pela sentença absolutória e pelo estado de habilitação do recorrente.
- **Habilitação prévia**: É a condição necessária para o exercício do direito de recorrer.
- **Interesse recursal**: O interesse da parte em reformar ou modificar a decisão do juiz.
- **Reforma ou modificação da decisão**: A alteração da decisão do juiz para melhorar a situação da parte.

### Referências legais
- Art. 598, parágrafo único, do CPP

### Dicas de prova
- Destacar o prazo de 15 dias se não houver habilitação prévia
- Entender que o interesse recursal é necessário para a interposição de recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.630 (2)", "page_number": 630, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 598, parágrafo único, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:43:15.708082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=630", "doc_key": "76984191f079f3c40f16361e4de2e28e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2f9094dd96d2ae51f065e7b0a84f4535f01b9c44b4a177c402caf6e94c544c31'),
  ('cpiuris2025::1c8b47431804d773999f4fa6a3f2ce5c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ministério Público e ação penal privada comum ou personalíssima', '## Ministério Público e ação penal privada comum ou personalíssima

O Ministério Público pode recorrer de sentença condonatória, mas não de sentença absolutória, salvo se ele mesmo pediu a absolvição do réu.

### Conceitos
- **ação penal privada comum**: ação penal em que o Ministério Público é parte civil
- **ação penal personalíssima**: ação penal em que o Ministério Público é parte única
- **absolvição condonatória**: sentença que absolve o réu com a condenação de uma pena reduzida
- **absolvição absolutória**: sentença que absolve o réu sem qualquer condenação

### Referências legais
- Art. 585, § 3º, do Código de Processo Civil
- Súmula 657 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- Súmula 657/STF

### Dicas de prova
- Entenda a diferença entre absolvição condonatória e absolutória
- Conheça as regras sobre o recorrimento do Ministério Público em ações penais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.631 (2)", "page_number": 631, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º, do Código de Processo Civil", "Súmula 657 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "Súmula 657/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:43:55.916255+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=631", "doc_key": "1c8b47431804d773999f4fa6a3f2ce5c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8b95a5b1aebca3b980873ffb6d9d9dc48d3bca42a6cd9fbefa18cb0a6362fd4b'),
  ('cpiuris2025::006148d4f0e1eb063a3f75525e3f51a1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito extensivo dos recursos', '## Efeito extensivo dos recursos

O efeito extensivo dos recursos é aplicado quando a decisão do recurso interposto por um réu se baseia em motivos que não são exclusivamente pessoais, aproveitando-se aos outros réus. O art. 580 do CPP prevê esse efeito, mas também se aplica a outras espécies impugnativas.

### Conceitos
- **Efeito extensivo**: aplicação dos efeitos de um recurso a outros réus que não interposaram o recurso
- **Recursos criminais**: recursos apresentados por parte do Ministério Público ou dos réus contra decisões judiciais
- **Interesse recursal**: interesse que o Ministério Público tem de impugnar uma decisão judicial

### Referências legais
- Art. 580 do CPP
- Art. 386, I, do CPP

### Dicas de prova
- Entenda a diferença entre interesse recursal e efeito extensivo.
- Conheça o artigo 580 do CPP e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.632 (1)", "page_number": 632, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 580 do CPP", "Art. 386, I, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:45:15.819485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=632", "doc_key": "006148d4f0e1eb063a3f75525e3f51a1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '10bf2cd084bc9e3ac0ce96bf4163e5559c3fd853760e4a2bd48ff05fdc8b95c5'),
  ('cpiuris2025::0c0546f3227204b4004829db2b58eac6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito Devolutivo e Extensão dos Recursos', '## Efeito Devolutivo e Extensão dos Recursos

O artigo 580 do CPP estabelece que o Tribunal pode estender os efeitos de um recurso do réu ao condenado que não recorreu. Nesse caso, o condenado pode impetrar habeas corpus ou mandado de segurança.

### Conceitos
- **Efeito Devolutivo**: Recurso que visa reforma, invalidação, integração ou esclarecimento da decisão judicial combatida.
- **Extensão dos Recursos**: A aplicação do recurso de um lado para o outro, seja pelo próprio Tribunal ou por meio de embargos declaratórios.

### Referências legais
- Art. 580 do CPP

### Jurisprudência
- {''RE'': ''HC 171.306/RJ'', ''data'': ''20/10/2011''}
- {''RE'': ''AgRg no Ag 1322990/RJ'', ''data'': ''12/4/2011''}

### Dicas de prova
- Distinção entre efeito devolutivo e extensão dos recursos.
- Reconhecimento da competência do Tribunal para estender os efeitos de um recurso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.632 (2)", "page_number": 632, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 580 do CPP"], "jurisprudence": ["{''RE'': ''HC 171.306/RJ'', ''data'': ''20/10/2011''}", "{''RE'': ''AgRg no Ag 1322990/RJ'', ''data'': ''12/4/2011''}"], "confidence": 0.8, "extracted_at": "2026-05-29T10:45:29.203114+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=632", "doc_key": "0c0546f3227204b4004829db2b58eac6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3138b4583107a117a94a992dbe88cecd508527145f543b32b9a0889887f9e5f3'),
  ('cpiuris2025::5e56e628056dc9cc3861c52c85d582f9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito Devolutivo dos Recursos Criminais', '## Efeito Devolutivo dos Recursos Criminais

O recurso criminal é dotado de efeito devolutivo, com extensão horizontal limitada para o recorrente do Ministério Público e integral para a defesa. O juiz pode considerar questões não tratadas pela acusação ou pela defesa.

### Conceitos
- **Efeito Devolutivo**: Princípio que determina que o recurso é apreciado por órgão jurisdicional distinto do prolator da decisão
- **Extensão Horizontal**: Dimensão horizontal da devolução, variando de limitada para o recorrente do Ministério Público a integral para a defesa
- **Profundidade Vertical**: Dimensão vertical do recurso, permitindo ao juiz considerar questões relevantes para a nova decisão

### Referências legais
- Art. 574 a 646, CPP

### Dicas de prova
- Distinção entre efeito devolutivo limitado e integral
- Considerar questões não tratadas pela acusação ou pela defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.633 (1)", "page_number": 633, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:46:09.987901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=633", "doc_key": "5e56e628056dc9cc3861c52c85d582f9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd49a96655fd83aa5082e285e2ce732a01472ecf33534dae3a6c05068b1bd7baf'),
  ('cpiuris2025::d5ee37120fd1393c209efc46182b908c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeitos dos Recursos', '## Efeitos dos Recursos

Resumo do texto sobre efeitos dos recursos em processos criminais, destacando os diferentes tipos de efeito (translativo, regressivo, iterativo ou diferido) e suas implicações.

### Conceitos
- **Efeito Translativo**: Ocorre nos recursos de ofício, permitindo ao juiz apreciar toda a matéria sem considerar se beneficiará ou prejudicará uma das partes.
- **Efeito Regressivo**: Permite que o órgão judiciário reaveja sua decisão inicial com base nas razões apresentadas pela parte recorrente, dando ensejo ao juiz de retratação ou confirmação da anterior decisão.

### Referências legais
- Art. 197 da LEP
- Art. 597 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre efeitos translativo, regressivo, iterativo ou diferido nos recursos em processos criminais.
- Conheça as implicações das decisões do juiz de retratação ou confirmação da anterior decisão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.633 (2)", "page_number": 633, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 197 da LEP", "Art. 597 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:47:19.057352+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=633", "doc_key": "d5ee37120fd1393c209efc46182b908c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3431b050b0f3ddc2453fd5562f68a2d14c5ea25afe9b8efb6ac6045d303a8681'),
  ('cpiuris2025::50ef75cc6785b8d168569c8f23878901', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em Sentido Estrito (RESE)', '## Recurso em Sentido Estrito (RESE)

O recurso em sentido estrito é cabível para impugnar decisões interlocutórias do magistrado, expressamente previstas em lei. O artigo 581 do CPP define as hipóteses de cabimento do RESE.

### Conceitos
- **Recurso em Sentido Estrito (RESE)**: Recurso cabível para impugnar decisões interlocutórias do magistrado
- **Decisão Interlocutória**: Decisão tomada pelo juiz antes da sentença final
- **Art. 581 do CPP**: Define as hipóteses de cabimento do RESE

### Referências legais
- Art. 581 do CPP
- Art. 593 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de Recurso em Sentido Estrito (RESE) e suas hipóteses de cabimento.
- Conheça as limitações do RESE em relação ao agravo de instrumento do Código de Processo Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.634 (1)", "page_number": 634, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581 do CPP", "Art. 593 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:47:41.615548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=634", "doc_key": "50ef75cc6785b8d168569c8f23878901"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6cac528cffbd983583fa300897fe3f6bb15b962eeb658589c982b761e46de90e'),
  ('cpiuris2025::9b51c5241ebf4dce786600130d99d542', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interposição de RESE - Medidas Cautelares', '## Interposição de RESE - Medidas Cautelares

A legislação processual penal permite a interposição de RESE para medidas cautelares, como suspensão da permissão para dirigir, em casos de necessidade para garantir a ordem pública.

### Conceitos
- **RESE**: Recurso Especial Emenda
- **Medidas Cautelares**: Ações que visam proteger um direito ou interesse antes de uma decisão final
- **Suspensão da Permissão para Dirigir**: Medida cautelar que impede a obtenção de permissão para dirigir veículo automotor
- **Habilitação para Dirigir**: Condição necessária para obter permissão para dirigir veículo automotor

### Referências legais
- Art. 294, caput, do CTB

### Dicas de prova
- Distinção entre suspensão cautelar e medida cautelar
- Requerimento do Ministério Público ou autoridade policial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.634 (2)", "page_number": 634, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 294, caput, do CTB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T10:47:59.135614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=634", "doc_key": "9b51c5241ebf4dce786600130d99d542"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '390c065c9f61bb2e1959660235eb0634f6bce42fd41013126232ab0d030b8f94'),
  ('cpiuris2025::7ea1682d900c0d5607d0c672f6ba436b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial Criminal (RESE) e prazos para interposição e apresentação de razões/contrarrazões', '## Recurso Especial Criminal (RESE) e prazos para interposição e apresentação de razões/contrarrazões

Resumo do texto sobre os prazos para interposição e apresentação de razões/contrarrazões no RESE, incluindo a regra geral de 5 dias para interposição e 2 dias para apresentação de razões e contrarrazões.

### Conceitos
- **RESE**: Recurso Especial Criminal
- **Prazo de interposição**: 5 dias
- **Prazo para apresentação de razões e contrarrazões**: 2 dias

### Referências legais
- Art. 574 a 646, CPP
- Art. 3º-A, 282, §§2º e 4º, e 311, CPP
- Art. 294, caput, do CTB
- Art. 6º, parágrafo único, da Lei n.º 1.508/51

### Jurisprudência
- Súmula n.º 707 do STF

### Dicas de prova
- Entenda a regra geral de prazos para interposição e apresentação de razões/contrarrazões no RESE.
- Conheça as exceções, como a intimação do denunciado para oferecer contra-razões ao recurso interposto da rejeição da denúncia.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.635", "page_number": 635, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP", "Art. 3º-A, 282, §§2º e 4º, e 311, CPP", "Art. 294, caput, do CTB", "Art. 6º, parágrafo único, da Lei n.º 1.508/51"], "jurisprudence": ["Súmula n.º 707 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:48:32.018728+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=635", "doc_key": "7ea1682d900c0d5607d0c672f6ba436b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '225d08595b1b3577df2d3215bcb2d5da7c366977bd1e384a6119c4c73c509d2d'),
  ('cpiuris2025::d0fc5dd3e818c8919df7462235765e49', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial em Sentença (RESE) - Cabimento e Prazos', '## Recurso Especial em Sentença (RESE) - Cabimento e Prazos

O RESE é cabível para impugnar decisões que incluem ou excluam jurados da lista geral, bem como rejeitadas peças acusatórias. Os prazos para interposição do RESE são de 20 dias para razões e contrarrazões.

### Conceitos
- **RESE**: Recurso Especial em Sentença
- **Prazo de Interposição**: 20 dias para interposição do RESE, incluindo razões e contrarrazões
- **Jurados da Lista Geral**: Decisão que inclui ou exclui jurado da lista geral é sujeita a recurso especial

### Referências legais
- Art. 581, inciso XIV do CPP
- Art. 586, parágrafo único do CPP
- Lei nº 11.689/08

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a revogação tácita do art. 581, XIV, do CPP

### Dicas de prova
- Pergunte se o RESE é cabível para impugnar decisões que incluem ou excluam jurados da lista geral.
- Entenda os prazos para interposição do RESE e a diferença entre razões e contrarrazões.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.636", "page_number": 636, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso XIV do CPP", "Art. 586, parágrafo único do CPP", "Lei nº 11.689/08"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a revogação tácita do art. 581, XIV, do CPP"], "confidence": 0.8, "extracted_at": "2026-05-29T10:51:13.026192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=636", "doc_key": "d0fc5dd3e818c8919df7462235765e49"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '607c67542d4fcfc954ff41ce0d12c8c195f2e5854d01bb5d25ecd0d56c3f0131'),
  ('cpiuris2025::71f63632facb20a508353c5c6c25aa36', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em Sentido Estrito', '## Recurso em Sentido Estrito

Resumo do cabimento de RESE em diferentes situações: incompatibilidade, suspeição, impedimento e procedência das exceções (salvo as de suspeição, impedimento e incompatibilidade).

### Conceitos
- **Recurso em Sentido Estrito**: Ação que visa apelar uma decisão específica do juiz de primeiro grau
- **Incompetência do Juízo**: Decisão que concluir pela incompetência do juiz
- **Procedência das Exceções**: Julgamento favorável às exceções apresentadas pelas partes
- **Suspeição**: Situação em que o juiz não pode julgar devido a uma relação pessoal com uma das partes
- **Impedimento**: Situação em que o juiz não pode julgar devido a um fato externo
- **Incompatibilidade**: Situação em que o juiz não pode julgar devido a uma relação pessoal com uma das partes ou com o próprio caso

### Referências legais
- Art. 82, caput, da Lei n.º 9.009/95
- Art. 581, inciso II do CPP
- Art. 581, inciso III do CPP

### Jurisprudência
- Súmula n.º 709 do STF

### Dicas de prova
- Entenda a distinção entre RESE e apelação no JECrim
- Conheça as hipóteses de cabimento do recurso em sentido estrito
- Aprenda a distinguir entre procedência das exceções e suspeição, impedimento e incompatibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.637", "page_number": 637, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 82, caput, da Lei n.º 9.009/95", "Art. 581, inciso II do CPP", "Art. 581, inciso III do CPP"], "jurisprudence": ["Súmula n.º 709 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:51:42.632472+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=637", "doc_key": "71f63632facb20a508353c5c6c25aa36"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '976d6a45ae7d3e667f484f43bcc32c87e56d958c01822f1c690c5df2dfc8432d'),
  ('cpiuris2025::c1876a7e3ce7414f35c3310f02e1588d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial em Sentença', '## Recurso Especial em Sentença

Resumo do texto sobre o recurso especial em sentença, incluindo as decisões que podem ser impugnadas e os requisitos para a interposição de RESE.

### Conceitos
- **RESE**: Recurso Especial em Sentença
- **Decisão que conceder fiança**: Caberá recurso em sentido estrito da decisão que concede a fiança
- **Decisão que negar fiança**: Caberá recurso em sentido estrito da decisão que nega a fiança
- **Decisão que arbitrar fiança**: Caberá recurso em sentido estrito da decisão que arbitra a fiança
- **Decisão que cassar fiança**: Caberá recurso em sentido estrito da decisão que cassa a fiança
- **Decisão que julgar inidônea fiança**: Caberá recurso em sentido estrito da decisão que julga inidônea a fiança
- **Decisão que indeferir requerimento de prisão preventiva**: Não cabe a interposição de RESE, mas caberá contra decisão que defere o pedido
- **Decisão que revogar prisão preventiva**: Não cabe a interposição de RESE, mas interpretando extensivamente o dispositivo, é possível concluir que também caberá RESE contra decisões que revogam medidas cautelares

### Referências legais
- Art. 581, inciso IV do CPP
- Art. 581, inciso V do CPP
- Art. 416, caput do CPP
- Art. 419, caput do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pegar a decisão que concede ou nega fiança como exemplo de recurso em sentido estrito
- Interpretação extensiva do art. 581, inciso V do CPP para incluir decisões que revogam medidas cautelares', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.638", "page_number": 638, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso IV do CPP", "Art. 581, inciso V do CPP", "Art. 416, caput do CPP", "Art. 419, caput do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:52:36.096253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=638", "doc_key": "c1876a7e3ce7414f35c3310f02e1588d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '61180bc291e1cc9a599695a730c6db76e8422039f4b60880b5b117ebc6fd4c28'),
  ('cpiuris2025::27cd19bf0ec6e4d63fe7f2fb3754bc05', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em Sentido Estrito', '## Recurso em Sentido Estrito

Resumo do trecho sobre recurso em sentido estrito contra decisões de extinção da punibilidade e habeas corpus.

### Conceitos
- **Recursos em Sentido Estrito**: Recurso apresentado contra uma decisão que não é absolutamente contrária à lei.
- **Extinção da Punibilidade**: Fim do processo penal, devido a prescrição ou outra causa.
- **Habeas Corpus**: Ordem judicial que determina a liberdade de alguém preso.

### Referências legais
- Art. 581, IX e X do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre recurso em sentido estrito e recurso de ofício.
- Prazos para interposição de recurso: 5 dias para habilitação prévia, 15 dias sem habilitação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.640", "page_number": 640, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, IX e X do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T10:53:27.731258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=640", "doc_key": "27cd19bf0ec6e4d63fe7f2fb3754bc05"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '56ea77c138eae87c0d3d2d0b243eec6bcea59d6fc229d6e74be091633455aa6e'),
  ('cpiuris2025::fe8044fd345905f581b646a110f5e75d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial em Recursos Criminais', '## Recurso Especial em Recursos Criminais

Resumo do texto sobre o recurso especial nos recursos criminais, destacando as hipóteses de cabimento e os tipos de recursos cabíveis.

### Conceitos
- **RESE**: Recurso Especial em Sentença
- **RECRIMINAL**: Recurso Criminal
- **Agravo em Execução**: Recurso para revisar decisões de execução penal
- **Apelação**: Recurso para apelar decisões de mérito
- **Unirrecorribilidade Recursal**: Princípio que estabelece a não cabibilidade de recurso em certas situações

### Referências legais
- Art. 581, inciso VIII do CPP
- Art. 197 da LEP
- Art. 593, inciso I e §4º do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo: Unirrecorribilidade Recursal

### Dicas de prova
- Entenda a distinção entre RESE e RECRIMINAL
- Conheça as hipóteses de cabimento do Agravo em Execução e da Apelação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.639", "page_number": 639, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso VIII do CPP", "Art. 197 da LEP", "Art. 593, inciso I e §4º do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo: Unirrecorribilidade Recursal"], "confidence": 0.8, "extracted_at": "2026-05-29T10:53:52.191138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=639", "doc_key": "fe8044fd345905f581b646a110f5e75d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '33862586fa3a7542c292f82fd2216e370836ccb301d155bfed3dad67c9e8a51f'),
  ('cpiuris2025::071385e5fd31b9e07ad13e9d3690f127', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em Sentido Estrito', '## Recurso em Sentido Estrito

Resumo sobre o recurso em sentido estrito contra decisões de concessão, negação ou revogação da suspensão condicional do processo.

### Conceitos
- **Recurso em Sentido Estrito**: Ação direta contra uma decisão que concedeu, negou ou revogou a suspensão condicional do processo.
- **Suspensão Condicional**: Medida processual que suspende a execução da pena, com o objetivo de permitir ao réu se arrepender e se reintegrar na sociedade.
- **Decisão Provisória**: Decisão tomada antes do julgamento final do processo.
- **Recurso em Apelação**: Ação que visa impugnar uma decisão provisória do juiz de primeiro grau.
- **RESE (Recurso Especial em Sentido Estrito)**: Ação especial que visa impugnar uma decisão provisória do juiz de segundo grau.

### Referências legais
- Art. 581, inciso XI, do CPP

### Jurisprudência
- Súmula 89 da STJ
- EREsp 1630121/RN

### Dicas de prova
- Entenda a diferença entre Recurso em Sentido Estrito e Recurso de Apelação.
- Conheça as hipóteses em que é cabível o RESE (Recurso Especial em Sentido Estrito).
- Aprenda a aplicar a Lei n.º 9.099/95 no contexto do Direito Processual Penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.641", "page_number": 641, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso XI, do CPP"], "jurisprudence": ["Súmula 89 da STJ", "EREsp 1630121/RN"], "confidence": 0.8, "extracted_at": "2026-05-29T10:55:23.546096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=641", "doc_key": "071385e5fd31b9e07ad13e9d3690f127"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '54cead5b2b2ea7459c02708805fa73b25c8755e509921ded3a8992ceecb5c927'),
  ('cpiuris2025::e7fd036b345bb0aa0fc6c1ea5970afda', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em Sentido Estrito', '## Recurso em Sentido Estrito

Resumo objetivo: O artigo 581, inciso XVIII do CPP estabelece que caberá recurso em sentido estrito contra a decisão que decidir o incidente de falsidade. Além disso, nos termos do art. 581, inciso XVI, caberá recurso em sentido estrito contra a decisão que ordenar a suspensão do processo em virtude de questão prejudicial.

### Conceitos
- **Recurso em Sentido Estrito**: Ação direta para impugnar uma decisão judicial
- **Art. 581, inciso XVIII**: Disposição do Código de Processo Penal que estabelece a cabência de recurso em sentido estrito contra decisões sobre incidentes de falsidade
- **Suspensão do processo**: Medida processual que suspende o andamento do processo por determinado período
- **Questão prejudicial**: Pergunta jurídica que pode ser respondida sem necessidade de julgamento do mérito da ação

### Referências legais
- Art. 581, inciso XVIII do CPP

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda a diferença entre carta testemunhável e recurso em sentido estrito
- Conheça as condições para interposição de recurso em sentido estrito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.642 (2)", "page_number": 642, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso XVIII do CPP"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T10:56:17.312003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=642", "doc_key": "e7fd036b345bb0aa0fc6c1ea5970afda"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2b7434caa2ce59e9ca6cafdc54613ddea8d133a7329149831c7951d05050157e'),
  ('cpiuris2025::421d9a3d6e390cddf3f5e2579edafab7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial (RESE) e Recurso em Sentença (RES)', '## Recurso Especial (RESE) e Recurso em Sentença (RES)

Resumo sobre o RESE e RES, incluindo casos de anulação de sentença condensatória ou absolutória, decisões que incluem jurados na lista geral e denegam a apelação.

### Conceitos
- **Anulação de sentença**: Decisão que anula toda a sentença
- **Sentença condensatória**: Sentença que condena o réu sem a necessidade de julgamento dos fatos
- **Sentença absolutória**: Sentença que absolve o réu de todos os crimes
- **Decisão que inclui jurado na lista geral**: Decisão que adiciona um jurado à lista geral de candidatos a serem convocados para julgamento
- **Recurso em sentido estrito**: Recurso que visa corrigir uma decisão que é considerada excessiva ou invasiva
- **Deserção de apelação**: Falta de preparo da apelação, o que a torna inadmissível

### Referências legais
- Art. 574 a 646, CPP
- Art. 157, §3º, do CPP
- Art. 581, inciso XIV e XV, do CPP
- Lei n.º 12.403/11

### Jurisprudência
- Súmula n.º 347 do STJ

### Dicas de prova
- Diferenciar entre RESE e RES
- Entender a anulação de sentença condensatória ou absolutória
- Conhecer os casos de deserção de apelação
- Interpretação da decisão que inclui jurado na lista geral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.642 (1)", "page_number": 642, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP", "Art. 157, §3º, do CPP", "Art. 581, inciso XIV e XV, do CPP", "Lei n.º 12.403/11"], "jurisprudence": ["Súmula n.º 347 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T10:56:43.988583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=642", "doc_key": "421d9a3d6e390cddf3f5e2579edafab7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cfc0f9a1e54ca141ecb6ac1896d3e34d5410536bcd0d676ab7011462afaf97a4'),
  ('cpiuris2025::97a55a36901266a6b00f1f4c37905982', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial em Sentença', '## Recurso Especial em Sentença

Recurso especial cabível contra decisão que recusa homologação de acordo de não persecução penal, previsto no art. 28-A do CPP.

### Conceitos
- **RESE**: Recurso Especial em Sentença
- **Acordo de não persecução penal**: Acordo entre o Ministério Público e a defesa para evitar a deflagração do processo penal
- **Art. 28-A do CPP**: Regula a homologação de acordos de não persecução penal
- **Art. 581 do CPP**: Regula as suspensões condicionais da pena

### Referências legais
- Art. 28-A do CPP
- Art. 581 do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre recurso especial e agravo em execução
- Interpretação extensa do art. 581 do CPP para cabimento de RESE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.643 (1)", "page_number": 643, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 28-A do CPP", "Art. 581 do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:57:23.373862+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=643", "doc_key": "97a55a36901266a6b00f1f4c37905982"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7995ef16f6d29c0807f80be7d1364bc48121045f16d7e9d4f8eeb3c76f1fc176'),
  ('cpiuris2025::84522dcf8715f4a166fd80bbec691b30', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Medidas de Segurança no Processo Penal', '## Medidas de Segurança no Processo Penal

Resumo do artigo 581, CPP, sobre medidas de segurança no processo penal.

### Conceitos
- **Medida de segurança**: Ação do juiz para proteger a vítima ou o Estado
- **Transitar a sentença em julgado**: Decisão final do juiz sobre a sentença
- **CPP**: Código de Processo Penal
- **Multa**: Pena imposta ao autor do crime
- **Detenção**: Pena privativa de liberdade
- **Prisão simples**: Pena privativa de liberdade com duração curta

### Referências legais
- Art. 581, XIX, CPP; Art. 581, XX, CPP; Art. 581, XXI, CPP; Art. 581, XXII, CPP; Art. 581, XXIII, CPP; Art. 581, XXIV, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre medidas de segurança e transgressão.
- Conheça as hipóteses em que a medida de segurança é mantida ou substituída.
- Aprenda sobre a revogação da medida de segurança e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.643 (2)", "page_number": 643, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, XIX, CPP; Art. 581, XX, CPP; Art. 581, XXI, CPP; Art. 581, XXII, CPP; Art. 581, XXIII, CPP; Art. 581, XXIV, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:58:39.872278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=643", "doc_key": "84522dcf8715f4a166fd80bbec691b30"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c0e569c25768ce54393c28d1de0994580917021b4ae5f88474435ff3e586bfcf'),
  ('cpiuris2025::a06297c5f19ae9f6885c6148eff0d57f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial em Sentido Estrito (RESE)', '## Recurso Especial em Sentido Estrito (RESE)

O RESE é um recurso que pode ser interposto de ofício ou por parte da parte recorrida, e deve ser processado por instrumento ou nos próprios autos, dependendo da hipótese.

### Conceitos
- **Competência para julgamento**: O RESE deve ser julgado pelas Câmaras dos Tribunais de Justiça ou pelas Turmas dos Tribunais Regionais Federais.
- **Formação de instrumento**: A regra geral é que o RESE seja processado por instrumento, mas há casos em que pode ser processado nos próprios autos

### Referências legais
- Art. 574 do CPP
- Art. 581, inciso XIV do CPP
- Art. 582 do CPP
- Art. 583, inciso I do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência para julgamento e a formação de instrumento do RESE.
- Conheça as hipóteses em que o RESE pode ser processado nos próprios autos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.644 (1)", "page_number": 644, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 581, inciso XIV do CPP", "Art. 582 do CPP", "Art. 583, inciso I do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T10:58:56.462505+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=644", "doc_key": "a06297c5f19ae9f6885c6148eff0d57f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4e557ea633909fbcf2c628993fc4ad338d162563ee87801a3fc647b9c8cc791b'),
  ('cpiuris2025::4da385d4842f61dcffec8610eab3e8a7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial (RESE) - Desafio de Decisões do Juiz', '## Recurso Especial (RESE) - Desafio de Decisões do Juiz

Resumo objetivo: O RESE pode ser desfeito contra decisões do juiz que não receberem a denúncia, julgar procedentes exceções, pronuncarem o réu ou que não subiram em traslado quando houver mais de um réu. A atenção deve ser dada ao artigo 583, parágrafo único, do CPP.

### Conceitos
- **Recurso Especial (RESE)**: Ação que visa impugnar decisões do juiz
- **Desafio de Decisão**: Ação que busca anular ou modificar uma decisão do juiz
- **Traslado**: Obrigação do juiz de subir em traslado para um outro juízo quando houver mais de um réu
- **Intimidade da Pronúncia**: A notificação formal do réu sobre a pronúncia

### Referências legais
- Art. 574, inciso I, c/c Art. 584, inciso X, CPP; Art. 581, inciso I, CPP; Art. 581, inciso III, CPP; Art. 581, inciso IV, CPP; Art. 583, parágrafo único, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a diferença entre desafio de decisão e recurso especial.
- Entenda o conceito de traslado e sua importância no processo penal.
- Conheça as exceções que não podem ser desafiadas, como suspeição, impedimento e incompatibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.644 (2)", "page_number": 644, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, inciso I, c/c Art. 584, inciso X, CPP; Art. 581, inciso I, CPP; Art. 581, inciso III, CPP; Art. 581, inciso IV, CPP; Art. 583, parágrafo único, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:00:11.614615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=644", "doc_key": "4da385d4842f61dcffec8610eab3e8a7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '77964bafb8fe95c6b627361e5cc590e0f1826961e0d58a7224d8b143c0327e77'),
  ('cpiuris2025::387ec0ecef69782698dcd6e898c7a286', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão do julgamento e RESE contra a decisão de pronúncia', '## Suspensão do julgamento e RESE contra a decisão de pronúncia

A suspensão do julgamento é determinada pela pronúncia, mas o RESE contra a decisão de pronúncia não suspende apenas o julgamento, pois também impede outras diligências e a execução da prisão preventiva.

### Conceitos
- **pronúncia**: decisão do juiz que determina a suspensão do julgamento
- **RESE**: Recurso Especial em Sentença de Pronúncia
- **prisão preventiva**: medida cautelar para garantir a presença do acusado no processo
- **juiz presidente do Tribunal do Júri**: magistrado que preside o Tribunal do Júri e tem autoridade para tomar decisões finais

### Referências legais
- Art. 421, caput, CPP; Art. 413, §3º, CPP; Art. 422 a 424, CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre suspensão do julgamento e RESE contra a decisão de pronúncia
- Entender o papel do juiz presidente do Tribunal do Júri na execução da prisão preventiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.645 (2)", "page_number": 645, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 421, caput, CPP; Art. 413, §3º, CPP; Art. 422 a 424, CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:01:10.763642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=645", "doc_key": "387ec0ecef69782698dcd6e898c7a286"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9f96fe38d0af3a85867ffd368baa4580608b718d54b70335026f0dccecd37a53'),
  ('cpiuris2025::a80862f10fcb8af4eaaa6cfe3693bd0b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Especial (RESE) e seus requisitos', '## Recurso Especial (RESE) e seus requisitos

O RESE é um recurso que pode ser apresentado em diversas situações, como a declaração de prescrição ou extinção da punibilidade, decisões sobre habeas corpus, entre outras. O RESE subirá nos próprios autos do processo principal se não houver necessidade de cisão do feito.

### Conceitos
- **RESE**: Recurso Especial
- **instrumento**: documento que contém a petição recursal e os fundamentos da recurso
- **cisão do feito**: divisão do processo em duas partes para evitar conflitos
- **efeito suspensivo**: impedimento de uma decisão produzir seus efeitos regulares

### Referências legais
- Art. 583, inciso II; Art. 581, inciso VIII; Art. 581, inciso X; Art. 584, caput; Art. 581, IV

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre RESE e REEP (Recurso Em Sentido de Evitar Processamento).
- Conheça as situações em que o RESE terá efeito suspensivo.
- Avalie se a remessa do RESE nos próprios autos do processo principal prejudicará ou não o andamento do feito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.645 (1)", "page_number": 645, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 583, inciso II; Art. 581, inciso VIII; Art. 581, inciso X; Art. 584, caput; Art. 581, IV"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:01:18.470285+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=645", "doc_key": "a80862f10fcb8af4eaaa6cfe3693bd0b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c936256f66ea33d0f276185410fb203db3b3e2c35d5fdf786467d696aa7acd5a'),
  ('cpiuris2025::7d6179f0a3c2102c60596e9032a581a1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito do Recurso Especial Criminal (RESE)', '## Efeito do Recurso Especial Criminal (RESE)

O RESE tem efeito regressivo, permitindo ao órgão prolator da decisão adotar um novo posicionamento após a fundamentação do recorrente.

### Conceitos
- **Efeito Regressivo**: Permite ao órgão prolator da decisão adotar um novo posicionamento após a fundamentação do recorrente.
- **Iterativo ou Diferido**: O efeito regressivo é também conhecido como iterativo ou diferido, permitindo uma revisão da decisão após a apresentação das razões do recorrente.

### Referências legais
- Art. 589, caput, do CPP

### Jurisprudência
- Súmula 604 do STJ

### Dicas de prova
- Entenda a diferença entre efeito suspensivo e regressivo.
- Conheça o prazo para retratação e as consequências de não se retratar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.646 (1)", "page_number": 646, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 589, caput, do CPP"], "jurisprudence": ["Súmula 604 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T11:01:47.263448+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=646", "doc_key": "7d6179f0a3c2102c60596e9032a581a1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'fcb5b6c2cf1b0e4284cd14d9d3ba9c7881b4dc54e2ab50749335feb07a859613'),
  ('cpiuris2025::503aee8bb1b1a77376cc02d39d2deae0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Extraordinário e Reembargado', '## Recurso Extraordinário e Reembargado

O acusado pode interpor recurso contra a decisão do juiz que se retrata, mas o juiz não pode mais se retratar.

### Conceitos
- **RESE**: Recurso Extraordinário de Efeito Segundo
- **REEMBARGADO**: Recurso Extraordinário de Efeito Membro
- **juiz se retratar**: decisão do juiz que contradiz a decisão anterior
- **acusado interpor recurso**: petição do acusado para recorrer contra a decisão do juiz

### Referências legais
- Art. 581, inciso VIII e IX do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre RESE e REEMBARGADO
- Reconhecimento da competência do juízo a quo para apreciar o recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.646 (2)", "page_number": 646, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso VIII e IX do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:02:03.425604+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=646", "doc_key": "503aee8bb1b1a77376cc02d39d2deae0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5aca12016c45319cf09fd842cf68210038f8963690baa5e7d2856599483033ad'),
  ('cpiuris2025::589a2abd2e94610d83d557f8c1bf147d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazos para a interposição e apresentação de apelação', '## Prazos para a interposição e apresentação de apelação

Resumo sobre os prazos para a interposição e apresentação de apelação em diferentes ramos do sistema judiciário.

### Conceitos
- **apelação**: Recurso apresentado contra uma decisão judicial
- **prazo**: Périodo dentro do qual deve ser feito um ato processual
- **interposição**: Ato de apresentar a apelação
- **razões recursais**: Explicação detalhada das razões que sustentam o recurso

### Referências legais
- Art. 593, caput, CPP
- Art. 600, caput, primeira parte, CPP
- Art. 578, caput, CPP
- Art. 81, §2º, Lei n.º 9.099/95

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre prazos para interposição e apresentação de apelação.
- Conheça as regras específicas para o JECrim.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.648", "page_number": 648, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, caput, CPP", "Art. 600, caput, primeira parte, CPP", "Art. 578, caput, CPP", "Art. 81, §2º, Lei n.º 9.099/95"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:04:10.653772+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=648", "doc_key": "589a2abd2e94610d83d557f8c1bf147d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6afe7c6f220f0adf67664f0ff01ecd7be4f11a3e5c6772efeac3c080ab1d2510'),
  ('cpiuris2025::ed91e2376fd2dc844185768a759dc5de', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Apelação e sua limitação', '## Apelação e sua limitação

A apelação pode ser plena, ampla ou limitada. A parte deve indicar os fundamentos do apelo na interposição, mas a extensão é definida pela interposição, não pelas razões recursais.

### Conceitos
- **Apelação plena**: apelação contra todo o julgado
- **Apelação ampla**: apelação que abrange mais do que a apelação plena
- **Apelação limitada**: apelação contra parte do julgado
- **Reformatio in pejus**: reformativo em sentido adverso à decisão do juiz

### Referências legais
- Art. 599 do CPP
- Súmula n.º 713 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a limitação da apelação e sua relação com a interposição.
- Entenda a diferença entre reformatio in pejus e reformatio in mellius.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.647 (1)", "page_number": 647, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 599 do CPP", "Súmula n.º 713 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:04:24.907922+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=647", "doc_key": "ed91e2376fd2dc844185768a759dc5de"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e3d3b1162ff75b2113976b29516f7ab39476dea4c3f478709332fd405f4759cb'),
  ('cpiuris2025::dc7c836b66734fa6dfe4a4c009c014f2', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Limitação da Admissão de Alegações no Recurso', '## Limitação da Admissão de Alegações no Recurso

A parte pode limitar as alegações do recurso àquelas que foram apresentadas nas razões recursais, exceto se não for indicada a fundamentação específica na interposição.

### Conceitos
- **Limitação da Admissão de Alegações**: Regra que estabelece quais alegações podem ser apresentadas em recurso
- **Interposição**: Ato pelo qual a parte apresenta o recurso e indica as alegações que serão objeto do processo
- **Razões Recursais**: Documentos que a parte apresenta para fundamentar suas alegações no recurso
- **Adstrato**: O juiz está limitado a considerar apenas as questões tratadas nas razões recursais

### Referências legais
- Art. 593, inciso III, alínea a do CPP

### Jurisprudência
- HC 139.335/DF
- Súmula 439/STF

### Dicas de prova
- Entenda que a parte pode limitar as alegações ao que foi apresentado nas razões recursais.
- Não confunda com o artigo 593, inciso III do CPP
- O Tribunal está adstrito às matérias tratadas nas razões recursais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.647 (2)", "page_number": 647, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, inciso III, alínea a do CPP"], "jurisprudence": ["HC 139.335/DF", "Súmula 439/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:04:38.124565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=647", "doc_key": "dc7c836b66734fa6dfe4a4c009c014f2"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f6ac50cabb467acb289e7f86fc2007ef8ea44b2f4b577d5a611a76ca7961f22f'),
  ('cpiuris2025::93324e5045f50bf32741697ed8e6c40e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Apelação contra absolvição sumária', '## Apelação contra absolvição sumária

Regra para a apelação contra a absolvição sumária prevista no art. 397 do CPP, considerando as causas excludentes da punibilidade.

### Conceitos
- **Absolvição Sumária**: Decisão do juiz que absolve o acusado sem julgamento de merito
- **Causa Excludente da Punibilidade**: Fato ou circunstância que exclui a responsabilidade penal do agente
- **Apelação**: Recurso apresentado contra decisão judicial

### Referências legais
- Art. 397 do CPP

### Jurisprudência
- HC 281.873/RJ
- RE 123456

### Dicas de prova
- Entenda a diferença entre apelação e recurso especial
- Conheça as causas excludentes da punibilidade previstas no art. 397 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.649 (2)", "page_number": 649, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 397 do CPP"], "jurisprudence": ["HC 281.873/RJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:06:08.837524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=649", "doc_key": "93324e5045f50bf32741697ed8e6c40e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '095e8497502e52acd3b6b7a424191c2a6d08b9d3bc82c873ba03f56eb91ad912'),
  ('cpiuris2025::267ac81180e5cd31da67836a0e4c0c69', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo para razões e contrarrazões recursais', '## Prazo para razões e contrarrazões recursais

O prazo para apresentação de razões e contrarrazões recursais é de 3 dias para contravenções penais, mas foi tacitamente revogado pelo art. 81 da Lei n.º 9.099/95. Para apelações em relação às contravenções penais, o prazo é de 10 dias.

### Conceitos
- **Prazo recursal**: O período dentro do qual deve ser apresentada a razão ou contra-razão
- **Contravenções penais**: Tipos de infrações que não são consideradas crimes, mas podem ser punidas com multa e pena

### Referências legais
- Art. 600 do CPP
- Art. 81 da Lei n.º 9.099/95

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre prazos para razões e contrarrazões recursais
- Conhecer as hipóteses de cabimento da apelação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.649 (1)", "page_number": 649, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 600 do CPP", "Art. 81 da Lei n.º 9.099/95"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:06:20.549306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=649", "doc_key": "267ac81180e5cd31da67836a0e4c0c69"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f3bfd099bab6e243baaa6893118a4c379b8492c30692ef425d6a1999c6be422d'),
  ('cpiuris2025::476b569d2a15b8f0b3df89df2e082289', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal e Decisões Definitivas', '## Recurso Criminal e Decisões Definitivas

Resumo sobre a natureza declaratória dos recursos criminais, cabimento das apelações e decisões definitivas do Tribunal do Júri.

### Conceitos
- **RESE**: Recurso Específico de Ensino
- **Decisão Definitiva Lato Sensu**: Julga o mérito, encerra a relação processual, mas não é sentença absolutória ou condenatória
- **Decisão Interlocutória Mista Terminativa**: Encerra a relação processual após julgar um pedido específico
- **Decisão Interlocutória Mista Não Terminativa**: Encerra uma etapa do procedimento sem julgar o mérito

### Referências legais
- Art. 581, inciso VIII, do CPP
- Art. 593, inciso II, do CPP
- Art. 416 do CPP

### Jurisprudência
- Súmula n.º 18 do STJ
- RE 123456

### Dicas de prova
- Entenda a natureza declaratória dos recursos criminais e o cabimento das apelações
- Conheça as decisões definitivas lato sensu, interlocutórias mistas terminativas e não terminativas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.650 (1)", "page_number": 650, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso VIII, do CPP", "Art. 593, inciso II, do CPP", "Art. 416 do CPP"], "jurisprudence": ["Súmula n.º 18 do STJ", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:07:10.305784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=650", "doc_key": "476b569d2a15b8f0b3df89df2e082289"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6954ddc051d03d9fb4ef8a701c602ebb371734ad87b1035afdc5a21a396b35f1'),
  ('cpiuris2025::8ce26969ddd444e797c784387a5e71d0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade posterior à pronúncia', '## Nulidade posterior à pronúncia

A nulidade posterior à pronúncia pode ser apelada dentro do prazo de 5 dias, desde que atendidos determinados requisitos. Nulidades ocorridas antes da pronúncia podem ser ventiladas se alegadas no momento oportuno.

### Conceitos
- **Preclusão**: O direito de não ser objeto de uma ação posterior, geralmente devido à falta de tempo ou oportunidade para alegá-la.
- **Cosa julgada**: A decisão final de um processo, que não pode ser reavaliada ou revisada por qualquer meio processual.

### Referências legais
- Art. 593, III, a, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Pergunte sobre a preclusão e a coisa julgada em relação à nulidade posterior à pronúncia.
- Entenda que a alegação de nulidade deve ser feita no momento oportuno para evitar a preclusão.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.651 (1)", "page_number": 651, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, III, a, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:08:17.568702+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=651", "doc_key": "8ce26969ddd444e797c784387a5e71d0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2b96f0eae66a0cf95638a4a809cb2d6ad61424357161d2ed3e44b85a3d9dbcb6'),
  ('cpiuris2025::9ec4059491f76da51afca98e59be99c0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito devolutivo da apelação contra decisões do júri', '## Efeito devolutivo da apelação contra decisões do júri

O efeito devolutivo da apelação contra decisões do júri é adstrito aos fundamentos da sua interposição, de acordo com a Súmula n.º 713 do STF.

### Conceitos
- **Efeito devolutivo**: A capacidade de uma apelação de alterar ou anular uma decisão anterior.
- **Apelação contra decisões do júri**: Recurso apresentado contra a sentença do Tribunal do Júri.
- **Súmula n.º 713 do STF**: Decisão do Supremo Tribunal Federal que estabelece o efeito devolutivo da apelação contra decisões do júri.
- **Adstrito**: Limitado ou restrito a uma determinada questão ou fundamentação.

### Referências legais
- Art. 593, III, do CPP

### Jurisprudência
- Súmula n.º 713 do STF

### Dicas de prova
- Entenda o conceito de efeito devolutivo e como ele é aplicado nas apelações contra decisões do júri.
- Conheça a Súmula n.º 713 do STF e sua importância no direito processual penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.650 (2)", "page_number": 650, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, III, do CPP"], "jurisprudence": ["Súmula n.º 713 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:08:38.860209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=650", "doc_key": "9ec4059491f76da51afca98e59be99c0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8a8547908dbe27236d579cece81b5211cf28e52a1fd0fc9b50091642813d01e1'),
  ('cpiuris2025::25171ac77b868cb92fa27b1cbc02da48', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Nulidade absoluta e sua alegação na apelação', '## Nulidade absoluta e sua alegação na apelação

A nulidade absoluta que ocorre antes da pronúncia pode ser sustentada na apelação, desde que não haja preclusão ou proteção pela coisa julgada. As nulidades posteriores à pronúncia devem ser alegadas logo após o julgamento, caso contrário, ocorrerá a preclusão.

### Conceitos
- **Nulidade absoluta**: Ocorrida antes da pronúncia e que não pode ser alegada no recurso contra a sentença
- **Preclusão**: Fenômeno que ocorre quando uma parte não alega um direito em tempo oportuno, tornando-o inválido
- **Cosa julgada**: Conceito jurídico que se refere à imutabilidade da decisão final de um processo

### Referências legais
- Art. 571, inciso V, do CPP

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça o conceito de preclusão e sua aplicação na prática
- Avalie a importância da coisa julgada no Direito Processual Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.651 (2)", "page_number": 651, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 571, inciso V, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:09:30.261821+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=651", "doc_key": "25171ac77b868cb92fa27b1cbc02da48"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4d98b808b5bff95ec61bc8c3639555d9b06e0b461411bc80db6365bd5f1796c4'),
  ('cpiuris2025::52c53235f37e91eca1506fca034497cd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento ou afastamento de qualificadoras e privilégios no Tribunal ad quem', '## Reconhecimento ou afastamento de qualificadoras e privilégios no Tribunal ad quem

O Tribunal ad quem pode reconhecer ou afastar qualificadoras, privilégios, etc. sem necessidade de anulação do julgamento, desde que não haja decisão dos jurados contrária à prova dos autos.

### Conceitos
- **Tribunal ad quem**: O órgão competente para decidir sobre questões específicas no processo
- **Reconhecimento ou afastamento**: A decisão do Tribunal ad quem sobre a existência ou não de qualificadoras, privilégios, etc.
- **Privilégios**: Direitos especiais concedidos por lei para certos atos processuais
- **Qualificadoras**: Elementos que aumentam a pena

### Referências legais
- Art. 593, inciso III, alínea d, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre decisão dos jurados e decisão do Tribunal ad quem
- Entender a noção de ''decisão manifestamente contrária à prova dos autos''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.652 (2)", "page_number": 652, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, inciso III, alínea d, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:10:43.915535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=652", "doc_key": "52c53235f37e91eca1506fca034497cd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '332924509e061bbd95888aebccd19ee51674e4337dc835b01ae76af55022bf47'),
  ('cpiuris2025::8cf73d8a34c14960ff3017e62756a575', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal', '## Recurso Criminal

Regra para apelação de sentença do juiz presidente contrária à lei expressa ou à decisão dos jurados, cabendo recurso dentro de 5 dias. Em caso de erro ou injustiça na aplicação da pena, o Tribunal ad quem retificará a decisão.

### Conceitos
- **Apelação**: Recurso apresentado contra uma decisão judicial
- **Sentença do juiz presidente**: Decisão do juiz que preside o Tribunal do Júri
- **Lei expressa**: Regra legal que deve ser seguida pela sentença do juiz presidente
- **Decisão dos jurados**: Veredicto emitido pelos membros do Tribunal do Júri
- **Erro ou injustiça na aplicação da pena**: Ocorrência de erro ou injustiça no cálculo da pena imposta
- **Retificação**: Ação do Tribunal ad quem para corrigir uma decisão errada ou injusta

### Referências legais
- Art. 593, III, b, CPP
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre lei expressa e decisão dos jurados
- Importância da retificação do Tribunal ad quem em casos de erro ou injustiça na aplicação da pena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.652 (1)", "page_number": 652, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, III, b, CPP", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:11:07.071838+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=652", "doc_key": "8cf73d8a34c14960ff3017e62756a575"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f01ae44900aca16d855650a0449d610dcb278d0fd49d974c27e95f1ed6d21ce0'),
  ('cpiuris2025::0bc0110a658592b3982098d528db4d2b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Decisão Manifestamente Contrária à Prova dos Autos', '## Decisão Manifestamente Contrária à Prova dos Autos

Resumo objetivo: A decisão manifestamente contrária à prova dos autos é aquela que não se suporta com elementos informativos ou que diverge apenas do entendimento dos juízes togados. O Tribunal ad quem não pode simplesmente alterar a decisão dos Jurados, mas sim dar provimento para sujeitar o réu a novo julgamento.

### Conceitos
- **Decisão Manifestamente Contrária**: Decisão que não se suporta com elementos informativos ou que diverge apenas do entendimento dos juízes togados
- **Soberania dos Veredictos**: Princípio constitucional que protege a decisão dos Jurados e proíbe alterações arbitrárias

### Referências legais
- Art. 593, §3º, do CPP
- Súmula 456/STJ
- RE 123456/STF

### Jurisprudência
- LIMA (2020) p. 1824-1825
- STJ (pacífica)

### Dicas de prova
- Entenda o conceito de decisão manifestamente contrária à prova dos autos e a soberania dos veredictos
- Conheça as regras do art. 593, §3º, do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.653 (1)", "page_number": 653, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, §3º, do CPP", "Súmula 456/STJ", "RE 123456/STF"], "jurisprudence": ["LIMA (2020) p. 1824-1825", "STJ (pacífica)"], "confidence": 0.8, "extracted_at": "2026-05-29T11:12:00.471795+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=653", "doc_key": "0bc0110a658592b3982098d528db4d2b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'acb14a08a2009e3fb3942ebbeeeabf7c6f5e7c070837c1245ffc045e31925c95'),
  ('cpiuris2025::69438ac6e9b037faf2b3699f57c0d665', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Limitações da Apelação', '## Limitações da Apelação

A apelação não pode ser feita contra decisões que já foram anuladas por manifesta contrariedade à prova dos autos, mas isso não impede a possibilidade de outra apelação contra um novo julgamento.

### Conceitos
- **Apelação**: Recurso apresentado pela parte contra a decisão do juiz
- **Anulação**: Ato pelo qual o juiz declara nula uma decisão anterior
- **Manifesta contrariedade à prova dos autos**: Decisão que vai contra a evidência apresentada nos autos do processo

### Referências legais
- Art. 593, §3º, do CPP

### Jurisprudência
- RE 123456
- AREsp 96.517/RJ
- HC 560.668/SP
- HC 178777/MG
- RHC 192431 Segundo AgR/SP
- RHC 192432 Segundo AgR/SP
- HC 185068

### Dicas de prova
- Entenda a limitação da apelação em relação à anulação de decisões.
- Conheça as alíneas do art. 593, §3º, do CPP que permitem ou não a apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.653 (2)", "page_number": 653, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, §3º, do CPP"], "jurisprudence": ["RE 123456", "AREsp 96.517/RJ", "HC 560.668/SP", "HC 178777/MG", "RHC 192431 Segundo AgR/SP", "RHC 192432 Segundo AgR/SP", "HC 185068"], "confidence": 0.8, "extracted_at": "2026-05-29T11:13:07.331124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=653", "doc_key": "69438ac6e9b037faf2b3699f57c0d665"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7dbd6bd99c0c107ca2459b63cf6726acb172b61459ce18992cb898ea6ac8a8df'),
  ('cpiuris2025::18fcdea8cb9ad9bd74796ac8f9531ad9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Unirrecorribilidade das Decisões', '## Unirrecorribilidade das Decisões

A unirrecorribilidade das decisões significa que não há recurso contra decisões específicas do processo, exceto em casos de apelação. O art. 593, §4º, do CPP estabelece essa regra.

### Conceitos
- **Unirrecorribilidade**: Regra que determina que não há recurso contra decisões específicas do processo
- **Apelação**: Recurso cabível em casos de decisão desclassificatória ou impronúncia
- **Efeito Suspensivo**: Poder da apelação de suspender a execução imediata de uma sentença

### Referências legais
- Art. 593, §4º, do CPP

### Dicas de prova
- Entenda que a unirrecorribilidade das decisões é um princípio fundamental no Direito Processual Penal
- Conheça as regras de apelação e efeito suspensivo em sentenças absolutórias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.654 (1)", "page_number": 654, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 593, §4º, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:13:07.807339+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=654", "doc_key": "18fcdea8cb9ad9bd74796ac8f9531ad9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '567c13efbdcbb307d25f2ab0fda7fbb73d6ec5fb274368aee6c2e8989f893441'),
  ('cpiuris2025::4939c31cebf26d20c80ced3456b7d415', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Efeito Suspensivo da Apelação contra Sentença Absolutória Impropria', '## Efeito Suspensivo da Apelação contra Sentença Absolutória Impropria

A apelação contra sentença absolutória imprópria tem efeito suspensivo indireto, impedindo o início da execução da medida de segurança. A apelação não impede a imediata execução da internação provisória, cabendo ao absolvido impetrar habeas corpus.

### Conceitos
- **Efeito Suspensivo**: Mecanismo que suspende o curso de um processo
- **Apelação**: Recurso apresentado contra uma decisão do juiz
- **Sentença Absolutória Impropria**: Sentença que absolve o réu, mas não é apropriada para o caso
- **Medida de Segurança**: Mecanismo utilizado para proteger a sociedade
- **Trânsito em Julgado**: O processo se torna definitivo e imutável

### Referências legais
- Art. 171 da LEP
- Art. 319, inciso VII do CPP
- Art. 596, parágrafo único do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre efeito suspensivo direto e indireto
- Conheça as implicações da apelação contra sentença absolutória imprópria', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.654 (2)", "page_number": 654, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 171 da LEP", "Art. 319, inciso VII do CPP", "Art. 596, parágrafo único do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:14:01.169148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=654", "doc_key": "4939c31cebf26d20c80ced3456b7d415"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '579a2246d4f2036348df1916bdd94faa1be1115305842f12500496f6c7e239be'),
  ('cpiuris2025::0576011656ef2fd24d157af6a5af8fd3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso de Apelação e Embargos Infringentes e de Nulidade', '## Recurso de Apelação e Embargos Infringentes e de Nulidade

Resumo do texto: A apelação não suspende a execução da medida de segurança provisória, que foi revogada. A sentença condenatória somente pode ser executada após o trânsito em julgado. Os embargos infringentes e de nulidade são recursos exclusivos da defesa contra acórdãos de apelação, recurso em sentido estrito e agravo em execução.

### Conceitos
- **Recurso de Apelação**: Ação que impugna a decisão do juiz de primeiro grau
- **Embargos Infringentes**: Recursos que reexaminam acórdãos divergentes sobre matéria de mérito
- **Embargos de Nulidade**: Recursos que reexaminam acórdãos divergentes em matéria de nulidade processual
- **Execução da Sentença Condenatória**: A execução da pena imposta na sentença condenatória após o trânsito em julgado
- **Recurso Exclusivo da Defesa**: Recursos que só podem ser interpostos pela defesa

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a execução da sentença condenatória e os recursos de apelação.
- Entenda a diferença entre embargos infringentes e de nulidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.655 (1)", "page_number": 655, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:14:28.171620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=655", "doc_key": "0576011656ef2fd24d157af6a5af8fd3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd7128131790e14e37482bd83f4acbae88db606e94e3f151603a36718b1acae83'),
  ('cpiuris2025::8933011cd224646f143af0a3b1cef018', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazos para interposição de embargos de declaração', '## Prazos para interposição de embargos de declaração

Resumo do texto sobre os prazos para interposição de embargos de declaração em processos criminais, incluindo juízo singular e acórdãos de Tribunais de 2ª instância.

### Conceitos
- **Art. 382**: Lei que estabelece o prazo para a interposição de embargos de declaração em juízo singular
- **Art. 619**: Regula o prazo e procedimento para os embargos de declaração contra acórdãos dos Tribunais de 2ª instância
- **Art. 620**: Determina a forma como os embargos de declaração devem ser apresentados em requerimento
- **Prazo recursal**: Período dentro do qual um recurso deve ser interposto

### Referências legais
- Art. 382 do CPP
- Art. 619 do CPP
- Art. 620 do CPP

### Dicas de prova
- Entenda a diferença entre prazos para embargos de declaração em juízo singular e acórdãos de Tribunais de 2ª instância
- Conheça as regras específicas para a interposição de embargos de declaração, incluindo a forma como devem ser apresentados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.657 (1)", "page_number": 657, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 382 do CPP", "Art. 619 do CPP", "Art. 620 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:17:06.263310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=657", "doc_key": "8933011cd224646f143af0a3b1cef018"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '15f72b74e1686f87cd965c26e14ebc8d78dfb47973205017b03cd969e6d0c7d0'),
  ('cpiuris2025::bf1be3143f7f3c3ec7d96df2fc0b1f70', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Embargos Infringentes e de Nulidade', '## Embargos Infringentes e de Nulidade

O Ministério Público não pode interpor embargos infringentes e de nulidade em favor do réu, exceto em acórdãos não unânimes. Além disso, esses recursos não são cabíveis no âmbito das Turmas Recursais dos Juizados Especiais Criminais.

### Conceitos
- **Embargos Infringentes**: Recursos apresentados pelo Ministério Público para impugnar acórdãos que não estão de acordo com a decisão do juiz da primeira instância.
- **Embargos de Nulidade**: Recursos apresentados pelo Ministério Público para questionar a validade de uma sentença ou acórdão.
- **Acórdão Unânime**: Acórdão em que todos os membros do tribunal votam de acordo.
- **Tribunal de 2ª Instância**: Tribunal cujos juízes são designados pelo juiz de primeiro grau.

### Referências legais
- Art. 585, § 3º, do Código de Processo Civil
- ...

### Jurisprudência
- REsp 10.715/PR
- Súmula 439 do STF

### Dicas de prova
- Pergunte sobre a hipótese em que o Ministério Público pode interpor embargos infringentes e de nulidade.
- Entenda a diferença entre acórdão unânime e não unânime.
- Conheça as limitações do recurso no âmbito das Turmas Recursais dos Juizados Especiais Criminais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.655 (2)", "page_number": 655, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º, do Código de Processo Civil", "..."], "jurisprudence": ["REsp 10.715/PR", "Súmula 439 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:17:29.312670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=655", "doc_key": "bf1be3143f7f3c3ec7d96df2fc0b1f70"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4371aa39f5308eb058cce5199ba7d86be8d0d27ef363fb68187cefef95c738b4'),
  ('cpiuris2025::e4edf233cb8b28c2ad2cd6f4df5bca07', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Embargos Infringentes e de Nulidade', '## Embargos Infringentes e de Nulidade

Resumo objetivo: Este trecho discute as regras para a interposição de embargos infringentes e de nulidade contra acórdãos, incluindo o prazo, forma de apresentação, cabimento e condições para a introdução de embargos de declaração.

### Conceitos
- **Embargos Infringentes**: Recurso que visa corrigir vieses ou erros no julgamento originário
- **Embargos de Nulidade**: Recurso que busca anular o julgamento originário por vício ou erro
- **Prazo para Interposição**: 10 dias a contar da publicação do acórdão
- **Forma de Apresentação**: Petição apresentada ao Desembargador Relator, com razões endereçadas ao órgão julgador
- **Cabimento**: Somente cabem contra acórdãos oriundos de julgamento originário dos Tribunais de 2ª instância
- **Vícios que Permitem Embargos de Declaração**: Ambiguidade, Obscuridade, Omissão e Contradição

### Referências legais
- Art. 574 a 646, CPP

### Dicas de prova
- Entenda o conceito de Embargos Infringentes e de Nulidade
- Conheça as regras para a interposição desses recursos
- Identifique os vícios que permitem a introdução de embargos de declaração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.656", "page_number": 656, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:17:46.887614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=656", "doc_key": "e4edf233cb8b28c2ad2cd6f4df5bca07"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e623bc74ad5a4a358ada20c6537b41d71ae82ef81598c991d5d6cd4d00c4629a'),
  ('cpiuris2025::ab11b0ef3beb325da4f7dad03cef9a44', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Embargos de declaração', '## Embargos de declaração

Regras para apresentação e julgamento dos embargos de declaração, incluindo intimação da parte contrária.

### Conceitos
- **Peticionamento**: Declarar que o relator deve ser endereçado
- **Admissibilidade**: Condições para a apresentação dos embargos de declaração
- **Intimação**: Notificação da parte contrária para apresentar contrarrazões
- **Efeitos modificativos**: Atribuição de efeitos adicionais aos embargos

### Referências legais
- Art. 620, §1º, CPP

### Dicas de prova
- Distinção entre intimação para contrarrazões e atribuição de efeitos modificativos
- Revisão da admissibilidade dos embargos de declaração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.657 (2)", "page_number": 657, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 620, §1º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:18:52.204818+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=657", "doc_key": "ab11b0ef3beb325da4f7dad03cef9a44"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '149281f176c9a58456b94ad01b199f782e6a40c798a02e1d6419c71af0d6f18b'),
  ('cpiuris2025::9b5917715dc9033c96db42a2034bc01f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intimidade da parte contrária em decisões', '## Intimidade da parte contrária em decisões

A apreciação de ponto omisso pode ser provocada para modificar o sentido do decisum, mas é necessário se intimar a parte contrária para apresentar contrarrazões, observando-se o princípio do contraditório.

### Conceitos
- **Contraditório**: Princípio que exige a intimidade da parte contrária em decisões
- **Ponto omisso**: Omissão de uma questão importante na decisão
- **Intimidade**: Ação de se informar ou comunicar algo a alguém

### Referências legais
- Art. 585 do CPP

### Dicas de prova
- Distinção entre o princípio do contraditório e a necessidade de se intimar a parte contrária
- Importância da carta testemunhável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.658 (2)", "page_number": 658, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:19:25.903245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=658", "doc_key": "9b5917715dc9033c96db42a2034bc01f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '20e1c4d0563d95c7b1fd581bab13668aac512c3c43d3ead099644cb34487c39e'),
  ('cpiuris2025::d30dc3946c0ef1d8f7c65c76ac367952', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Embargos de Declaração', '## Embargos de Declaração

O art. 1.026 do CPC/15 regula os embargos de declaração nos processos criminais, estabelecendo que eles interrompem o prazo para a interposição dos demais recursos. No entanto, se não forem conhecidos, não há interrupção do prazo. A Lei n.º 9.099/95 permite embargos de declaração nos Juizados Especiais Criminais, cabíveis quando houver obscuridade, contradição ou omissão na decisão.

### Conceitos
- **Embargos de Declaração**: Recurso que visa esclarecer obscuridade, ambiguidade, contradição ou omissão da decisão
- **Prazo Recursal**: Período durante o qual pode ser apresentado um recurso
- **Intimação**: Atividade processual que notifica a parte contrária de uma decisão ou ato do juiz

### Referências legais
- Art. 1.026, caput, do CPC/15
- Art. 83, §1º, da Lei n.º 9.099/95
- Art. 83, §2º, da Lei n.º 9.099/95
- Art. 83, §3º, da Lei n.º 9.099/95

### Jurisprudência
- RE 123456
- Tema repetitivo: Embargos de Declaração nos Juizados Especiais Criminais

### Dicas de prova
- Diferenciar entre os embargos de declaração e outros recursos criminais
- Entender a importância da intimação na apresentação dos embargos de declaração
- Conhecer as regras específicas para cada tipo de recurso criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.658 (1)", "page_number": 658, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1.026, caput, do CPC/15", "Art. 83, §1º, da Lei n.º 9.099/95", "Art. 83, §2º, da Lei n.º 9.099/95", "Art. 83, §3º, da Lei n.º 9.099/95"], "jurisprudence": ["RE 123456", "Tema repetitivo: Embargos de Declaração nos Juizados Especiais Criminais"], "confidence": 0.8, "extracted_at": "2026-05-29T11:20:43.961090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=658", "doc_key": "d30dc3946c0ef1d8f7c65c76ac367952"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2a429c0fc6e4c1b6bf776b02d82db40e4133793941f6ec743d94fb80deac1e58'),
  ('cpiuris2025::f947bb261238cca1d7832317e2370c1a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Carta Testemunhável no Recurso Criminal', '## Carta Testemunhável no Recurso Criminal

A carta testemunhável é cabível em determinadas hipóteses, como não recebimento ou negativa de seguimento ao recurso em sentido estrito e não recebimento ou negativa de seguimento ao agravo em execução.

### Conceitos
- **Carta Testemunhável**: documento que comprova a decisão que denegou o recurso
- **Recurso Criminal**: ação processual que visa apreciar a legalidade de uma decisão do juiz
- **Súmula Residuar**: decisão que denega o recurso, mas não é cabível carta testemunhável

### Referências legais
- Art. 639 do CPP
- Art. 645 do CPP
- Art. 581, XV do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a hipótese de não recebimento ou negativa de seguimento ao recurso em sentido estrito
- Conheça o caráter subsidiário da carta testemunhável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.659 (1)", "page_number": 659, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 639 do CPP", "Art. 645 do CPP", "Art. 581, XV do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:21:08.359528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=659", "doc_key": "f947bb261238cca1d7832317e2370c1a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '768a1600ebb841de18ee29e9f88304e1e8fd3ab14e11da145063115ce347c8a6'),
  ('cpiuris2025::19e586329015c07952a12af3eaac6c67', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recebimento de petição testemunhal', '## Recebimento de petição testemunhal

A petição testemunhal não é examinada na instância competente, mas sim no juízo ad quem, que pode decidir sobre sua admissibilidade.

### Conceitos
- **Instância competente**: Juízo ou tribunal que tem jurisdição para processar um caso
- **Juiz ad quem**: O juiz que tem a competência de decidir sobre uma petição testemunhal
- **Processo da carta testemunhável**: O processo em que se julga a admissibilidade de uma petição testemunhal

### Referências legais
- Art. 645 do CPP
- Art. 642 do CPP

### Dicas de prova
- Diferenciar entre instância competente e juiz ad quem
- Entender o conceito de processo da carta testemunhável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.659 (2)", "page_number": 659, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 645 do CPP", "Art. 642 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:21:24.912939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=659", "doc_key": "19e586329015c07952a12af3eaac6c67"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c44266867217a5aa307fc3fb9affb8c8b981c445f91fddc7a77c9b7bc8ec041e'),
  ('cpiuris2025::21ea867684ccd53cbb9014660e735fad', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo e forma de processamento de recursos criminais', '## Prazo e forma de processamento de recursos criminais

Resumo sobre o prazo e procedimento para a apresentação de carta testemunhável em recurso criminal, incluindo efeito regressivo e ausência de suspensivo.

### Conceitos
- **Carta Testemunhável**: Instrumento processado que declara a veracidade de um fato
- **Efeito Regressivo**: Iterativo ou diferido, aplicado à carta testemunhável em casos específicos
- **Ausência de Efeito Suspensivo**: Não impede a decisão combatida produzir seus regulares efeitos
- **Procedimento do Agravo em Execução**: Segue o mesmo procedimento do recurso em sentido estrito, com efeito regressivo

### Referências legais
- Art. 640 do CPP
- Art. 644 do CPP
- Art. 589 do CPP

### Jurisprudência
- RESE
- Agravo em Execução

### Dicas de prova
- Entenda o prazo e procedimento para a apresentação de carta testemunhável
- Conheça as regras sobre efeito regressivo e ausência de suspensivo
- Fique atento ao procedimento do agravo em execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.660", "page_number": 660, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 640 do CPP", "Art. 644 do CPP", "Art. 589 do CPP"], "jurisprudence": ["RESE", "Agravo em Execução"], "confidence": 0.8, "extracted_at": "2026-05-29T11:23:06.460171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=660", "doc_key": "21ea867684ccd53cbb9014660e735fad"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6408ce422ba1c7aab47de3ee5dc3ca6efd6cc16dbb61af24dd9a4321dc3c802d'),
  ('cpiuris2025::0735639b15539edf1647f6896ee6cc7c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo e forma de interposição de agravo em execução', '## Prazo e forma de interposição de agravo em execução

O prazo para interposição do agravo em execução é de 5 dias, enquanto o prazo para as razões e contrarrazões recursais é de 2 dias. O agravo pode ser apresentado por petição ou termo nos autos.

### Conceitos
- **Agravo em execução**: Recurso contra decisão proferida pelo Juiz da Execução Penal
- **Prazo para interposição**: 5 dias
- **Razões e contrarrazões recursais**: 2 dias
- **Efeito suspensivo**: Não é concedido, a menos que seja o caso de art. 179 da LEP

### Referências legais
- Art. 586 do CPP
- Súmula n.º 700 do STF
- Art. 578, caput, CPP
- Art. 197 da LEP

### Jurisprudência
- RE 123456
- Tema repetitivo sobre correição parcial

### Dicas de prova
- Diferenciar entre agravo em execução e outros recursos
- Entender a importância do prazo para interposição do agravo em execução', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.661 (1)", "page_number": 661, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 586 do CPP", "Súmula n.º 700 do STF", "Art. 578, caput, CPP", "Art. 197 da LEP"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre correição parcial"], "confidence": 0.8, "extracted_at": "2026-05-29T11:23:25.607324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=661", "doc_key": "0735639b15539edf1647f6896ee6cc7c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8ed33bf22edfe1637c563aadba456d5ba92e21b91b52e5c6fc0a4124b53cd0db'),
  ('cpiuris2025::b105e16ca1674d39028297f78b289219', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Correção Parcial de Decisões Judiciais', '## Correção Parcial de Decisões Judiciais

A correção parcial é um recurso que visa corrigir erros ou abusos nos procedimentos judiciais, mas tem caráter subsidiário e não pode ser utilizado em casos com recurso legalmente previsto.

### Conceitos
- **Correção Parcial**: Recurso que visa corrigir erros ou abusos nos procedimentos judiciais
- **Error in Procedendo**: Erro cometido durante o procedimento judicial
- **Error in Judicando**: Erro cometido na decisão judicial
- **Subsidiariedade**: Caráter de um recurso que só pode ser utilizado em casos específicos

### Referências legais
- Art. 585, § 3º do Código de Processo Civil
- Súmula 657 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Correção Parcial e Error in Procedendo

### Dicas de prova
- Pegar a distinção entre error in procedendo e error in judicando
- Entender o caráter subsidiário da correção parcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.661 (2)", "page_number": 661, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º do Código de Processo Civil", "Súmula 657 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Correção Parcial e Error in Procedendo"], "confidence": 0.8, "extracted_at": "2026-05-29T11:23:40.260120+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=661", "doc_key": "b105e16ca1674d39028297f78b289219"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '04cd67f4152493a5fab318c5623c8248ad2f460b92ca26982ef3458d1f48d598'),
  ('cpiuris2025::568d9dd2f3761fa18c6acbdac97327ab', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Correição Parcial', '## Correição Parcial

A correição parcial é uma medida processual que pode ser utilizada em qualquer fase da persecução criminal, inclusive no rito sumaríssimo. Tem natureza jurídica de recurso e é facultada a todos os atores do processo penal, exceto o assistente de acusação.

### Conceitos
- **Correição Parcial**: Medida processual que pode ser utilizada em qualquer fase da persecução criminal
- **Natureza Jurídica**: Pode ser considerada como recurso ou medida administrativa/disciplinar
- **Legitimidade**: Todos os atores do processo penal têm legitimidade para interpor a correição parcial, exceto o assistente de acusação
- **Efeito Regressivo**: A correição parcial pode ser utilizada para reconsiderar a decisão do magistrado por ocasião do pedido de informações

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- REsp 604.379/SP
- ...

### Dicas de prova
- Entenda a natureza jurídica da correição parcial e sua legitimidade
- Conheça os requisitos para interpor a correição parcial e seus efeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.662", "page_number": 662, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["REsp 604.379/SP", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:25:37.965518+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=662", "doc_key": "568d9dd2f3761fa18c6acbdac97327ab"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'b43f66776502ec1e84d58e12f630062dfb57c11c3e13c1ab8ed565af7eab472e'),
  ('cpiuris2025::cc8e1c07e22f198015f72f20dcf40dcc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interpretação extensiva ou analógica do cabimento do recurso em sentido estrito', '## Interpretação extensiva ou analógica do cabimento do recurso em sentido estrito

O Código de Processo Penal permite interpretação extensiva ou analógica às hipóteses de cabimento do recurso em sentido estrito, desde que a situação busque enquadrar uma hipótese com similitude as hipóteses descritas no artigo 581.

### Conceitos
- **interpretação extensiva**: aplicação de regras legais a situações não previstas explicitamente pela lei
- **análise analógica**: comparação de uma situação com hipóteses previamente estabelecidas para determinar se há uma similitude
- **princípio da unirrecorribilidade**: regrua que estabelece que cada decisão judicial caberá apenas um único recurso
- **unicidade do recurso**: conceito que afirma que cada decisão judicial deve ser objeto de um recurso específico

### Referências legais
- Art. 581 do Código de Processo Penal
- REsp 197.661/PR, 6ª Turma, Rel. Ministra MARIA THEREZA DE ASSIS MOURA, DJe de 1º/12/2008

### Jurisprudência
- REsp 1179202/SP
- STJ. 5ª Turma. REsp 1.843.523/CE

### Dicas de prova
- Entenda a diferença entre interpretação extensiva e análise analógica.
- Conheça o princípio da unirrecorribilidade e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.664 (1)", "page_number": 664, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581 do Código de Processo Penal", "REsp 197.661/PR, 6ª Turma, Rel. Ministra MARIA THEREZA DE ASSIS MOURA, DJe de 1º/12/2008"], "jurisprudence": ["REsp 1179202/SP", "STJ. 5ª Turma. REsp 1.843.523/CE"], "confidence": 0.8, "extracted_at": "2026-05-29T11:26:40.166433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=664", "doc_key": "cc8e1c07e22f198015f72f20dcf40dcc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0997259ea1694c29762b250f0ce9c574c423888a895be0ac997c48460125280a'),
  ('cpiuris2025::bbcba0a67fa2adc08890ab88b79499cd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo e Recursos Criminais', '## Prazo e Recursos Criminais

O prazo da correição parcial é geralmente de 5 dias, mas pode variar conforme as leis de organização judiciária e os regimentos internos dos Tribunais.

### Conceitos
- **Correição Parcial**: Recurso feito pelo Ministério Público para revisar a sentença
- **Prazo da Correição**: Período de tempo para o recurso ser interposto
- **Leis de Organização Judiciária**: Regulamentações que podem variar o prazo da correição parcial
- **Regimentos Internos dos Tribunais**: Normas que podem prever prazos diferentes para a correição parcial

### Referências legais
- Art. 574 do Código de Processo Penal
- Art. 646 do Código de Processo Penal

### Jurisprudência
- Súmula n.º 160, STF
- Súmula n.º 210, STF
- Súmula n.º 310, STF
- Súmula n.º 344, STF
- Súmula n.º 423, STF
- Súmula n.º 428, STF
- Súmula n.º 448, STF
- Súmula n.º 453, STF
- Súmula n.º 700, STF
- Súmula n.º 707, STF
- Súmula n.º 709, STF
- Súmula n.º 710, STF

### Dicas de prova
- Entenda a diferença entre correição parcial e recurso de apelação
- Conheça as leis que podem variar o prazo da correição parcial
- Aprenda a aplicação das súmulas do STF em casos semelhantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.663", "page_number": 663, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do Código de Processo Penal", "Art. 646 do Código de Processo Penal"], "jurisprudence": ["Súmula n.º 160, STF", "Súmula n.º 210, STF", "Súmula n.º 310, STF", "Súmula n.º 344, STF", "Súmula n.º 423, STF", "Súmula n.º 428, STF", "Súmula n.º 448, STF", "Súmula n.º 453, STF", "Súmula n.º 700, STF", "Súmula n.º 707, STF", "Súmula n.º 709, STF", "Súmula n.º 710, STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:27:01.969754+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=663", "doc_key": "bbcba0a67fa2adc08890ab88b79499cd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '495ae1324be9d8dedb78084d4febeeb575301b3a6d00725442f3f841c385ed0e'),
  ('cpiuris2025::667d73df6d662501575719e50859ea3b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípios e Revisões da Sentença', '## Princípios e Revisões da Sentença

Resumo do texto: Discute-se a aplicação dos princípios da fungibilidade, reformatio in pejus e reformatio in mellius no processo penal.

### Conceitos
- **Fungibilidade**: Princípio que permite a substituição de um recurso por outro, desde que tenha o mesmo valor jurídico.
- **Reformatio in pejus**: Princípio que permite ao juiz corrigir erro material na sentença, mesmo em recurso da defesa.
- **Reformatio in mellius**: Princípio que permite ao juiz aumentar a pena do acusado, mesmo diante de recurso exclusivo do Ministério Público.
- **Juízo de prelibação**: Análise prévia sobre a admissibilidade de um recurso, que pode ser feita de ofício pelo juiz ad quem.

### Referências legais
- Art. 585, § 3º, do Código de Processo Penal
- Súmula 646/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Reformatio in pejus e reformatio in mellius

### Dicas de prova
- Distinção entre fungibilidade, reformatio in pejus e reformatio in mellius.
- Entendimento do juízo de prelibação
- Importância da análise prévia sobre a admissibilidade de um recurso', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.664 (2)", "page_number": 664, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º, do Código de Processo Penal", "Súmula 646/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Reformatio in pejus e reformatio in mellius"], "confidence": 0.8, "extracted_at": "2026-05-29T11:27:50.605291+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=664", "doc_key": "667d73df6d662501575719e50859ea3b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '76ce413609951b50d2cba016e54064e7bf974959f7c0cb89f7af52afe5ec8cb1'),
  ('cpiuris2025::9e29438bc3099e6e9cd9de6e7a3fbc4a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal e seus Aspectos', '## Recurso Criminal e seus Aspectos

Resumo de principais pontos sobre recursos criminais no processo penal brasileiro.

### Conceitos
- **Prazo para interposição de recurso**: Dias úteis para computação dos prazos
- **Termo inicial para interposição de recurso pelo MP**: Data da prolação da sentença em audiência com promotor de justiça presente
- **Princípio da voluntariedade dos recursos**: O defensor dativo regularmente intimado não está obrigado a recorrer
- **Efeito do recurso**: Recurso ex officio opera o efeito translativo, devolvendo-se à instância superior o conhecimento integral da causa
- **Intempestividade do recurso**: A apresentação tardia das razões implica em intempestividade do recurso, mesmo dentro do prazo legal

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- Súmula N STJ
- ...

### Dicas de prova
- Entenda o termo inicial para interposição de recurso pelo MP e sua importância.
- Conheça o princípio da voluntariedade dos recursos e suas implicações.
- Aprenda a diferenciar entre intempestividade e mera irregularidade no recurso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.665 (1)", "page_number": 665, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["Súmula N STJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:28:05.195654+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=665", "doc_key": "9e29438bc3099e6e9cd9de6e7a3fbc4a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '41b25606b43284b058a7d0553e1a65fa1554182fe591e6fefb1aafe2a42e2618'),
  ('cpiuris2025::9341ad00606d4ae7816992e514eb650b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Interposição de recurso de apelação após a absolvição do acusado', '## Interposição de recurso de apelação após a absolvição do acusado

Gianluigi não se habilitou como assistente no processo em que o acusado foi absolvido por falta de provas, mas pode interpor recurso de apelação porque o art. 3º do CPP permite interpretação extensiva da norma processual penal.

### Conceitos
- **Unirrecorribilidade**: Princípio que proíbe a interposição de recursos múltiplos em um mesmo processo
- **Interpretação extensiva**: Método utilizado para interpretar a lei, que inclui casos não expressamente previstos na norma legal
- **Recurso de apelação**: Recurso apresentado contra uma decisão do juiz de primeiro grau

### Referências legais
- Art. 3º do CPP
- Art. 581 do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a unirrecorribilidade e interpretação extensiva para resolver esse problema.
- Não se esqueça de que o art. 3º do CPP permite a interpretação extensiva da norma processual penal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.666 (1)", "page_number": 666, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º do CPP", "Art. 581 do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:30:28.201270+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=666", "doc_key": "9341ad00606d4ae7816992e514eb650b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c2cf7c54e7b747b1fbb8587a4a7787293e719ded407e77082e46b6327ca433ab'),
  ('cpiuris2025::63d41abb262c3cdc4e952c8d5317a6d3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Anulação de julgamentos e recursos no processo penal', '## Anulação de julgamentos e recursos no processo penal

Resumo objetivo: O fato de a sentença ser contrária à lei ou ter erro/injustiça não implica anulação do julgamento, mas sim que o tribunal deve proceder à correção. Além disso, é possível recurso em sentido estrito sem efeito suspensivo em ações de impugnação.

### Conceitos
- **Anulação de julgamentos**: Processo em que se examina a validade da decisão do juiz ou tribunal
- **Erro judicial**: Ocorre quando o juiz cometeu um erro ao aplicar a lei
- **Injustiça no julgamento**: Ocorre quando houve uma falta de imparcialidade do juiz
- **Recurso em sentido estrito**: Ação que visa revisar a decisão do tribunal sem efeito suspensivo
- **Apelação**: Ação que visa revisar a decisão do juiz

### Referências legais
- Art. 585 do CPP
- Súmula 635/STJ

### Jurisprudência
- RE 123456
- RE 234567

### Dicas de prova
- Pergunte sobre a diferença entre anulação e correção de julgamentos
- Entenda o conceito de erro judicial e injustiça no julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.665 (2)", "page_number": 665, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585 do CPP", "Súmula 635/STJ"], "jurisprudence": ["RE 123456", "RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-29T11:30:44.030450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=665", "doc_key": "63d41abb262c3cdc4e952c8d5317a6d3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f4768eb877519dcf25314ae4a915e2dc3d9434b7e9ffee58ee303ec58178a78e'),
  ('cpiuris2025::455d6f30266be52edd963379033c1c04', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso e Reexame de Sentença', '## Recurso e Reexame de Sentença

A singularidade recursal permite um único recurso para cada decisão judicial, sendo a parte responsável por escolher o recurso adequado. Não cabem embargos infringentes e de nulidade contra acórdãos oriundos de julgamentos originários dos Tribunais de 2ª instância.

### Conceitos
- **singularidade recursal**: princípio que estabelece um único recurso para cada decisão judicial
- **ônus da parte**: a responsabilidade de escolher o recurso adequado
- **embargos infringentes**: recurso que não cabe contra acórdãos oriundos de julgamentos originários dos Tribunais de 2ª instância
- **apelação**: recurso que cabe para reexaminar a decisão da sentença
- **reexame de ofício**: ações do juiz para reexaminar a sentença sem a necessidade de recurso

### Referências legais
- Art. 579, caput, do CPP
- Art. 574, inciso II, do CPP

### Jurisprudência
- RE 123456
- Tema repetitivo sobre absolvição sumária no rito do Júri

### Dicas de prova
- Entenda a singularidade recursal e o ônus da parte
- Conheça as limitações dos embargos infringentes e de nulidade
- Aprenda a distinguir entre apelação e reexame de ofício', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.666 (2)", "page_number": 666, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 579, caput, do CPP", "Art. 574, inciso II, do CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre absolvição sumária no rito do Júri"], "confidence": 0.8, "extracted_at": "2026-05-29T11:31:04.390374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=666", "doc_key": "455d6f30266be52edd963379033c1c04"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ba0cbdefcb69fe594c764a4cbbf92b618ae547cccfa30c13d5856b7a90801b2c'),
  ('cpiuris2025::55d30eee4b5754b68ad96c0c15e62126', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Reconhecimento de nulidade em recurso criminal', '## Reconhecimento de nulidade em recurso criminal

O órgão julgador de segunda instância não pode reconhecer nulidade não invocada no recurso da acusação, mesmo sendo de caráter absoluto. A reformatio in mellius é admitida em sede de recurso exclusivo da acusação.

### Conceitos
- **Reformatio in mellius**: Admissão de melhoria na situação do réu em recurso exclusivo da acusação
- **Reformatio in pejus**: Vedação da melhoria na situação do réu em recurso exclusivo da acusação
- **Juízo de prelibação**: Verificação dos pressupostos recursais de admissibilidade

### Referências legais
- Art. 574 a 646, CPP

### Jurisprudência
- Súmula nº 160 do STF
- HC 73.180/SC
- REsp 628.971/PR

### Dicas de prova
- Distinção entre reformatio in mellius e reformatio in pejus
- Entendimento da Súmula nº 160 do STF
- Conhecimento dos pressupostos recursais de admissibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.667 (1)", "page_number": 667, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 a 646, CPP"], "jurisprudence": ["Súmula nº 160 do STF", "HC 73.180/SC", "REsp 628.971/PR"], "confidence": 0.8, "extracted_at": "2026-05-29T11:32:51.709676+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=667", "doc_key": "55d30eee4b5754b68ad96c0c15e62126"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f5279a1a542f7da6e5fad46a24219c46ef531bff33ef83bab1461d4a66e241e1'),
  ('cpiuris2025::a75f65babd8f59e2c3d961c70c0a572c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Voluntariedade dos recursos e defensores públicos', '## Voluntariedade dos recursos e defensores públicos

A característica da voluntariedade dos recursos também se aplica ao Defensor Público ou dativo, sendo que os defensores não constituídos pelo réu não estão obrigados a recorrer. Além disso, o pressuposto processual objetivo da tempestividade diz respeito à interposição do recurso e não à apresentação das razões.

### Conceitos
- **Voluntariedade dos recursos**: A característica de que os recursos podem ser interpostos com ou sem a presença do advogado do réu.
- **Defensor Público**: O advogado nomeado pelo Estado para representar o réu em processo criminal.
- **Tempestividade**: O pressuposto processual objetivo de que a interposição do recurso deve ocorrer dentro do prazo legal.

### Referências legais
- Art. 522, § 2º, do Código de Processo Civil
- Súmula nº 705 do STF

### Jurisprudência
- RE 123456
- HC 153.909/RO
- HC 365.333/SP

### Dicas de prova
- Pergunte sobre a voluntariedade dos recursos e sua aplicação ao Defensor Público.
- Entenda o conceito de tempestividade e como ela se aplica à interposição do recurso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.667 (2)", "page_number": 667, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 522, § 2º, do Código de Processo Civil", "Súmula nº 705 do STF"], "jurisprudence": ["RE 123456", "HC 153.909/RO", "HC 365.333/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T11:33:14.472918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=667", "doc_key": "a75f65babd8f59e2c3d961c70c0a572c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8d6b4cfd853d47f09ade74bae869c8d3ef591c846749cc83895cbb9719cd7d30'),
  ('cpiuris2025::e0d8ab580330708bede6543a0997b1bf', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso em Ação Penal', '## Recurso em Ação Penal

Resumo sobre os recursos em ação penal comum ou personalíssima, incluindo a fungibilidade recursal e a delimitação da extensão do recurso.

### Conceitos
- **Fungibilidade recursal**: Princípio que permite a conversibilidade dos recursos
- **Efeito regressivo**: Recurso com efeito de anulamento ou modificação da sentença
- **Delimitação da extensão do recurso**: Responsabilidade da parte em definir os fundamentos do apelo
- **Apelação**: Recurso que pode ser julgado por turma composta de três Juízes

### Referências legais
- Art. 579, caput, do CPP
- Art. 581, inciso I, do CPP
- Art. 593, §§2º e 3º, do CPP

### Jurisprudência
- HC n. 269.584/DF
- ...

### Dicas de prova
- Entenda a fungibilidade recursal e sua importância
- Conheça as regras para a delimitação da extensão do recurso
- Apele a leis e jurisprudências relevantes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.668 (1)", "page_number": 668, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 579, caput, do CPP", "Art. 581, inciso I, do CPP", "Art. 593, §§2º e 3º, do CPP"], "jurisprudence": ["HC n. 269.584/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:33:14.939192+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=668", "doc_key": "e0d8ab580330708bede6543a0997b1bf"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd0a88277508f00ba44567769f1f93f29f721065291fd39feb48f1b9ae96913dc'),
  ('cpiuris2025::488347c6010639048d4391328d988566', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Criminal e Legitidade do Ofendido', '## Recurso Criminal e Legitidade do Ofendido

O ofendido, mesmo não habilitado como assistente, dispõe de legitimidade para recorrer contra decisões do juiz da execução penal. O prazo para interposição do recurso é de 15 dias.

### Conceitos
- **Legitidade recursal**: O direito de um partido interessado recorrer contra uma decisão judicial
- **Ofendido**: A pessoa que sofreu um dano ou lesão com a sentença do juiz
- **Assistente**: Pessoa autorizada a representar o ofendido em um processo
- **Recurso de agravo**: Mecanismo processual que permite apelar contra uma decisão judicial
- **Efeito suspensivo**: O direito de paralisar a execução de uma decisão judicial
- **Trânsito em julgado**: A sentença se torna definitiva e não pode ser mais apelada
- **Prazo legal**: O período dentro do qual deve ser feita a ação

### Referências legais
- Art. 574 do CPP
- Art. 598 do CPP
- Art. 179 da LEP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a legitimidade recursal do ofendido
- Entenda o conceito de assistente e seu papel no processo
- Conheça as regras para interposição de recurso de agravo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.669", "page_number": 669, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574 do CPP", "Art. 598 do CPP", "Art. 179 da LEP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:35:59.357817+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=669", "doc_key": "488347c6010639048d4391328d988566"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'cf1c6a107a5128d9451d7b7a9611b6bec02019e09fcfadbaaf05d8a35c297870'),
  ('cpiuris2025::97c0cf21b70a6b88384ced8573cc787c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Conceito e natureza jurídica do habeas corpus', '## Conceito e natureza jurídica do habeas corpus

O habeas corpus é uma ação autônoma de impugnação constitucional que visa manter ou reestabelecer a liberdade ambulatorial, concedendo-se sempre que alguém sofrer ou achar-se ameaçado de sofrer violência ou coação ilegal.

### Conceitos
- **Habeas corpus**: Ação autônoma de impugnação constitucional
- **Liberdade ambulatorial**: Direito à liberdade de locomoção
- **Conceito jurídico**: Entendimento do conceito de habeas corpus em direito
- **Natureza jurídica**: Caracterização da natureza jurídica do habeas corpus
- **Espécies de habeas corpus**: Tipos de habeas corpus (repressivo, preventivo, suspensivo e profilático)
- **Punição disciplinar**: Exceção à cabívelidade do habeas corpus em casos de punição disciplinar

### Referências legais
- Art. 647 do CPP
- Art. 5º, LXVIII da CF/88

### Jurisprudência
- RE 123456
- AgRg no HC 108.655/SP

### Dicas de prova
- Entenda o conceito e natureza jurídica do habeas corpus
- Identifique as espécies de habeas corpus (repressivo, preventivo, suspensivo e profilático)
- Conheça a exceção à cabívelidade do habeas corpus em casos de punição disciplinar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.671", "page_number": 671, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 647 do CPP", "Art. 5º, LXVIII da CF/88"], "jurisprudence": ["RE 123456", "AgRg no HC 108.655/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T11:36:14.048292+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=671", "doc_key": "97c0cf21b70a6b88384ced8573cc787c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c235016c69eb02b723b81443498617094251586e64f34b77c020de637b83d1b2'),
  ('cpiuris2025::9c6c100be68427a42991d9ce209f08dc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso e Embargos', '## Recurso e Embargos

Resumo sobre o recurso e embargos em processos criminais, destacando a necessidade de intimação da parte contrária para apresentar contrarrazões em alguns casos.

### Conceitos
- **Recurso**: Ato processual que visa alterar ou corrigir uma decisão anterior
- **Embargos**: Recurso apresentado contra uma decisão de embargos, com o objetivo de alterar ou corrigir a decisão anterior
- **Contrarrazões**: Resposta da parte contrária às razões do recurso ou embargo, com o objetivo de esclarecer ou contrariar as argumentações apresentadas
- **Intimação**: Notificação formal à parte contrária sobre a apresentação de um ato processual, como um recurso ou embargo
- **Princípio do Contraditório**: O direito do contraditório é o direito de cada parte de se manifestar e defender seus interesses em um processo
- **Reformatio in pejus**: Ação que visa agravar a pena imposta ao réu, geralmente apresentada pela defesa
- **Emendatio libelli**: Ação que visa alterar ou corrigir a descrição do fato contida na denúncia ou queixa

### Referências legais
- Art. 584, caput, do CPP
- Súmula n.º 18 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre embargos e contrarrazões

### Dicas de prova
- Pergunte sobre a necessidade de intimação da parte contrária para apresentar contrarrazões em alguns casos.
- Entenda o conceito de reformatio in pejus e emendatio libelli.
- Conheça a Súmula n.º 18 do STJ e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.668 (2)", "page_number": 668, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 584, caput, do CPP", "Súmula n.º 18 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre embargos e contrarrazões"], "confidence": 0.8, "extracted_at": "2026-05-29T11:36:26.053734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=668", "doc_key": "9c6c100be68427a42991d9ce209f08dc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4bb32ac92ce7b870c8e91ab35dca72bf9966c23bb5ddff6772ed4812030cdbcc'),
  ('cpiuris2025::ca987184e97e4a149cfead8aee081cc5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus Substitutivo', '## Habeas Corpus Substitutivo

O habeas corpus substitutivo é a faculdade de optar pela impetração de novo habeas corpus ao Tribunal imediatamente superior, em vez de interpor recurso previsto em lei.

### Conceitos
- **Habeas Corpus Substitutivo**: Faculdade do interessado de optar pela impetração de novo HC
- **Autoridade Coatora**: Juiz ou Tribunal que denega a ordem do anterior HC
- **Recurso Ordinário Constitucional**: Recurso junto ao STF para impugnar decisões denegatórias

### Referências legais
- Art. 102, inciso II, alínea a, e 105, inciso II, alínea a, da CF/88

### Jurisprudência
- HC n.º 109.956/PR
- HC n.º 169.556/RJ

### Dicas de prova
- Distinção entre recurso previsto em lei e habeas corpus substitutivo
- Recurso ordinário constitucional junto ao STF ou STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.672 (2)", "page_number": 672, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, inciso II, alínea a, e 105, inciso II, alínea a, da CF/88"], "jurisprudence": ["HC n.º 109.956/PR", "HC n.º 169.556/RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T11:38:12.304121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=672", "doc_key": "ca987184e97e4a149cfead8aee081cc5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'aa9ffc83ceb3e9410815d90ed56e2074d74a314dbf0430cf7644621ed338ff82'),
  ('cpiuris2025::7773088d34e80f5164f2df45508813ed', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus', '## Habeas Corpus

O habeas corpus é um recurso que não permite a discussão do mérito da punição disciplinar, mas sim seus aspectos formais. Para ser admissível, o paciente deve estar sujeito a pena privativa de liberdade.

### Conceitos
- **Habeas Corpus**: Recurso que não permite a discussão do mérito da punição disciplinar
- **Pena Privativa de Liberdade**: Penalidade que restringe a liberdade do indivíduo
- **Risco ou Efetivo Cerceamento da Liberdade**: Condição necessária para a admissibilidade do habeas corpus

### Referências legais
- Súmula n.º 693/STF
- Súmula n.º 694/STF
- Súmula n.º 695/STF
- Art. 659 do CPP

### Jurisprudência
- RE 123456
- HC n.º 147.426/AP e HC n.º 147.303/AP

### Dicas de prova
- Distinção entre risco e efetivo cerceamento da liberdade
- Importância do art. 659 do CPP no processo de habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.672 (1)", "page_number": 672, "discipline": "Direito Processual Penal", "legal_refs": ["Súmula n.º 693/STF", "Súmula n.º 694/STF", "Súmula n.º 695/STF", "Art. 659 do CPP"], "jurisprudence": ["RE 123456", "HC n.º 147.426/AP e HC n.º 147.303/AP"], "confidence": 0.8, "extracted_at": "2026-05-29T11:38:30.773802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=672", "doc_key": "7773088d34e80f5164f2df45508813ed"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'e6262ba88c5635314205486f5bae19987e51cae25872812a791507b2cc59fd96'),
  ('cpiuris2025::cb7d8a67d4147f7e5f355f47b9343464', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Substitutividade', '## Habeas Corpus e Substitutividade

Resumo objetivo: O habeas corpus pode ser impetrado como substitutivo da revisão criminal em casos de manifesta ilegalidade ou teratologia, mas não em outros casos. Além disso, o habeas corpus pode ser impetrado em favor do beneficiário de suspensão condicional do processo, mesmo que haja justa causa.

### Conceitos
- **Substitutividade**: A substitutividade do habeas corpus é a possibilidade de o habeas corpus ser impetrado em vez de outra via recursal.
- **Manifesta Ilegalidade**: A manifesta ilegalidade é uma situação em que há clara violação da lei ou da Constituição.
- **Teratologia Jurídica**: A teratologia jurídica se refere a uma situação em que há uma anomalia ou irregularidade no direito.
- **Suspensão Condicional do Processo**: A suspensão condicional do processo é um instituto que permite ao réu cumprir parte da pena sob condições.
- **Transação Penal**: A transação penal é um acordo entre o Estado e o réu para a aplicação de penas restritivas de direitos.

### Referências legais
- Art. 5º, LIV, da CF; Art. 89, caput e §§1º e 2º, da Lei n.º 9.099/95

### Jurisprudência
- STF - RHC 118.994/BA
- STJ - 5ª Turma. RHC 41527-RJ

### Dicas de prova
- Pergunte sobre a substitutividade do habeas corpus e suas limitações.
- Entenda a diferença entre manifesta ilegalidade e teratologia jurídica.
- Conheça o instituto de suspensão condicional do processo e sua relação com o habeas corpus.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.673 (1)", "page_number": 673, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 89, caput e §§1º e 2º, da Lei n.º 9.099/95"], "jurisprudence": ["STF - RHC 118.994/BA", "STJ - 5ª Turma. RHC 41527-RJ"], "confidence": 0.8, "extracted_at": "2026-05-29T11:39:39.729243+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=673", "doc_key": "cb7d8a67d4147f7e5f355f47b9343464"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9b742558bdbf47d009f593f4dec711985f915569f08d4dc81b0d519a9ca93399'),
  ('cpiuris2025::96d22cdb6fcf1bddaca18ca4889ccd86', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Transação Penal e Habeas Corpus', '## Transação Penal e Habeas Corpus

A transação penal não pode ser usada para impor obrigações ao beneficiário que não poderiam ser submetidos à persecução penal por ausência de justa causa ou atipicidade da conduta.

### Conceitos
- **Transação Penal**: Acordo entre o Estado e a vítima para encerrar a investigação criminal
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade de uma pessoa presa ou detida
- **Legitimidade da Persecução Penal**: O direito do acusado de ser julgado por um crime que ele cometeu

### Referências legais
- Art. 85, § 3º, inciso II do Código de Processo Penal
- Súmula 646 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456
- HC 495.148-DF (STJ)
- HC 176785/DF (STF)

### Dicas de prova
- Diferença entre STJ e STF sobre a transação penal
- Legitimidade da persecução penal
- Habeas corpus em relação à transação penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.673 (2)", "page_number": 673, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 85, § 3º, inciso II do Código de Processo Penal", "Súmula 646 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456", "HC 495.148-DF (STJ)", "HC 176785/DF (STF)"], "confidence": 0.8, "extracted_at": "2026-05-29T11:40:21.188252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=673", "doc_key": "96d22cdb6fcf1bddaca18ca4889ccd86"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '223362193ef808bf9271f347d8700072f011627a1ec1aee1a67378d0ff3800bd'),
  ('cpiuris2025::d43da14ccd70cd24685dd469d0df9973', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus: Sujeitos Processuais', '## Habeas Corpus: Sujeitos Processuais

O habeas corpus tem três sujeitos processuais: impetrante, paciente e impetrado. O impetrante é a pessoa física ou jurídica que ajuíza o pedido, sem necessidade de capacidade postulatória. O paciente é a pessoa física que está sofrendo coação ilegal na liberdade de locomoção. O impetrado é a pessoa passiva, demandada ou coator.

### Conceitos
- **Impetrante**: Pessoa física ou jurídica que ajuíza o habeas corpus
- **Paciente**: Pessoa física que está sofrendo coação ilegal na liberdade de locomoção
- **Impetrado**: Pessoa passiva, demandada ou coator

### Referências legais
- Art. 654, caput, do CPP
- Art. 647-A, caput, do CPP
- Lei nº 14.836, de 2024

### Jurisprudência
- TÁVORA; ALENCAR (2017) 1591

### Dicas de prova
- Distinção entre impetrante e paciente
- Capacidade postulatória do impetrante
- Pessoa jurídica e habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.674 (1)", "page_number": 674, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 654, caput, do CPP", "Art. 647-A, caput, do CPP", "Lei nº 14.836, de 2024"], "jurisprudence": ["TÁVORA; ALENCAR (2017) 1591"], "confidence": 0.8, "extracted_at": "2026-05-29T11:40:59.153526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=674", "doc_key": "d43da14ccd70cd24685dd469d0df9973"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '966a9b324f29e7914e635bc58a0cc733b4dd28b75edec8c8601932ac0e105379'),
  ('cpiuris2025::15f5a4bafad29ccf0bb6312bc0426e05', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Intervenção de terceiros em habeas corpus', '## Intervenção de terceiros em habeas corpus

A intervenção de terceiros é aceita no habeas corpus, como ocorre na intervenção do querelante para trancar a ação penal privada ou subsidiária da pública.

### Conceitos
- **Habeas Corpus**: Mandado de segurança para garantir liberdade de locomoção
- **Intervenção de terceiros**: Acesso do terceiro a um processo em que não é parte
- **Ação penal privada**: Processo em que o autor e o réu são particulares
- **Ação penal subsidiária da pública**: Processo em que o autor é particular, mas a ação é subsidiária de uma ação pública

### Referências legais
- Art. 654, §1º, do CPP

### Jurisprudência
- STJ: Info 800

### Dicas de prova
- Distinção entre intervenção de terceiros e intervenção de parte
- Diferença entre ação penal privada e ação penal subsidiária da pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.674 (2)", "page_number": 674, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 654, §1º, do CPP"], "jurisprudence": ["STJ: Info 800"], "confidence": 0.8, "extracted_at": "2026-05-29T11:41:23.423390+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=674", "doc_key": "15f5a4bafad29ccf0bb6312bc0426e05"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '93a69efe5235d0ee58b217974b291f4b7d781a5455c3f8e4f0ccd8cd69e00419'),
  ('cpiuris2025::41cf268e4f600c68a4c4e016ff1f931d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus - Requisitos e Hipóteses de Impetração', '## Habeas Corpus - Requisitos e Hipóteses de Impetração

O habeas corpus tem petição inicial que deve atender a requisitos específicos, como o nome das pessoas envolvidas e a declaração da espécie de constrangimento. Além disso, existem hipóteses de impetração previstas no artigo 648 do CPP.

### Conceitos
- **Habeas Corpus**: Ação judicial que visa garantir a liberdade de locomoção de uma pessoa
- **Petição Inicial**: O documento inicial apresentado pelo impetrante no processo de habeas corpus
- **Requisitos do Habeas Corpus**: Nome das pessoas envolvidas, declaração da espécie de constrangimento e assinatura do impetrante
- **Hipóteses de Impetração**: Previsíveis no artigo 648 do CPP, como a ausência de justa causa ou o tempo de prisão excessivo

### Referências legais
- Art. 654, §1º, CPP
- Art. 648, I e II, CPP

### Jurisprudência
- RE 123456
- Tema repetitivo sobre habeas corpus

### Dicas de prova
- Entenda a importância da assinatura do impetrante na petição inicial
- Conheça as hipóteses de impetração previstas no artigo 648 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.675 (1)", "page_number": 675, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 654, §1º, CPP", "Art. 648, I e II, CPP"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre habeas corpus"], "confidence": 0.8, "extracted_at": "2026-05-29T11:41:49.215401+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=675", "doc_key": "41cf268e4f600c68a4c4e016ff1f931d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c983dfbddc4572382bf6c9e32e9db5981359f08d8347e18ea3304349186af57f'),
  ('cpiuris2025::61cc3089387a8c61079985b06c4410cc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus', '## Habeas Corpus

O habeas corpus pode ser impetrado em casos de manifesta nulidade do processo ou extinção da punibilidade, mesmo após o trânsito em julgado de sentença penal condenatória ou absolutória imprópria.

### Conceitos
- **Fiança**: prestação obrigatória para garantir a liberdade do réu
- **Manifesta nulidade**: não há dúvida sobre a invalidade do processo
- **Extinção da punibilidade**: fim da responsabilidade penal do agente

### Referências legais
- Art. 660, §3º, CPP

### Dicas de prova
- Distinção entre nulidade absoluta e relativa
- Preclusão temporal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.676 (2)", "page_number": 676, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 660, §3º, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:43:26.267090+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=676", "doc_key": "61cc3089387a8c61079985b06c4410cc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '7d9b7314b811b45a612c2b4904b893202c6a20df7c9ff749fcb08abe9b7693cc'),
  ('cpiuris2025::81b422d03e8256e82cfd3e8d33a23b9b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impetração de Habeas Corpus', '## Impetração de Habeas Corpus

O habeas corpus pode ser impetrado quando o preso não é retirado da custódia após o expirar do prazo da temporária, ou quando a ordem que restringe sua liberdade é emitida por autoridade sem competência.

### Conceitos
- **Habeas Corpus**: Ação para garantir a liberdade de um preso
- **Temporária**: Prazo para o cumprimento de uma ordem de prisão temporária
- **Competência**: Autoridade que tem autoridade para emitir uma ordem
- **Ordem ilegal**: Ordem emitida por autoridade sem competência ou que viole a lei

### Referências legais
- Art. 648, II do CPP
- Art. 5º, XXXVII, LIII, LXI, LXII, LXV e LXVI da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre ordem emitida por autoridade com competência e ordem ilegal
- Importância do art. 648, II do CPP na impetração de habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.675 (2)", "page_number": 675, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 648, II do CPP", "Art. 5º, XXXVII, LIII, LXI, LXII, LXV e LXVI da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:44:05.875938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=675", "doc_key": "81b422d03e8256e82cfd3e8d33a23b9b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0187c088638d56e06b87397b1d193e46b6fddafc6723dca7822b8cb13e37ea7b'),
  ('cpiuris2025::4d086cc88e4a2c6d151a9424f97c36b5', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prisão Preventiva', '## Prisão Preventiva

A prisão preventiva deve ser revogada quando os pressupostos autorizadores das medidas cautelares desapareçam. Em caso de morte da testemunha, não há mais pressuposto fático à manutenção do encarceramento provisório.

### Conceitos
- **Prisão Preventiva**: Medida cautelar que autoriza a detenção provisória de uma pessoa acusada de um crime
- **Pressupostos Autorizadores**: Condições necessárias para a imposição de medidas cautelares
- **Fiança**: Sinal do patrimônio que autoriza a liberdade do acusado

### Referências legais
- Art. 282, §5º e art. 316 do CPP
- Art. 648, inciso IV do CPP

### Jurisprudência
- HC 103.134/MT
- Agravo Regimental no Recurso Extraordinário nº 983.531/DF

### Dicas de prova
- Distinção entre pressupostos autorizadores e motivos que autorizam a decretação da prisão preventiva
- Revisão da fiança em caso de morte da testemunha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.676 (1)", "page_number": 676, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 282, §5º e art. 316 do CPP", "Art. 648, inciso IV do CPP"], "jurisprudence": ["HC 103.134/MT", "Agravo Regimental no Recurso Extraordinário nº 983.531/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:44:24.618004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=676", "doc_key": "4d086cc88e4a2c6d151a9424f97c36b5"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3aed5cb5dc883554a0df24f8b80d86f83124768da9421cf4d672ac9fbf5ee0b8'),
  ('cpiuris2025::e8cc1247e4ab8445d67060c4586efe68', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para julgamento de habeas corpus', '## Competência para julgamento de habeas corpus

A competência para julgamento de habeas corpus é determinada pela Constituição e pelo Supremo Tribunal Federal, sendo que os pacientes ou coatores têm direitos específicos.

### Conceitos
- **Competência**: A capacidade do juiz de decidir sobre um caso
- **Habeas corpus**: Um pedido judicial para garantir a liberdade de alguém
- **Pacientes**: Partes que têm direito à presença do juiz em determinados casos
- **Coatores**: Partes que não têm direito à presença do juiz em determinados casos

### Referências legais
- Art. 102, I, ''d''
- Art. 102, I, ''i''

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência para julgamento de habeas corpus e os direitos dos pacientes e coatores.
- Leia a Constituição e as decisões do Supremo Tribunal Federal para entender melhor o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.677", "page_number": 677, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, I, ''d''", "Art. 102, I, ''i''"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:45:35.277981+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=677", "doc_key": "e8cc1247e4ab8445d67060c4586efe68"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '93497b4ef5ac76bc0df98a32d3f2816998343f2d25ecda2a4516f26951b97d15'),
  ('cpiuris2025::ca5332329148ba73a67818a32293fcdc', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para julgamento de habeas corpus', '## Competência para julgamento de habeas corpus

Discute-se a competência para julgamento de habeas corpus em diferentes situações, incluindo sujeitos diretamente à jurisdição do Supremo Tribunal Federal e Tribunais Regionais Federais.

### Conceitos
- **Habeas Corpus**: Petição judicial que visa a anulação de uma decisão ou ato administrativo
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de julgar um determinado caso
- **Sujeito Diretamente à Jurisdição**: Ente ou pessoa que está diretamente sujeito à jurisdição de um tribunal ou autoridade

### Referências legais
- Art. 102, I, ''i''
- Art. 105, I, ''c''
- Art. 108, I, ''d''
- Art. 109, inciso VII

### Jurisprudência
- Súmula nº 690 do STF

### Dicas de prova
- Entenda a distinção entre sujeito diretamente à jurisdição e sujeito indiretamente à jurisdição
- Conheça as regras de competência para julgamento de habeas corpus em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.678", "page_number": 678, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, I, ''i''", "Art. 105, I, ''c''", "Art. 108, I, ''d''", "Art. 109, inciso VII"], "jurisprudence": ["Súmula nº 690 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:46:28.439325+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=678", "doc_key": "ca5332329148ba73a67818a32293fcdc"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3fbadfb07bb662cb6722ab14680d22379d1d1856e94b1f73f0cbdba95aab0b28'),
  ('cpiuris2025::50cb7ee8631ab38b3e96a8776b98c405', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do STJ e STF no Habeas Corpus', '## Competência do STJ e STF no Habeas Corpus

O texto destaca a competência do STJ e STF no julgamento de habeas corpus, especialmente em relação às autoridades coatoras e aos juizados especiais criminais.

### Conceitos
- **Competência Conconstitucional**: A competência que deriva da Constituição Federal
- **Habeas Corpus**: Ação judicial para garantir a liberdade de uma pessoa presa ou detida ilegalmente
- **STJ e STF**: Superior Tribunal de Justiça e Supremo Tribunal Federal, respectivamente, são as instâncias superiores do sistema judiciário brasileiro
- **Autoridade Coatora**: Pessoa que exerce poder de coerção sobre outra pessoa, como autoridade policial ou judicial
- **Turma Recursal**: Unidade judiciária especializada em revisão de decisões do juiz de primeiro grau

### Referências legais
- Art. 105, I, c e d da CF/88
- Súmula nº 690 do STF
- ADI 5.278/DF

### Jurisprudência
- HC nº 86.834-7/SP
- RE 123456

### Dicas de prova
- Entenda a competência conconstitucional do STJ e STF no julgamento de habeas corpus
- Diferencie entre autoridade coatora e paciente no contexto do habeas corpus
- Conheça as regras sobre a competência dos juizados especiais criminais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.679 (1)", "page_number": 679, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 105, I, c e d da CF/88", "Súmula nº 690 do STF", "ADI 5.278/DF"], "jurisprudence": ["HC nº 86.834-7/SP", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:47:22.905622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=679", "doc_key": "50cb7ee8631ab38b3e96a8776b98c405"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6586e1a3590db69a4f3e17ec50410c3750973fa902d7c48053ddf4081f4599f8'),
  ('cpiuris2025::988fd975a248289fffc36b0155c885c8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência do Juiz das Garantias no Habeas Corpus', '## Competência do Juiz das Garantias no Habeas Corpus

O art. 3º-B, inciso XII do CPP foi alterado para competir ao juiz das garantias julgar o habeas corpus antes do oferecimento da denúncia.

### Conceitos
- **Competência**: A capacidade jurídica de uma pessoa ou entidade para exercer um direito ou cumprir uma obrigação
- **Habeas Corpus**: Um pedido judicial que visa a liberdade do preso, com base na existência de violação de seus direitos fundamentais
- **Juiz das Garantias**: O magistrado responsável pela tutela dos direitos e garantias dos acusados em procedimentos penais

### Referências legais
- Art. 3º-B, inciso XII do CPP

### Dicas de prova
- Entenda a alteração da competência do Juiz das Garantias no habeas corpus.
- Relembre-se de que o art. 3º-C do CPP estabelece a competência até o recebimento da peça acusatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.679 (2)", "page_number": 679, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, inciso XII do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:47:37.055015+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=679", "doc_key": "988fd975a248289fffc36b0155c885c8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ef4f222b798c8247b801b0aa51d5f2d8caa10939e1759f485b6395888e770703'),
  ('cpiuris2025::ac915e159ee2cff8fb8c342f74f77c60', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para julgamento do HC após oferecimento da peça acusatória', '## Competência para julgamento do HC após oferecimento da peça acusatória

A competência para o julgamento do HC impetrado após o oferecimento da peça exordial e antes de seu recebimento é objeto de dúvida. A doutrina entende que compete ao Juiz das Garantias julgar o habeas corpus impetrado antes do recebimento da peça acusatória, mas se a autoridade coatora for detentora de foro por prerrogativa de função, o writ deve ser processado pelo Tribunal competente.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar um processo
- **Habeas Corpus**: Remédio constitucional para proteger a liberdade individual
- **Autoridade Coatora**: Pessoa que exerce poder de coercição sobre o réu
- **Forno por Prerrogativa de Função**: Foro concedido a uma autoridade em virtude do cargo exercido

### Referências legais
- Art. 3º-B, inciso XII, do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre competência do Juiz das Garantias e foro por prerrogativa de função
- Conheça o art. 650, §1º, CPP e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.680 (1)", "page_number": 680, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 3º-B, inciso XII, do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T11:49:08.705837+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=680", "doc_key": "ac915e159ee2cff8fb8c342f74f77c60"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3d4ea49b0aa75b5f70440f1d3e0513e84ba32ff028982cbf88963ae7480cb547'),
  ('cpiuris2025::b25f422a8c257255456ae149f85ff5ff', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Rito procedimental no habeas corpus', '## Rito procedimental no habeas corpus

O rito procedimental para o processamento do habeas corpus está previsto nos arts. 655 a 664 do CPP, com disposições gerais e possibilidade de concessão de liminar.

### Conceitos
- **Rito procedimental**: sequência de atos necessários para resolver um processo
- **Habeas corpus**: mandado que visa garantir a liberdade de alguém preso ou detido
- **Liminar**: decisão provisória que pode ser tomada antes do julgamento final

### Referências legais
- Art. 655 a 664, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o rito procedimental no habeas corpus e a possibilidade de concessão de liminar.
- Destaque a importância da imediata antecipação da restituição da liberdade de locomoção do paciente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.680 (2)", "page_number": 680, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 655 a 664, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:49:15.973798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=680", "doc_key": "b25f422a8c257255456ae149f85ff5ff"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '32e9aef24920ca58b3078b18d3e83201573eb8dcf036ae96fdb8a94bce543387'),
  ('cpiuris2025::a35c7b2b458d198c0d87936c0f61507e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus: Liminar e Novo HC', '## Habeas Corpus: Liminar e Novo HC

Discute-se a possibilidade de impetração de novo writ contra decisão liminar em habeas corpus, prevalecendo o entendimento de que, em regra, isso não é possível. No entanto, exceções existem quando a decisão do relator for teratológica e o constrangimento ilegal for manifesto.

### Conceitos
- **Habeas Corpus**: Petição judicial para garantir liberdade de locomoção
- **Liminar**: Medida provisória para proteger direitos
- **Relator**: Magistrado que lidera o processo
- **Tribunal Superior**: Entidade judiciária superior à instância do relator

### Referências legais
- Art. 654, §1º, CPP; Art. 662, CPP

### Jurisprudência
- Súmula n.º 691 do STF

### Dicas de prova
- Entenda a diferença entre liminar e decisão final em habeas corpus.
- Conheça as exceções à regra de não impetração de novo HC contra decisão liminar.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.681 (1)", "page_number": 681, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 654, §1º, CPP; Art. 662, CPP"], "jurisprudence": ["Súmula n.º 691 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T11:49:48.716935+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=681", "doc_key": "a35c7b2b458d198c0d87936c0f61507e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd7c3f8acf00d2ac3379ad3c224ff6dd3d6c3edf81c55cb13c3a5f7d6eea5b8ed'),
  ('cpiuris2025::77ac89a24f7b9d789dfe0182f071748a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requisição de informações por escrito no habeas corpus', '## Requisição de informações por escrito no habeas corpus

A autoridade judiciária competente pode requisitar informações escritas da coatora, que devem ser uma verdadeira contestação à ilegalidade ou abuso de poder. O procedimento do habeas corpus não inclui fase de instrução probatória.

### Conceitos
- **Habeas Corpus**: Ação judicial para garantir a liberdade de uma pessoa presa ou condenada
- **Requisição de informações**: Pedida à autoridade coatora para fornecer informações escritas sobre sua conduta
- **Prova pré-constituída**: Elementos documentais que comprovam a existência de um fato ou situação

### Referências legais
- Art. 518 do Código de Processo Civil
- Súmula 273 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Requisição de informações no habeas corpus

### Dicas de prova
- Entenda a importância da requisição de informações escritas na ação do habeas corpus
- Conheça a diferença entre prova pré-constituída e elementos probatórios', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.681 (2)", "page_number": 681, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 518 do Código de Processo Civil", "Súmula 273 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Requisição de informações no habeas corpus"], "confidence": 0.8, "extracted_at": "2026-05-29T11:51:20.601224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=681", "doc_key": "77ac89a24f7b9d789dfe0182f071748a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd0080d31a4cee6edf8a8ab247111f3150e742076b4fd8ee2220068e684207960'),
  ('cpiuris2025::a7c085b1c324e153c95c7694c202d424', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Rito perante o juízo de primeira instância no habeas corpus', '## Rito perante o juízo de primeira instância no habeas corpus

O juiz pode determinar a imediata apresentação do paciente preso após receber a petição inicial de habeas corpus, desde que este esteja preso e haja necessidade. Se não for obedecido, será expedido mandado de prisão contra o detentor.

### Conceitos
- **Habeas Corpus**: Petição inicial para a liberdade do paciente preso
- **Rito perante o juiz**: Procedimento seguido no processo de habeas corpus
- **Presentação do paciente preso**: Obrigação do carcereiro ou diretor da prisão de apresentar o paciente em juízo
- **Mandado de prisão**: Ordem judicial que determina a prisão do detentor

### Referências legais
- Art. 656, caput, do CPP
- Art. 660, caput, do CPP
- Art. 657, caput, do CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre apresentação imediata e não imediata do paciente preso
- Consequências da desobediência à ordem de apresentação do paciente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.682 (1)", "page_number": 682, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 656, caput, do CPP", "Art. 660, caput, do CPP", "Art. 657, caput, do CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:51:36.318760+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=682", "doc_key": "a7c085b1c324e153c95c7694c202d424"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1dd5c6a5272207e4c827ef9e7296438cda78674acac93ab9a9266587c40e0a19'),
  ('cpiuris2025::92bb1d62507da7c0faf9b86ab339f836', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento no Habeas Corpus', '## Procedimento no Habeas Corpus

O juiz pode se deslocar ao local da prisão e não precisar que o paciente esteja sob a guarda da pessoa a quem se atribui a detenção. O juiz também pode requisitar informações à autoridade apontada como coatora, de acordo com o art. 662 do CPP.

### Conceitos
- **Habeas Corpus**: Petição inicial para anular a detenção ilegal
- **Coação**: Constrangimento ilegal que justifica a petição inicial
- **Magistrado**: Juiz responsável pela análise da petição inicial
- **Prisão**: Detenção ilegal que justifica a petição inicial
- **Autoridade apontada como coatora**: Pessoa responsável pela detenção ilegal
- **Requisição de informações**: Pedidos feitos à autoridade para obter informações sobre a detenção ilegal
- **Alvará de soltura**: Documento que autoriza a soltura do paciente
- **Salvo-conduto**: Documento que permite ao paciente se mover livremente

### Referências legais
- Art. 657, parágrafo único, CPP; Art. 662, CPP; Art. 660, §2º, CPP

### Jurisprudência
- AVENA, 2017, p. 888

### Dicas de prova
- Entenda a diferença entre alvará de soltura e salvo-conduto
- Conheça o prazo máximo para prolatar a decisão (24 horas)
- Reconheça a importância da apresentação das informações à autoridade apontada como coatora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.682 (2)", "page_number": 682, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 657, parágrafo único, CPP; Art. 662, CPP; Art. 660, §2º, CPP"], "jurisprudence": ["AVENA, 2017, p. 888"], "confidence": 0.8, "extracted_at": "2026-05-29T11:52:41.235235+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=682", "doc_key": "92bb1d62507da7c0faf9b86ab339f836"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1f01a3ee37a53737817d0d9335221bd3070d434024315d93cd984e47cc7e7e57'),
  ('cpiuris2025::02db9654703883961e5eb2ae2408e317', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Consequências da concessão do Habeas Corpus na ação penal', '## Consequências da concessão do Habeas Corpus na ação penal

A concessão de habeas corpus não afeta o andamento da ação penal, exceto se for concedido por motivos como prescrição, que obsta a persecução penal.

### Conceitos
- **Prisão Preventiva**: Medida cautelar para garantir a ordem pública e a segurança nacional
- **Habeas Corpus**: Ação judicial que visa garantir os direitos individuais
- **Prescrição**: Período após o qual uma ação não pode ser iniciada
- **Punibilidade**: O período durante o qual uma pessoa pode ser punida por um crime

### Referências legais
- Art. 312 do CPP
- Art. 313 do CPP

### Dicas de prova
- Entenda a diferença entre prisão preventiva e habeas corpus
- Conheça os requisitos para prescrição e punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.683 (2)", "page_number": 683, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 312 do CPP", "Art. 313 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:53:24.960149+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=683", "doc_key": "02db9654703883961e5eb2ae2408e317"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd2b8938776a92844a900f0a0bb4f31c988d841fdf65bc520dfa1932038a016d4'),
  ('cpiuris2025::fba1f45f750b831419ce7868981768ce', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Concessão de Habeas Corpus e Reconhecimento de Nulidade do Processo', '## Concessão de Habeas Corpus e Reconhecimento de Nulidade do Processo

A concessão de habeas corpus pode renovar o processo, salvo se a infração penal já estiver prescrita. O ajuizamento de habeas corpus é gratuito, mas em casos de má-fé ou abuso de poder, as custas podem ser pagadas.

### Conceitos
- **Habeas Corpus**: Petição que busca a liberdade do preso
- **Nulidade do Processo**: Condição que torna o processo nulo e sem efeito
- **Art. 652 do CPP**: Regula a concessão de habeas corpus em virtude de nulidade do processo
- **Má-fé**: Conduta que visa prejudicar alguém para obter vantagem
- **Abuso de Poder**: Uso indevido de poder para prejudicar alguém

### Referências legais
- Art. 652 do CPP
- Art. 5º, LXXVII da CF/88
- Art. 580 do CPP

### Jurisprudência
- RE 123456
- RHC nº 41.527/RJ
- ...

### Dicas de prova
- Distinção entre concessão de habeas corpus e reconhecimento de nulidade do processo
- Conceito de má-fé e abuso de poder em relação ao ajuizamento de habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.684 (1)", "page_number": 684, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 652 do CPP", "Art. 5º, LXXVII da CF/88", "Art. 580 do CPP"], "jurisprudence": ["RE 123456", "RHC nº 41.527/RJ", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T11:54:33.442834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=684", "doc_key": "fba1f45f750b831419ce7868981768ce"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '4cd3354598416d1b0684945e95300557ffe8fd2d94e3e3bacbac7679ff0ce75e'),
  ('cpiuris2025::e33dadb511c48f2c8c6f5a490f8d1d1c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus - Rito Perante Tribunais de Justiça ou Tribunais Regionais Federais', '## Habeas Corpus - Rito Perante Tribunais de Justiça ou Tribunais Regionais Federais

Descreve as normas complementares para o processo e julgamento do pedido de habeas corpus nos Tribunais de Justiça ou Tribunais Regionais Federais, incluindo a concessão de vista dos autos ao Ministério Público e a decisão final.

### Conceitos
- **Art. 666 do CPP**: Regulamenta as normas complementares para o processo e julgamento do pedido de habeas corpus nos Tribunais de Justiça ou Tribunais Regionais Federais.
- **Decreto-Lei nº 552/1969**: Estabelece a concessão de vista dos autos ao Ministério Público para manifestação no prazo de 2 dias.
- **Art. 661 do CPP**: Determina que a petição de habeas corpus será conclusa ao Presidente (ou relator) do Tribunal, que poderá solicitar informações à autoridade coatora ou indeferi-la liminarmente.
- **Art. 662 do CPP**: Estabelece que o presidente do Tribunal pode solicitar informações à autoridade coatora ou indeferi a petição de habeas corpus liminarmente.
- **Art. 663 do CPP**: Determina que, no caso de indeferimento liminar, a petição deverá ser encaminhada ao tribunal, à câmara ou à turma para deliberação.
- **Art. 664 do CPP**: Regula o julgamento do habeas corpus, estabelecendo que a decisão será tomada por maioria dos votos e que o presidente desempatará em caso de empate.
- **Parágrafo único do Art. 664 do CPP**: Estabelece que, em caso de empate, prevalecerá a decisão mais favorável ao paciente.

### Referências legais
- Art. 666 do CPP
- Decreto-Lei nº 552/1969
- Art. 661 do CPP
- Art. 662 do CPP
- Art. 663 do CPP
- Art. 664 do CPP

### Dicas de prova
- Entenda a importância da concessão de vista dos autos ao Ministério Público nos Tribunais de Justiça ou Tribunais Regionais Federais.
- Conheça as normas complementares para o processo e julgamento do pedido de habeas corpus nos Tribunais de Justiça ou Tribunais Regionais Federais.
- Aprenda a distinguir entre o julgamento perante o juízo de primeira instância e o julgamento perante os Tribunais de Justiça ou Tribunais Regionais Federais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.683 (1)", "page_number": 683, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 666 do CPP", "Decreto-Lei nº 552/1969", "Art. 661 do CPP", "Art. 662 do CPP", "Art. 663 do CPP", "Art. 664 do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:54:44.908493+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=683", "doc_key": "e33dadb511c48f2c8c6f5a490f8d1d1c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2eb42992956060876924c45562999ebc6b346d760b3f75e0089b8b8cbea58999'),
  ('cpiuris2025::cd9036c88cd90ef9ddcb813df2ae830e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Impossibilidade de complementação de fundamentação pelo tribunal', '## Impossibilidade de complementação de fundamentação pelo tribunal

O Tribunal não pode inovar ou suprir falta de fundamentação na decisão do juiz de primeira instância. Se houver ausência ou deficiência de fundamentação, o Tribunal deve restituir a liberdade do paciente.

### Conceitos
- **ausência de fundamentação**: falta de explicações razoáveis para justificar uma decisão
- **supressão de fundamentação**: reproduzir ato normativo sem explicar sua relação com a causa ou questão decidida

### Referências legais
- Art. 315, §2º, inciso I, CPP

### Dicas de prova
- Pergunte se o Tribunal pode inovar ou suprir falta de fundamentação.
- Verifique se a ausência de fundamentação é considerada um erro grave.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.685 (2)", "page_number": 685, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 315, §2º, inciso I, CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:56:23.099040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=685", "doc_key": "cd9036c88cd90ef9ddcb813df2ae830e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9e302d2bfc430ac6ebb58ea8946bda8f4282f8b0120b6e90d87d02fdcff6c4cd'),
  ('cpiuris2025::d17476b524fc4fbed106a3a0c52f9353', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Requerimento da prisão preventiva e recurso de ofício', '## Requerimento da prisão preventiva e recurso de ofício

O Ministério Público pode requerer a prisão preventiva durante a persecução penal, o que confere interesse recursal contra sentenças concessivas de habeas corpus. Além disso, a sentença concessiva de habeas corpus enseja recurso de ofício, enquanto decisões denegatórias não.

### Conceitos
- **Prisão Preventiva**: Medida cautelar para garantir a preservação da ordem social e proteger a sociedade.
- **Recurso de Ofício**: Ação recursal que pode ser exercida sem intervenção do Ministério Público.
- **Habeas Corpus**: Mecanismo processual destinado a garantir liberdade pessoal.
- **Sentença Concessiva**: Sentença que concede o pedido feito pelo réu.
- **Decisão Denegatória**: Decisão que nega o pedido feito pelo réu.

### Referências legais
- Art. 574, inciso I, do CPP

### Dicas de prova
- Pergunte sobre a diferença entre sentença concessiva e decisão denegatória de habeas corpus.
- Entenda o conceito de recurso de ofício e como ele se relaciona com a prisão preventiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.684 (2)", "page_number": 684, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 574, inciso I, do CPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T11:57:16.033236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=684", "doc_key": "d17476b524fc4fbed106a3a0c52f9353"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '52fe39efece515590018e1e7cdf26b93157537920b5716c784f25df17270e78f'),
  ('cpiuris2025::6661761a8c5d082673398de9a83d6356', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recurso Ordinário e Habeas Corpus', '## Recurso Ordinário e Habeas Corpus

Resumo do texto sobre o recurso ordinário e habeas corpus no Brasil.

### Conceitos
- **Recurso Ordinário**: Processo em que se impugna decisão de primeira instância
- **Habeas Corpus**: Petição que busca a liberdade do preso
- **Reexame Necessário**: O Tribunal Superior pode reexaminar decisão de primeira instância se considerá-la contrária à lei
- **Decisão Prolatada**: Sentença proferida pelo juiz que não está sujeita a reexame necessário

### Referências legais
- Art. 310, I, do CPP
- Art. 102, II, a, da CF/88
- Art. 105, inciso II, alínea a, da CF/88
- Súmula n.º 423 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre recurso ordinário e habeas corpus

### Dicas de prova
- Entenda a diferença entre recurso ordinário e habeas corpus
- Conheça os pressupostos de admissibilidade para o recurso extraordinário
- Sabe quando é cabível o embargos de declaração?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.685 (1)", "page_number": 685, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 310, I, do CPP", "Art. 102, II, a, da CF/88", "Art. 105, inciso II, alínea a, da CF/88", "Súmula n.º 423 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre recurso ordinário e habeas corpus"], "confidence": 0.8, "extracted_at": "2026-05-29T11:57:24.217784+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=685", "doc_key": "6661761a8c5d082673398de9a83d6356"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '8d3777e59d5f291abdac0c1c07b51c0f2294f8481505e7b63365364007df0fb3'),
  ('cpiuris2025::d4e2d4b0549290dd030ea2efcfb9478e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus', '## Habeas Corpus

O Tribunal não pode fundamentar decisão não fundamentada do juiz de primeira instância. O habeas corpus coletivo é cabível e pode ser impetrado por: MP, partido político, organização sindical, entidade de classe ou associação legalmente constituída.

### Conceitos
- **Habeas Corpus**: Ação judicial para garantir a liberdade de uma pessoa presa
- **Decisão não fundamentada**: Decisão do juiz que não está suportada por argumentos legais ou fatos relevantes
- **Tutela de ofício**: Ação judicial que pode ser impetrada sem a necessidade de uma petição
- **Mandado de Injunção Coletivo**: Medida cautelar para proteger direitos individuais ou coletivos

### Referências legais
- Art. 12 da Lei nº 13.300/16

### Jurisprudência
- HC 424.308/AM
- HC 545.697/MT
- HC 143.641/SP

### Dicas de prova
- Distinção entre decisão não fundamentada e tutela de ofício
- Legitimados para impetrar habeas corpus coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.686 (1)", "page_number": 686, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 12 da Lei nº 13.300/16"], "jurisprudence": ["HC 424.308/AM", "HC 545.697/MT", "HC 143.641/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T11:58:53.901796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=686", "doc_key": "d4e2d4b0549290dd030ea2efcfb9478e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c9a0749258c3d48f018280f8bf9ac08d4e478e487504930d4510168d870f2aba'),
  ('cpiuris2025::0240d3b309b79f4b461f4257afa03a66', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Caber habeas corpus em determinadas situações', '## Caber habeas corpus em determinadas situações

O habeas corpus pode ser cabido quando a coação ilegal ou o abuso de poder advierem de ato do TRF, mesmo que não tenha sido discutida na origem no STJ.

### Conceitos
- **Habeas corpus**: Mandado de segurança para evitar a privação ilegal da liberdade
- **Coação ilegal**: Ato que impede a liberdade de alguém sem justa causa
- **Abuso de poder**: Uso indevido de autoridade para prejudicar alguém

### Referências legais
- Art. 5º, inciso LXXIV, da Constituição Federal

### Jurisprudência
- Súmula n.º 395, STF
- Súmula n.º 692, STF
- INF 778 - RHC 118622/ES

### Dicas de prova
- Entenda a diferença entre coação ilegal e abuso de poder
- Conheça as regras para o cabimento do habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.686 (2)", "page_number": 686, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso LXXIV, da Constituição Federal"], "jurisprudence": ["Súmula n.º 395, STF", "Súmula n.º 692, STF", "INF 778 - RHC 118622/ES"], "confidence": 0.8, "extracted_at": "2026-05-29T11:59:30.878628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=686", "doc_key": "0240d3b309b79f4b461f4257afa03a66"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '335f2733808fb629737c002e2015c70eb59fcf2fab9d9cf32708f2cf16582ffa'),
  ('cpiuris2025::e3cc076f2d3ca9c6c67d03c4077f42cb', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Cabimento', '## Habeas Corpus e Cabimento

O habeas corpus não é cabível para pleitear trancamento de processo de impeachment, nem para reexame de pressupostos de admissibilidade de recursos. Além disso, não é meio idôneo para discutir a legalidade de ato impugnado em execução penal.

### Conceitos
- **Habeas Corpus**: instrumento processual que tutela liberdade de locomoção
- **Cabimento**: reexame de pressupostos de admissibilidade de recursos
- **Trancamento de processo**: medida para suspender o andamento do processo
- **Execução penal**: execução das penas impostas pela lei
- **Restrição de visita**: limitação da liberdade de locomoção de uma pessoa

### Referências legais
- RISTF, art. 21; CPC, art. 557

### Jurisprudência
- INF 830 - HC 134315 AgR/DF
- HC 114293/MG
- INF 393 - HC nº 85.503/SP

### Dicas de prova
- Entenda a finalidade do habeas corpus e sua cabimento
- Conheça as exceções ao cabimento do habeas corpus em execução penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.687 (1)", "page_number": 687, "discipline": "Direito Processual Penal", "legal_refs": ["RISTF, art. 21; CPC, art. 557"], "jurisprudence": ["INF 830 - HC 134315 AgR/DF", "HC 114293/MG", "INF 393 - HC nº 85.503/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T11:59:54.654724+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=687", "doc_key": "e3cc076f2d3ca9c6c67d03c4077f42cb"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '37b14d44596e0bd88b4068d5082f0ec404fa70d84d21f13be453ae63833aa28a'),
  ('cpiuris2025::d89cd384e769d346d31d7050a0f7e9b7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Probatório Residual e Supremacia da Condenação', '## Probatório Residual e Supremacia da Condenação

A sentença condenatória não prejudica a análise da tese defensiva de que houve quebra da cadeia de custódia da prova, pois o caso envolve um fenômeno processual estático que se tornou comprovativo.

### Conceitos
- **Probatório Residual**: O direito do réu de apresentar provas em última instância para demonstrar sua inocência.
- **Supremacia da Condenação**: A ideia de que a sentença condenatória é superior e prevalece sobre as teses defensivas do réu.
- **Cadeia de Custódia da Prova**: O processo pelo qual a prova coletada é transmitida ao juiz, que a utiliza para condenar o réu.
- **Fenômeno Processual Estático**: Um evento ou processo que se torna estático e não modificável após a sua ocorrência.

### Referências legais
- Art. 319 do Código de Processo Penal

### Jurisprudência
- HC n. 653.515/RJ
- Súmula 439/STF

### Dicas de prova
- Pergunte sobre a diferença entre probatório residual e supremacia da condenação.
- Entenda o conceito de cadeia de custódia da prova e como ela se relaciona com a sentença condenatória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.687 (2)", "page_number": 687, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 319 do Código de Processo Penal"], "jurisprudence": ["HC n. 653.515/RJ", "Súmula 439/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:01:37.162424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=687", "doc_key": "d89cd384e769d346d31d7050a0f7e9b7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '71bd79168c9e40f17d21b144a133d4a25bea8639537a1c7fcc4e8627cb078a64'),
  ('cpiuris2025::b7fc13375eb810bbbcc8a5c4ada77d13', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Decisões Condenatórias', '## Habeas Corpus e Decisões Condenatórias

Resumo sobre a cabívelidade do habeas corpus em diferentes situações, incluindo decisões condenatórias.

### Conceitos
- **Habeas Corpus**: Ação judicial para garantir a liberdade de uma pessoa presa ou detida
- **Decisão Condenatória**: Sentença que condena o réu por um crime
- **Pena Pecuniária**: Pena que não envolve a privação da liberdade, mas pode ser paga em dinheiro
- **Liminar**: Decisão provisória que pode ser posteriormente rejeitada ou confirmada
- **Reconhecimento de Decadência**: Ação para negar a extinção da punibilidade por decadência

### Referências legais
- Art. 519, § 2º do CPP
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre decisões condenatórias que envolvem pena pecuniária e outras
- Entendimento da cabívelidade do habeas corpus em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.688 (2)", "page_number": 688, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 519, § 2º do CPP", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:01:58.156262+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=688", "doc_key": "b7fc13375eb810bbbcc8a5c4ada77d13"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5aa66f7a7dc84d0babe32e7fe79e5170d56672cf3e815e6f61bbc1274b0e703e'),
  ('cpiuris2025::4ef3bc6b30ff561449015b321d9497e9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Recursos Em Habeas Corpus', '## Habeas Corpus e Recursos Em Habeas Corpus

O habeas corpus não é meio idôneo para impugnar decisões de governador sobre medidas de adoção, nem para se pleitear o fornecimento de cópias de processo criminal. Além disso, o habeas corpus não constitui recurso interposto por advogado sem procuração.

### Conceitos
- **Habeas Corpus**: mandado judicial para garantir liberdade
- **Recursos Em Habeas Corpus**: recurso interposto para impugnar decisões de governador ou juiz
- **Capacidade Postulatória**: habilitação do advogado a representar o cliente no processo
- **Procuração**: outorga de poderes ao advogado para agir em nome do cliente

### Referências legais
- Art. 5º, LIV da CF; RDC no HC 700.487-RS

### Jurisprudência
- HC 111.561/SP
- AgRg no RHC 69.183/AM
- Súmula n.º 648, STJ; Súmula n.º 667, STJ

### Dicas de prova
- Distinguir entre habeas corpus e recursos em habeas corpus
- Entender a importância da capacidade postulatória e procuração no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.688 (1)", "page_number": 688, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF; RDC no HC 700.487-RS"], "jurisprudence": ["HC 111.561/SP", "AgRg no RHC 69.183/AM", "Súmula n.º 648, STJ; Súmula n.º 667, STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T12:02:05.070335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=688", "doc_key": "4ef3bc6b30ff561449015b321d9497e9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'f94598cbfe14a3b7931aa47b10592bf6f0917b822175ff1d2cfa1812f7c4974a'),
  ('cpiuris2025::9f7ebde4d9af57da2a124178a06d4802', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Coação', '## Habeas Corpus e Coação

Resumo objetivo: O habeas corpus não cabe contra a imposição de pena de exclusão ou coação ilegal, com exceção de casos em que a lei autoriza o uso da fiança.

### Conceitos
- **Habeas Corpus**: Ação para garantir a liberdade de locomoção
- **Coação**: Fato que impede a liberdade de escolha
- **Pena de Exclusão**: Pena que exclui o direito à função pública ou militar
- **Fiança**: Garantia para garantir o cumprimento da pena

### Referências legais
- Art. 648, inciso V, do CPP
- Súmula nº 694 do STF
- Súmula nº 395 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre coação e fiança
- Conhecimento de recurso de habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.689 (2)", "page_number": 689, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 648, inciso V, do CPP", "Súmula nº 694 do STF", "Súmula nº 395 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:03:50.764926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=689", "doc_key": "9f7ebde4d9af57da2a124178a06d4802"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2d9f91527f915dec2708661c2fd4492916ae9658aa41b8ec32cbd6f23e46cf87'),
  ('cpiuris2025::6388f60051616cdf73551e8e83f4271a', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus e Coação', '## Habeas Corpus e Coação

O habeas corpus é uma via própria para impugnar medidas ilegais de coação. A coação pode ser considerada ilegal em determinadas situações, como a manifesta nulidade do processo ou a extinção da punibilidade.

### Conceitos
- **Habeas Corpus**: via própria para impugnar medidas ilegais de coação
- **Coação**: medida que pode ser considerada ilegal em determinadas situações
- **Justa Causa**: necessária para a impetração do habeas corpus, quando não houver justa causa, o pedido é inadmissível

### Referências legais
- Art. 648, incisos VI e VII, do CPP
- Súmula nº 695 do STF
- Súmula nº 693 do STF
- Art. 648, inciso I, do CPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre coação ilegal e justa causa
- Importância da manifesta nulidade do processo para a impetração do habeas corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.689 (1)", "page_number": 689, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 648, incisos VI e VII, do CPP", "Súmula nº 695 do STF", "Súmula nº 693 do STF", "Art. 648, inciso I, do CPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T12:04:06.768080+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=689", "doc_key": "6388f60051616cdf73551e8e83f4271a"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ffb61299941656b09790429078d64f657452c09802b6b4baf400f412f9e14959'),
  ('cpiuris2025::044b873e757afcb6ab025864336e65ba', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Habeas Corpus', '## Habeas Corpus

Resumo objetivo: O habeas corpus é um recurso processual que visa garantir a liberdade de locomoção do réu, sendo inadmissível em determinadas situações e sujeito a regras específicas.

### Conceitos
- **Habeas Corpus**: Recurso processual que visa garantir a liberdade de locomoção do réu
- **Súmula nº 693 do STF**: Proíbe o habeas corpus contra decisão condenatória a pena de multa ou relativa a processo em curso por infração penal com pena pecuniária
- **Liminar**: Pedida de medida provisória para evitar o prejuízo do réu
- **Coação**: Ato que impede a liberdade de locomoção do réu
- **Punibilidade**: Período durante o qual o agente não é punido por uma infração penal
- **Decadência**: Causa extintiva da punibilidade

### Referências legais
- Art. 648, VII do CPP
- Súmula nº 693 do STF
- Art. 654 do CPP

### Jurisprudência
- RE 123456
- STJ. 2ª Turma. RDC no HC 700.487-RS

### Dicas de prova
- Entenda a regra de inadmissibilidade do habeas corpus contra decisão condenatória a pena de multa
- Conheça a jurisprudência sobre o manejo do habeas corpus em casos de coação e punibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.690", "page_number": 690, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 648, VII do CPP", "Súmula nº 693 do STF", "Art. 654 do CPP"], "jurisprudence": ["RE 123456", "STJ. 2ª Turma. RDC no HC 700.487-RS"], "confidence": 0.8, "extracted_at": "2026-05-29T12:04:55.042511+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=690", "doc_key": "044b873e757afcb6ab025864336e65ba"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '05dd2d926fca9dd07fd3d83753b363e83a9fab7071238e38186e96463f923f12'),
  ('cpiuris2025::f865a01735843473c6bb56670f855384', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança em Matéria Criminal', '## Mandado de Segurança em Matéria Criminal

O mandado de segurança em matéria criminal é ação autônoma que visa proteger direitos líquidos e certos, não amparados por habeas corpus ou habeas data. Sua regulamentação não está prevista no Código de Processo Penal, mas sim na Lei n.º 12.016/09.

### Conceitos
- **Mandado de Segurança**: Ação autônoma que visa proteger direitos líquidos e certos
- **Habeas Corpus**: Ação que busca garantir a liberdade de uma pessoa presa ou detida
- **Habeas Data**: Ação que busca garantir o direito à informação
- **Autoridade Pública**: Pessoa jurídica que exerce funções públicas
- **Agente de Pessoa Jurídica**: Pessoa física ou jurídica que atua em nome de uma autoridade pública

### Referências legais
- Art. 5º, inciso LXIX, CF/88
- Art. 23 da Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de mandado de segurança em matéria criminal e sua relação com o habeas corpus e o habeas data
- Conheça a regulamentação do mandado de segurança, que não está prevista no Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.692 (1)", "page_number": 692, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, inciso LXIX, CF/88", "Art. 23 da Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:06:28.283249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=692", "doc_key": "f865a01735843473c6bb56670f855384"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0288cfeea92b920b34147a033e90f9f74b4c4fe19c0778dc3b2d8230b2aa1259'),
  ('cpiuris2025::f23b4e614086c674f21911c4033bf3f6', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Prazo de decadência para impetração de mandado de segurança', '## Prazo de decadência para impetração de mandado de segurança

O prazo de decadência para a impetração de mandado de segurança é de cento e vinte dias, contados da data em que o interessado tomou conhecimento do ato a ser impugnado. O entendimento prevalece no sentido de que se trata de prazo decadencial, não estando sujeito a causas interruptivas e/ou suspensivas.

### Conceitos
- **Prazo de decadência**: Período durante o qual deve ser impetrada uma ação
- **Mandado de segurança**: Medida cautelar para proteger direito ou interesse legítimo
- **Impugnação**: Ação de questionar ou desafiar uma decisão ou ato administrativo

### Referências legais
- Art. 5º, LIV, da CF
- Súmula nº 632 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que o prazo de decadência é um prazo legal e não pode ser suspenso por causas interruptivas ou suspensivas.
- Lembre-se de que a perda do prazo não retira do interessado o direito propriamente dito, que poderá ser atingido pelas vias ordinárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.692 (2)", "page_number": 692, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF", "Súmula nº 632 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:06:28.285410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=692", "doc_key": "f23b4e614086c674f21911c4033bf3f6"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '21a00d3229902fa5c03858d901037c5c20c9043a30b6a7b3083a39de31949c8a'),
  ('cpiuris2025::886db519be3b0939610ce82c3596d774', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Cabimento do Mandado de Segurança em Matéria Criminal', '## Cabimento do Mandado de Segurança em Matéria Criminal

O mandado de segurança em matéria penal é cabível se for impugnada decisão que viola direito líquido e certo, não amparado por HC ou HD. Exige-se comprovação da ilegalidade ou do abuso de poder.

### Conceitos
- **Direito Líquido e Certo**: direito que pode ser imediatamente protegido
- **Habeas Corpus**: ação para garantir liberdade pessoal
- **Habeas Data**: ação para garantir direitos de propriedade
- **Atos Concretos**: atos que possam causar perigo ou restrição ao direito líquido e certo

### Referências legais
- Art. 1º da Lei n.º 12.016/19
- Súmula n.º 266 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre direito líquido e certo e direitos ilíquidos
- Comprovação da ilegalidade ou do abuso de poder
- Vedações ao ajuizamento do mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.693 (1)", "page_number": 693, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º da Lei n.º 12.016/19", "Súmula n.º 266 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:06:55.392796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=693", "doc_key": "886db519be3b0939610ce82c3596d774"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6dfbe9ca400718a733edfe7d5984eb0c21ce7e3c8b2e2f1beb0c16c5ecc5e8c1'),
  ('cpiuris2025::0c8df46bf77978b0c370adbfb36fa143', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Uso do Mandado de Segurança', '## Uso do Mandado de Segurança

O uso do mandado de segurança é limitado por leis e súmulas do STF, especialmente em relação a decisões judiciais com recurso cabível.

### Conceitos
- **Mandado de Segurança**: instrumento processual utilizado para tutelar direitos líquidos e certos
- **Caução**: exigência prevista na lei para ajuizamento do mandado de segurança
- **Recurso administrativo com efeito suspensivo**: recurso que pode ser apresentado contra ato administrativo com efeito suspensivo
- **Decisão judicial passível de recurso ou correição**: decisão judicial que pode ser recorrida ou corrigida
- **Súmula n.º 429 do STF**: súmula do STF que afirma a existência de recurso administrativo com efeito suspensivo não impede o uso do mandado de segurança
- **Súmula n.º 267 do STF**: súmula do STF que proíbe o uso do mandado de segurança contra ato judicial passível de recurso ou correição
- **Súmula n.º 268 do STF**: súmula do STF que afirma a utilização do MS contra decisão judicial já transitada em julgado é vedada

### Referências legais
- Art. 1031 do Código de Processo Civil
- Súmula n.º 429 do STF
- Súmula n.º 267 do STF
- Súmula n.º 268 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Mandado de Segurança

### Dicas de prova
- Entenda a limitação do uso do mandado de segurança em relação a decisões judiciais com recurso cabível.
- Conheça as súmulas do STF que regulamentam o uso do MS.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.693 (2)", "page_number": 693, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1031 do Código de Processo Civil", "Súmula n.º 429 do STF", "Súmula n.º 267 do STF", "Súmula n.º 268 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Mandado de Segurança"], "confidence": 0.8, "extracted_at": "2026-05-29T12:07:47.452840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=693", "doc_key": "0c8df46bf77978b0c370adbfb36fa143"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6a905cc0dd95b31dbd38f214c82b79560a5176d7559145a7aa6c3e2fd868eb5e'),
  ('cpiuris2025::279eb2ea59f2b9b6b5bfd8543379b88c', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança em matéria Criminal', '## Mandado de Segurança em matéria Criminal

O mandado de segurança é um recurso que visa impugnar atos do Poder Judiciário ou do Poder Executivo, com competência específica e funções definidas.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar uma causa
- **Mandado de Segurança**: Um recurso que visa impugnar atos do Poder Judiciário ou do Poder Executivo
- **Habeas Corpus**: Um recurso que visa garantir a liberdade de uma pessoa presa
- **Órgão Colegiado**: Um órgão do Tribunal que é composto por mais de um membro
- **Tribunal**: O órgão jurisdicional superior

### Referências legais
- Art. 1º, caput, c/c art. 6º, §3º, da Lei n.º 12.016/09

### Dicas de prova
- Diferenciar entre habeas corpus e mandado de segurança
- Entender a competência para julgamento do mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.695", "page_number": 695, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 1º, caput, c/c art. 6º, §3º, da Lei n.º 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:09:59.809026+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=695", "doc_key": "279eb2ea59f2b9b6b5bfd8543379b88c"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'd75e67b93b2af7c8d689f42afd3fb1c86241156b9019243582d7f0467397637b'),
  ('cpiuris2025::b8db65a9c728af6cfffa94bb2da602b1', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade passiva do Mandado de Segurança', '## Legitimidade passiva do Mandado de Segurança

O mandado de segurança pode ser impetrado por apenas um dos acusados e não requer a assinatura de advogado, mas sim alguém com capacidade postulatória. A legitimidade passiva recai sobre a autoridade responsável pela violência ou ameaça ao direito líquido e certo do impetrante.

### Conceitos
- **Legitimidade passiva**: O direito de agir em nome de outrem
- **Mandado de Segurança**: Ato processual que visa proteger um direito líquido e certo
- **Capacidade postulatória**: Habilidade para representar ou defender alguém em uma ação
- **Autoridade responsável**: Pessoa ou entidade que pratica o ato impugnado

### Referências legais
- Art. 5º, LIV, da CF; Art. 102 do CPP; Súmula 644/STJ

### Jurisprudência
- RE 426.370
- Tema repetitivo: Legitimidade passiva do MS

### Dicas de prova
- Pergunta sobre legitimidade passiva pode ser confusa, mas é importante entender que a autoridade responsável é o polo passivo
- Diferencie entre Mandado de Segurança e Habeas Corpus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.694 (2)", "page_number": 694, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV, da CF; Art. 102 do CPP; Súmula 644/STJ"], "jurisprudence": ["RE 426.370", "Tema repetitivo: Legitimidade passiva do MS"], "confidence": 0.8, "extracted_at": "2026-05-29T12:10:22.910539+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=694", "doc_key": "b8db65a9c728af6cfffa94bb2da602b1"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6ff0e80971f67d27c869d508a5959efa696b99963915089252d2a6d4d6109111'),
  ('cpiuris2025::2f6413c11763860f613c5f3fbd7b385e', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança em Materia Criminal', '## Mandado de Segurança em Materia Criminal

O mandado de segurança não se presta para atribuir efeito suspensivo a recurso criminal interposto pelo Ministério Público, conforme Súmula do STJ n.º 604.

### Conceitos
- **Mandado de Segurança**: instrumento processual que visa proteger direito líquido e certo
- **Legitimidade Ativa**: direito do sujeito passivo de impetrar ação ou recurso, especialmente no processo penal
- **Citação do Réu**: obrigação de citar o réu como litisconsorte passivo em mandado de segurança impetrado pelo Ministério Público

### Referências legais
- Art. 581, inciso V, do CPP
- Súmula n.º 604 do STJ
- Súmula n.º 701 do STF
- Lei n.º 12.016/09

### Jurisprudência
- RE 22.157/DF
- EDcl MS 22.157/DF

### Dicas de prova
- Distinção entre efeito suspensivo e eficácia imediata
- Importância da citação do réu em mandado de segurança impetrado pelo Ministério Público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.694 (1)", "page_number": 694, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 581, inciso V, do CPP", "Súmula n.º 604 do STJ", "Súmula n.º 701 do STF", "Lei n.º 12.016/09"], "jurisprudence": ["RE 22.157/DF", "EDcl MS 22.157/DF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:10:39.295272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=694", "doc_key": "2f6413c11763860f613c5f3fbd7b385e"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '389ade447056b71f52bc83d40caa68fb9be37baa64638dfae37034d43132b59b'),
  ('cpiuris2025::7fa739668792166ba03c7a8e8d3b7699', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para julgamento de Mandado de Segurança em matéria criminal', '## Competência para julgamento de Mandado de Segurança em matéria criminal

O artigo 7º, inciso III, da Lei n.º 12.016/09 estabelece que o juiz deve ordenar a suspensão do ato que deu motivo ao pedido e pode conceder liminar sem ouvir a parte contrária, com efeitos até a prolação da sentença.

### Conceitos
- **Competência**: A capacidade do juiz de julgar um caso
- **Mandado de Segurança**: Um pedido judicial que visa proteger uma pessoa jurídica ou física de um ato ilegal
- **Liminar**: Uma decisão provisória que pode ser tomada sem a oitiva da parte contrária
- **Recurso de Agravo de Instrumento**: Um recurso que pode ser apresentado para apelar uma decisão do juiz

### Referências legais
- Art. 7º, inciso III, da Lei n.º 12.016/09

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a competência para julgamento de Mandado de Segurança em matéria criminal
- Conheça as regras para conceder ou negar pedido de liminar
- Aprenda sobre o procedimento para julgar um Mandado de Segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.697", "page_number": 697, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º, inciso III, da Lei n.º 12.016/09"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:13:03.175596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=697", "doc_key": "7fa739668792166ba03c7a8e8d3b7699"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '61e5e359b1c656f776a6803fe0e23e537591c28be44b0d2e33083b584ab6d6ea'),
  ('cpiuris2025::b9a1f4bf664059caeee551fe7bbc79a0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Procedimento do Mandado de Segurança em Tribunais', '## Procedimento do Mandado de Segurança em Tribunais

O procedimento para o processamento do mandado de segurança nos tribunais será definido pelos regimentos internos, com algumas disposições especiais trazidas pela Lei n.º 12.016/09.

### Conceitos
- **Lei n.º 12.016/09**: Lei que trouxe disposições especiais sobre o procedimento do mandado de segurança nos tribunais.
- **Recurso cabível**: Ação que pode ser interposta contra uma decisão do relator que indeferiu a petição inicial ou defereu ou indefereu um pedido de liminar.
- **Competência para instrução do processo**: O relator é o responsável pela instrução do processo, com a defesa oral na sessão do julgamento do mérito ou do pedido liminar.
- **Agravo regimental**: Recurso que pode ser interposto contra uma decisão do relator que defereu ou indeferiu um pedido de liminar.

### Referências legais
- Art. 10, §1º, da Lei n.º 12.016/09
- Art. 16, caput, e parágrafo único, da Lei n.º 12.016/09

### Dicas de prova
- Entenda a competência para instrução do processo e o recurso cabível.
- Conheça as disposições especiais trazidas pela Lei n.º 12.016/09.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.698 (1)", "page_number": 698, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 10, §1º, da Lei n.º 12.016/09", "Art. 16, caput, e parágrafo único, da Lei n.º 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:13:27.328202+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=698", "doc_key": "b9a1f4bf664059caeee551fe7bbc79a0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9e4bcd3002c1e8860a5e4e4cfb8ff22879e45aeb739da5dfc88cbe406295a2ca'),
  ('cpiuris2025::d2fcba4f5cc548e8fb4f801c2eb902e7', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência para julgamento de mandados de segurança', '## Competência para julgamento de mandados de segurança

O Supremo Tribunal Federal, o Superior Tribunal de Justiça e os Tribunais Regionais Federais têm competência para processar e julgar mandados de segurança contra atos de autoridades federais e do próprio tribunal. Os Juízes Federais também têm competência para julgarem mandados de segurança contra atos de autoridades federais, excetuados os casos de competência dos Tribunais Regionais Federais.

### Conceitos
- **Competência**: A capacidade do tribunal ou juiz de processar e julgar uma ação
- **Mandado de segurança**: Ação judicial que visa proteger um direito ou interesse
- **Supremo Tribunal Federal**: O tribunal mais alto do país, competente para processar e julgar mandados de segurança contra atos de autoridades federais
- **Superior Tribunal de Justiça**: O tribunal que tem competência para processar e julgar mandados de segurança contra atos de autoridades federais e do próprio tribunal
- **Tribunal Regional Federal**: O tribunal regional federal é o tribunal competente para processar e julgar mandados de segurança contra atos de autoridades federais
- **Juiz Federal**: O juiz que tem competência para julgarem mandados de segurança contra atos de autoridades federais, excetuados os casos de competência dos Tribunais Regionais Federais

### Referências legais
- Art. 102, I, d da Constituição Brasileira
- Art. 105, I, b da Constituição Brasileira
- Art. 108, I, c da Constituição Brasileira
- Art. 109, VIII da Constituição Brasileira

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência para julgamento de mandados de segurança

### Dicas de prova
- Diferenciar entre competência dos Tribunais Regionais Federais e Juízes Federais
- Entender a diferença entre habeas corpus e mandado de segurança em relação à competência do tribunal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.696", "page_number": 696, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 102, I, d da Constituição Brasileira", "Art. 105, I, b da Constituição Brasileira", "Art. 108, I, c da Constituição Brasileira", "Art. 109, VIII da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência para julgamento de mandados de segurança"], "confidence": 0.8, "extracted_at": "2026-05-29T12:14:16.532068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=696", "doc_key": "d2fcba4f5cc548e8fb4f801c2eb902e7"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '0db7180aa23eb2c407414ce1b154a0e8d188d38bc01b648fd6b4bf5b521c6fa6'),
  ('cpiuris2025::cbd106a5aaa768142918004fc83b33bd', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Suspensão do ato que deu motivo ao pedido', '## Suspensão do ato que deu motivo ao pedido

A suspensão do ato que deu motivo ao pedido deve ser feita conforme o artigo 7º, inciso III. Após a expiração do prazo das informações, o juiz ouvirá o representante do Ministério Público dentro de 10 dias e proferirá decisão em 30 dias.

### Conceitos
- **Suspensão do ato que deu motivo ao pedido**: Dever de o juiz suspender o ato que deu origem ao pedido
- **Prazo improrrogável**: Prazo não flexível, dentro do qual deve ser concluído o procedimento
- **Ouvido do Ministério Público**: Dever de ouvir o representante do Ministério Público após a expiração do prazo das informações
- **Parecer do Ministério Público**: Opinião do representante do Ministério Público sobre o caso
- **Decisão do juiz**: Procedimento final do juiz após a conclusão dos autos

### Referências legais
- Art. 7º, inciso III
- Art. 12, caput

### Dicas de prova
- Pergunte sobre o prazo improrrogável e sobre o dever de ouvir o Ministério Público
- Entenda a importância do parecer do Ministério Público na decisão final', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.698 (2)", "page_number": 698, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 7º, inciso III", "Art. 12, caput"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:15:41.084523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=698", "doc_key": "cbd106a5aaa768142918004fc83b33bd"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'c95316adad0aa510875112203a1ea97d5a864e10ba216895525d05c9e741fb61'),
  ('cpiuris2025::24c0d4cca94b0ac87cf6e05a5642076d', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Utilização do Mandado de Segurança em Matéria Criminal', '## Utilização do Mandado de Segurança em Matéria Criminal

O mandado de segurança pode ser utilizado quando há ausência de meio legal para recorrer de uma decisão, especialmente em casos de indeferimento da habilitação do assistente de acusação.

### Conceitos
- **Mandado de Segurança**: instrumento processual que permite a impugnação de atos judiciais
- **Decisão que indefere a habilitação do assistente de acusação**: decisão que nega o direito à habilitação do assistente de acusação
- **Art. 273 do CPP**: disposição do Código de Processo Penal que regula a habilitação do assistente de acusação
- **Legitimados para a habilitação do assistente de acusação**: partes que têm direito à habilitação do assistente de acusação
- **Procurador legalmente habilitado**: advogado autorizado a representar o assistente de acusação

### Referências legais
- Art. 14, §2º da Lei n.º 12.016/09

### Dicas de prova
- Diferenciar entre recurso e mandado de segurança
- Entender a importância do art. 273 do CPP na habilitação do assistente de acusação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.699 (2)", "page_number": 699, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, §2º da Lei n.º 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:16:42.650007+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=699", "doc_key": "24c0d4cca94b0ac87cf6e05a5642076d"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '5b4dc3c993e32b2102124eee762152aa6f0f8a7a371485df3cc0ba388621dec8'),
  ('cpiuris2025::a583ccec664bd49da823f3e91ab192d0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Recursos cabíveis em mandado de segurança', '## Recursos cabíveis em mandado de segurança

Regra sobre recursos cabíveis em mandado de segurança, incluindo apelação, agravo regimental e recurso especial/extraordinário.

### Conceitos
- **Duplo Grau Obrigatório**: Sentença concessiva do mandado de segurança sujeita a reexame necessário
- **Reexame Necessário**: Condição imprescindível para o trânsito em julgado da sentença concessiva do mandado de segurança
- **Execução Provisória**: Admissibilidade da execução provisória da sentença concessiva do mandado de segurança, salvo em casos específicos
- **Agravo Regimental**: Recurso cabível para o órgão competente que integre a decisão do juiz de primeiro grau
- **Recurso Ordinário Constitucional**: Recurso cabível ao STJ ou STF em casos específicos
- **Recurso Especial**: Recurso cabível para o STJ em casos específicos
- **Recurso Extraordinário**: Recurso cabível para o STF em casos específicos

### Referências legais
- Art. 14, caput, da Lei n.º 12.016/09
- Art. 10, §1º, da Lei n.º 12.016/09
- Art. 105, inciso II, alínea b, CF/88
- Art. 102, inciso III, CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Recursos cabíveis em mandado de segurança

### Dicas de prova
- Distinção entre recursos cabíveis em casos de duplo grau obrigatório e não obrigatório
- Regras sobre execução provisória da sentença concessiva do mandado de segurança
- Importância de identificar o órgão competente para o agravo regimental', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.699 (1)", "page_number": 699, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, caput, da Lei n.º 12.016/09", "Art. 10, §1º, da Lei n.º 12.016/09", "Art. 105, inciso II, alínea b, CF/88", "Art. 102, inciso III, CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Recursos cabíveis em mandado de segurança"], "confidence": 0.8, "extracted_at": "2026-05-29T12:17:00.763707+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=699", "doc_key": "a583ccec664bd49da823f3e91ab192d0"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '073b60d9a02f1e1a11998a232039db6d20ef9735ba5accf5df5fca9aef1bd958'),
  ('cpiuris2025::10f65254a12d8b1304399fd163ec21e3', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança', '## Mandado de Segurança

O mandado de segurança é um recurso processual que pode ser recorrido pela autoridade coatora contra a sentença proferida no mandado de segurança.

### Conceitos
- **Mandado de Segurança**: Recurso processual
- **Art. 14, §2º, da Lei n.º 12.016/09**: Lei que estende o direito de recorrer contra a sentença proferida no MS
- **Capacidade postulatória**: Requisito para subscrito o MS
- **Habeas Corpus**: Ato privativo de advogado

### Referências legais
- Art. 14, §2º, da Lei n.º 12.016/09

### Dicas de prova
- Diferençar entre o MS e o Habeas Corpus
- Entender a capacidade postulatória para subscrito o MS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.701 (2)", "page_number": 701, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, §2º, da Lei n.º 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:18:41.565896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=701", "doc_key": "10f65254a12d8b1304399fd163ec21e3"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '2aca614a3bd2421fd77975fe0c3aadff79bf46c787ea3309d77f93ea48279c1e'),
  ('cpiuris2025::95359567e957a11657ad7f8fcaa92a8f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança em Processo Penal', '## Mandado de Segurança em Processo Penal

O mandado de segurança é um recurso que pode ser impetrado pelo Ministério Público ou por qualquer parte interessada contra decisões proferidas em processos criminais. A citação do réu como litisconsorte passivo é obrigatória quando o mandado de segurança for impetrado pelo Ministério Púbico.

### Conceitos
- **Mandado de Segurança**: Recurso que pode ser impetrado contra decisões proferidas em processos criminais
- **Citação do Réu**: Obrigatória quando o mandado de segurança for impetrado pelo Ministério Público
- **Litisconsorte Passivo**: Pessoa que deve ser citada como réu no mandado de segurança

### Referências legais
- Art. 14, caput, da Lei n.º 12.016/09

### Jurisprudência
- Súmula n.º 701 do STF
- Súmula n.º 376 do STJ

### Dicas de prova
- Distinção entre a citação do réu e o litisconsorte passivo
- Requisitos para impetrar mandado de segurança', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.701 (1)", "page_number": 701, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 14, caput, da Lei n.º 12.016/09"], "jurisprudence": ["Súmula n.º 701 do STF", "Súmula n.º 376 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T12:18:59.554236+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=701", "doc_key": "95359567e957a11657ad7f8fcaa92a8f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '62373fb76e8b20d5b0656990c3ffd7d91f13e57775bc01de6d5339e7e6cc83b9'),
  ('cpiuris2025::ae2428d054ff399c8214b2fbfc77a36b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança em Processo Penal', '## Mandado de Segurança em Processo Penal

O mandado de segurança é uma medida judicial que pode ser impetrada para proteger direitos individuais, como a liberdade de locomoção ou o acesso aos autos de investigação. A decisão do juiz pode ser recorrida, mas existem limitações e exceções.

### Conceitos
- **Mandado de Segurança**: Medida judicial para proteger direitos individuais
- **HC (Habeas Corpus)**: Recurso para anular decisão condenatória a pena de multa ou relativa a processo em curso por infração penal a que a pena pecuniária seja a única cominada
- **Súmula Vinculante**: Decisão do STF que tem força de lei e não pode ser alterada por outros tribunais
- **Recurso Ordinário**: Recurso apresentado ao tribunal que decidiu o caso, com limitações para apelar à Justiça Superior
- **Recurso Especial**: Recurso apresentado ao STJ para revisar a decisão do TRF
- **Recurso em Sentido Estrito**: Recurso apresentado para revisar uma decisão específica, sem alterar o resultado geral

### Referências legais
- Art. 5º, LIV da CF; Súmula n.º 693 do STF; Súmula Vinculante n.º 14 do STF

### Jurisprudência
- RE 123456
- Súmula n.º 405/STF
- Súmula n.º 423/STF
- Súmula n.º 510/STF
- Súmula n.º 105/STJ
- Súmula n.º 169/STJ
- Súmula n.º 376/STJ

### Dicas de prova
- Entenda a diferença entre HC e Mandado de Segurança
- Conheça as limitações do recurso em sentido estrito
- Aprenda sobre Súmulas Vinculantes e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.700", "page_number": 700, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 5º, LIV da CF; Súmula n.º 693 do STF; Súmula Vinculante n.º 14 do STF"], "jurisprudence": ["RE 123456", "Súmula n.º 405/STF", "Súmula n.º 423/STF", "Súmula n.º 510/STF", "Súmula n.º 105/STJ", "Súmula n.º 169/STJ", "Súmula n.º 376/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T12:19:24.814994+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=700", "doc_key": "ae2428d054ff399c8214b2fbfc77a36b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '35b8c49a2f4401a9e5f827bb5144a85db79f7d5d2b654f15fc6ab98d7a9b2f92'),
  ('cpiuris2025::1bc44c1a2f0afdc7e5427f35b54c4068', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Mandado de Segurança em Matéria Criminal', '## Mandado de Segurança em Matéria Criminal

A regulamentação do Mandado de Segurança em matéria criminal não está prevista no Código de Processo Penal, mas sim na Lei n.º 12.016/09.

### Conceitos
- **Mandado de Segurança**: instrumento processual que visa garantir a segurança do réu ou de terceiro
- **Lei n.º 12.016/09**: Lei que regula o Mandado de Segurança em matéria criminal

### Referências legais
- Artigo 5 da Lei n.º 12.016/09

### Dicas de prova
- Diferenciar do habeas corpus e da revisão criminal
- Conhecer a Lei n.º 12.016/09', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.702", "page_number": 702, "discipline": "Direito Processual Penal", "legal_refs": ["Artigo 5 da Lei n.º 12.016/09"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:20:24.730798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=702", "doc_key": "1bc44c1a2f0afdc7e5427f35b54c4068"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '383e7d7ef074ddaca7fadccbc130cf6534e559670f12c0d4ddf285bd957c7d28'),
  ('cpiuris2025::ff2db4c5f7aa655ea866331127bd1162', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

A revisão criminal é cabível contra sentenças condenatórias ou absolutórias impróprias, sendo possível a fundamentação do pedido em qualquer das hipóteses insertas nos incisos do art. 621 do CPP.

### Conceitos
- **Revisão Criminal**: Ação que visa revisar uma sentença condenatória ou absolutória imprópria
- **Turma Recursal**: Entidade responsável pela julgamento da revisão criminal no Juizado Especial Criminal
- **Legitimidade Ativa**: O direito de requerer a revisão criminal, que pode ser exercido pelo réu ou por procurador legalmente habilitado

### Referências legais
- Art. 622 do CPP
- Art. 623 do CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre revisão criminal e ação rescisória
- Conhecer as hipóteses que justificam a fundamentação do pedido de revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.705 (1)", "page_number": 705, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 622 do CPP", "Art. 623 do CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:21:19.504816+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=705", "doc_key": "ff2db4c5f7aa655ea866331127bd1162"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3d706c87c050107fcded49f7109f184218f8c00abdf99e79dcfe64b2c3b71085'),
  ('cpiuris2025::5435c2e08548ae0d8df94ec30a4a9c50', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

Ação autônoma de impugnação para desconstituir trânsito em julgado de sentença penal condenatória ou absolutória imprópria, corrigindo erros judiciários.

### Conceitos
- **Revisão Criminal**: Ação autônoma de impugnação para desconstituir trânsito em julgado de sentença penal condenatória ou absolutória imprópria.
- **Trânsito em Julgado**: Sentença penal condenatória ou absolutória imprópria que já transitou em julgado.
- **Erro Judiciário**: Ocorrencia de erro no processo que justifica a revisão criminal.

### Referências legais
- Art. 621, incisos I, II e III, CPP

### Jurisprudência
- Súmula n.º 18 do STJ

### Dicas de prova
- Entenda a natureza jurídica da revisão criminal como ação autônoma de impugnação.
- Conheça os pressupostos necessários para a revisão criminal: trânsito em julgado, sentença penal condenatória ou absolutória imprópria e demonstração de erro judiciário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.704", "page_number": 704, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 621, incisos I, II e III, CPP"], "jurisprudence": ["Súmula n.º 18 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T12:21:22.639485+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=704", "doc_key": "5435c2e08548ae0d8df94ec30a4a9c50"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '20a2e672f4f7a729df40618821ee34c3a91b95622f82facd76591b4ff47d8391'),
  ('cpiuris2025::b84371b29e64f285772231e95e6f781b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

A revisão criminal não exige capacidade postulatória, ao contrário do habeas corpus.

### Conceitos
- **Revisão Criminal**: Processo que visa a alteração de uma decisão penal já proferida
- **Habeas Corpus**: Mecanismo processual que visa a garantir o direito à liberdade pessoal
- **Capacidade Postulatória**: Habilidade jurídica necessária para propor uma ação ou recurso

### Referências legais
- Art. 585, § 3º do Código de Processo Penal

### Jurisprudência
- RvC 4886/1990
- HC 315.594/MG, 2016

### Dicas de prova
- Distinção entre revisão criminal e habeas corpus
- Entendimento da capacidade postulatória em revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.705 (2)", "page_number": 705, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º do Código de Processo Penal"], "jurisprudence": ["RvC 4886/1990", "HC 315.594/MG, 2016"], "confidence": 0.8, "extracted_at": "2026-05-29T12:21:33.657203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=705", "doc_key": "b84371b29e64f285772231e95e6f781b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '34c2b8aa7e63245a51bbeba03305c91d26c886306d4b9d0324d82034195e8835'),
  ('cpiuris2025::3c7481caf486e453e6957ac1cf706c06', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

A revisão criminal é permitida quando a sentença condenatória for contrária à lei penal ou à evidência dos autos, ou se descobrirem novas provas de inocência do condenado.

### Conceitos
- **Revisão Criminal**: Processo que visa revisar uma sentença condenatória
- **Contrariedade à Lei Penal**: Sentença condenatória que não se alinha com a lei penal aplicada
- **Evidência dos Autos**: Provas apresentadas durante o processo que sustentam a sentença

### Referências legais
- Art. 621, III do Código de Processo Penal

### Jurisprudência
- Súmula 456/STF

### Dicas de prova
- Entenda a diferença entre revisão criminal e recurso especial
- Conheça o artigo 621, III do Código de Processo Penal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.706 (2)", "page_number": 706, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 621, III do Código de Processo Penal"], "jurisprudence": ["Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:23:25.330421+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=706", "doc_key": "3c7481caf486e453e6957ac1cf706c06"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '9bb9e3e2d54b002d7e792d718d9d6ca95fa546b569ca539f92a41e0107a8dfc4'),
  ('cpiuris2025::b0341ca1260e50a8ac2448c31f73add8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

A revisão criminal não cabe para aplicar nova interpretação jurisprudencial em decisões já definitivamente julgadas, exceto em casos de abolitio criminis ou declaração de inconstitucionalidade.

### Conceitos
- **Revisão Criminal**: Ajuizamento de revisão criminal para aplicar nova interpretação jurisprudencial
- **Abolitio Criminis**: Declaração de que um crime não é crime mais uma vez
- **Declaração de Inconstitucionalidade**: Declaração do STF sobre a inconstitucionalidade de atos normativos

### Referências legais
- Art. 621 A 631, CPP

### Jurisprudência
- RE 113601
- RvC 4645
- RvC nº 5.457/SP-AgR
- HC 153805 AgR
- RvCr 3.900/SP

### Dicas de prova
- Distinção entre revisão criminal e ajuizamento de recurso
- Importância da competência para julgamento da revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.707 (1)", "page_number": 707, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 621 A 631, CPP"], "jurisprudence": ["RE 113601", "RvC 4645", "RvC nº 5.457/SP-AgR", "HC 153805 AgR", "RvCr 3.900/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T12:23:48.103283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=707", "doc_key": "b0341ca1260e50a8ac2448c31f73add8"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'dac3256bc6cc57c2330f0c4e910c72f7a58d40ff2924064db56938067e06f712'),
  ('cpiuris2025::dd73aaddefd0aebd2619e9c0d60e6cb4', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Legitimidade do Ministério Público para ajuizar revisão criminal', '## Legitimidade do Ministério Público para ajuizar revisão criminal

A legitimidade do Ministério Público para ajuizar revisão criminal é objeto de debate, com a maioria da doutrina defendendo sua legitimidade, mas a jurisprudência do STF não concorda, afirmando que o Estado-acusador não tem legitimidade para formalizar a revisão criminal.

### Conceitos
- **Legitimidade do Ministério Público**: O direito de agir em nome de outrem
- **Revisão Criminal**: Ação que visa revisar uma sentença de condenação
- **Causa Julgada**: Conceito jurídico que se refere à decisão final de um processo, que não pode ser reaberto

### Referências legais
- Art. 621 do CPP
- Súmula n.º 393 do STF

### Jurisprudência
- RHC nº 80.796/2001
- RE 123456

### Dicas de prova
- Entenda a diferença entre a legitimidade do Ministério Público e o direito de agir em nome de outrem
- Conheça as hipóteses de cabimento da revisão criminal previstas no art. 621 do CPP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.706 (1)", "page_number": 706, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 621 do CPP", "Súmula n.º 393 do STF"], "jurisprudence": ["RHC nº 80.796/2001", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T12:24:13.705159+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=706", "doc_key": "dd73aaddefd0aebd2619e9c0d60e6cb4"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '10a177701ae0e3a4cc4ed541aecfc47d8493c01f1d55969f4d8d614a5ca45e31'),
  ('cpiuris2025::bc940c9f6b6268f684c5027d8ce8fa12', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Competência e Revisão Criminal', '## Competência e Revisão Criminal

Regra de competência para a revisão criminal e procedimento a ser seguido.

### Conceitos
- **TRF**: Tribunal Regional Federal
- **TJ**: Tribunal de Justiça
- **Juizado Especial Criminal**: Vara especial do sistema judiciário para casos criminais
- **Turma Recursal**: Unidade recursal que processa e julga casos específicos

### Referências legais
- Art. 108, I, b, CF/88
- Art. 624, II, CPP

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência para a revisão criminal e o procedimento a ser seguido.
- Distinga entre TRF e TJ, Juizado Especial Criminal e Turma Recursal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.707 (2)", "page_number": 707, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 108, I, b, CF/88", "Art. 624, II, CPP"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:25:09.233278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=707", "doc_key": "bc940c9f6b6268f684c5027d8ce8fa12"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '6cfcf3bf7738912af200b95d40659f50572a048f4508d6b206d0040a8c146073'),
  ('cpiuris2025::c7d81752e133b337210220afb2da7950', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Jus Rescisorium e Pena Superior', '## Jus Rescisorium e Pena Superior

O jus rescisorium permite a substituição de uma decisão por outra melhor, sempre com o objetivo de melhorar a situação do réu. Para isso, é necessário um pedido expresso da parte requerente.

### Conceitos
- **Jus Rescisorium**: Permite a substituição de uma decisão por outra melhor
- **Error in Judicando**: Erro no julgamento que permite a substituição da decisão
- **Pena Superior**: Pena imposta sob pena de violação à proibição da reformativo in pejus

### Referências legais
- Art. 585, § 3º do Código de Processo Penal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de Jus Rescisorium e sua importância no Direito Processual Penal
- Identifique a condição necessária para que o jus rescisorium possa ser aplicado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.708 (2)", "page_number": 708, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º do Código de Processo Penal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T12:26:00.271611+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=708", "doc_key": "c7d81752e133b337210220afb2da7950"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '29ec7a68f94c94a8d6daabf279c3bef8f5f2d6b308c04383cd0b44a8b09d5dd0'),
  ('cpiuris2025::98ec44f020fb7252a45707ffe686d685', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

O pedido de revisão criminal pode demandar a produção de nova prova oral para comprovar a falsidade da anterior. A procedência do pedido somente beneficia o réu e não há chamada reformatio in pejus.

### Conceitos
- **Revisão Criminal**: Ação que visa corrigir ou alterar uma sentença anterior
- **Depoimento Falso**: Prova oral falsa apresentada em um processo
- **Justificação Prévia**: Procedimento aplicável ao processo penal para comprovar a falsidade de depoimentos
- **Chamada Reformatio in Pejus**: Proibição de agravamento da pena após a sentença inicial
- **Anulação da Sentença**: Atividade do juiz que anula uma sentença anterior

### Referências legais
- Art. 381, §5º, CPC; Art. 3º, CPP; Art. 626, parágrafo único, CPP

### Jurisprudência
- STJ, AgRg no REsp 2.037.387-SC
- RE 123456

### Dicas de prova
- Diferenciar jus rescindens e jus rescisorium
- Entender a limitação da chamada reformatio in pejus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.708 (1)", "page_number": 708, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 381, §5º, CPC; Art. 3º, CPP; Art. 626, parágrafo único, CPP"], "jurisprudence": ["STJ, AgRg no REsp 2.037.387-SC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T12:26:15.069399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=708", "doc_key": "98ec44f020fb7252a45707ffe686d685"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '62b8337b39bd2a108c417cd797de2ce530baa9f95c1cf736801dca3f8d08cfd7'),
  ('cpiuris2025::efb908e91d4baaa331b1243d2997be57', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal e Indenização', '## Revisão Criminal e Indenização

O artigo 630 do CPP permite a reconhecimento de direito à justa indenização pelos prejuízos sofridos, desde requerimento do interessado. A responsabilidade pela indenização é da União se o órgão prolator da sentença for vinculado à justiça federal ou do Distrito Federal e dos Territórios, e do Estado respectivo caso contrário.

### Conceitos
- **Revisão Criminal**: Ação que visa corrigir erro judiciário em sentença condenatória
- **Indenização**: Pagamento de indenização pelos prejuízos sofridos pelo acusado
- **Vinculação à Justiça Federal ou do Distrito Federal e dos Territórios**: O órgão prolator da sentença é vinculado à justiça federal ou do Distrito Federal e dos Territórios, o que determina a responsabilidade pela indenização
- **Erro Judiciário**: Materiação de fato ou circunstância não probada pelo acusado

### Referências legais
- Art. 630 do CPP
- Art. 5º, LXXV, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre erro judiciário e injustiça da condenação
- Conceito de responsabilidade pela indenização
- Reiteração de pedidos de revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.709 (1)", "page_number": 709, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 630 do CPP", "Art. 5º, LXXV, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:27:55.984469+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=709", "doc_key": "efb908e91d4baaa331b1243d2997be57"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '1bc204f730eaab678055ffa6f6a0b85c291321ba8e1e59704f342572581a3574'),
  ('cpiuris2025::2fed22c44e5ff58ceb2b6910af983714', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal e Recursos', '## Revisão Criminal e Recursos

A revisão criminal é ação originária de Tribunais ou Turmas Recursais, não cabendo apelação criminal. Somente são cabíveis embargos infringentes e de nulidade contra acórdãos desfavoráveis à Defesa.

### Conceitos
- **Revisão Criminal**: ação originária de Tribunais ou Turmas Recursais
- **Apelação Criminal**: não cabível em revisão criminal
- **Embargos Infringentes**: cabíveis contra acórdãos desfavoráveis à Defesa
- **Recurso Extraordinário**: cabível contra decisões de Turmas Recursais, segundo Súmula nº 640 do STF
- **Recurso Especial**: cabível, mas com inadmissibilidade específica em alguns casos
- **Turmas Recursais**: órgãos jurisdicionais que processam revisões criminais
- **Súmula nº 640 do STF**: define a admissibilidade de Recursos Extraordinários contra decisões de Turmas Recursais

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Súmula nº 640 do STF
- Súmula nº 203 do STJ

### Dicas de prova
- Diferenciar entre revisão criminal e apelação criminal
- Conhecer a admissibilidade dos recursos em revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.709 (2)", "page_number": 709, "discipline": "Direito Processual Penal", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Súmula nº 640 do STF", "Súmula nº 203 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T12:28:43.448118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=709", "doc_key": "2fed22c44e5ff58ceb2b6910af983714"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'be68e9db3453d3aed7ba12b365b511b33f657c93ce6b4725a116b1fa7d61b69d'),
  ('cpiuris2025::2338db91639a412756e87f5d650ab6b9', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal e Desconstituição de Acórdão', '## Revisão Criminal e Desconstituição de Acórdão

A revisão criminal não é cabível para se requerer a aplicação de lei penal mais benéfica durante a execução penal. O Superior Tribunal de Justiça pode desconstituir acórdãos de revisão criminal que foram fraudulently absolvidos, mas isso não significa que haja revisão criminal pro societate.

### Conceitos
- **Revisão Criminal**: Instituto processual que permite a revisão de uma decisão penal anterior
- **Desconstituição de Acórdão**: Ação do Tribunal para anular ou modificar um acórdão de revisão criminal
- **Fraude na Publicação do Julgamento da Revisão Criminal**: Ocorre quando o julgamento da revisão criminal é publicado, mas não foi provido

### Referências legais
- Art. 66, inciso I, da LEP
- Súmula nº 611 do STF

### Jurisprudência
- REsp 1.324.760-SP
- Informativo nº 555 - REsp
- RvCr 2.877-PE

### Dicas de prova
- Entenda a diferença entre revisão criminal e desconstituição de acórdão
- Conheça as regras para a aplicação da LEP e Súmula nº 611 do STF
- Aprenda a identificar fraude na publicação do julgamento da revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.710 (1)", "page_number": 710, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 66, inciso I, da LEP", "Súmula nº 611 do STF"], "jurisprudence": ["REsp 1.324.760-SP", "Informativo nº 555 - REsp", "RvCr 2.877-PE"], "confidence": 0.8, "extracted_at": "2026-05-29T12:29:00.396333+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=710", "doc_key": "2338db91639a412756e87f5d650ab6b9"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3d7c23d2850131a798b6a723c9530d2e8eefa0bd8e60c9ee4deb8ac8243a3cfd'),
  ('cpiuris2025::4bf0499cc81f84e8588f38b866ce2f3f', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal e Indenização ao Condenado', '## Revisão Criminal e Indenização ao Condenado

O pedido revisional pode ser deferido se a pena for diminuída equivocadamente, e o condenado sofrer prejuízos em virtude do erro judicial. A revisão é prática excepcional e somente justificada quando há contrariedade ao texto expresso da lei ou à evidência dos autos.

### Conceitos
- **Revisão Criminal**: Processo que visa alterar a sentença de um processo criminal
- **Indenização ao Condenado**: Pagamento feito ao condenado em virtude de erro judicial ou contrariedade à lei
- **Pleito Revisional**: Requerimento apresentado pelo condenado para revisar a sentença
- **Dosimetria da Pena**: Avaliação e ajuste da pena imposta ao condenado

### Referências legais
- Art. 585, § 3º do Código de Processo Civil
- Informativo nº 590 - REsp 1.243.516-SP

### Jurisprudência
- AgRg no AREsp 734.052/MS
- REsp 1.243.516-SP

### Dicas de prova
- Entenda a diferença entre revisão criminal e diminuição de pena
- Conheça o prazo para apresentar pleito revisional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.710 (2)", "page_number": 710, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 585, § 3º do Código de Processo Civil", "Informativo nº 590 - REsp 1.243.516-SP"], "jurisprudence": ["AgRg no AREsp 734.052/MS", "REsp 1.243.516-SP"], "confidence": 0.8, "extracted_at": "2026-05-29T12:30:19.651268+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=710", "doc_key": "4bf0499cc81f84e8588f38b866ce2f3f"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '80b076ef13f7026392dcc68e5737056e50f6712dabfd7b3716bff5d3ae72a846'),
  ('cpiuris2025::e49e54057a8a9ebff9ba57d1230d0c4b', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

A revisão criminal é uma ação autônoma que pode ser requerida para impugnar sentenças condenatórias ou absolutórias impróprias, com base em falsidade da prova ou novas provas de inocência do condenado.

### Conceitos
- **Revisão Criminal**: ação autônoma que pode ser requerida para impugnar sentenças condenatórias ou absolutórias impróprias
- **Falsidade da Prova**: prova incorreta ou enganosa utilizada para condenar o réu
- **Provas Novas**: novas provas que possam inocentá-lo do condenado ou diminuir a pena

### Referências legais
- Art. 621, CPP
- Art. 630, CPP

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Reconhecer o direito a uma justa indenização pelos prejuízos sofridos
- Falsidade da prova utilizada para condenar o réu ou de nova prova capaz de inocentá-lo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.711", "page_number": 711, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 621, CPP", "Art. 630, CPP"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:30:52.599952+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=711", "doc_key": "e49e54057a8a9ebff9ba57d1230d0c4b"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', '3478958ff5fbd36a9bf560f25316cff23948fa4f7ffda4f71b8e95708bb09c6a'),
  ('cpiuris2025::bfab91b5031f43fd70ffe8e0a8212148', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Revisão Criminal', '## Revisão Criminal

A revisão criminal é um recurso processual que pode ser requerido a qualquer tempo antes ou depois da extinção da pena. O réu não precisa estar representado por advogado constituído para ingressar com a revisão, mas existem precedentes do STF e do STJ que o apóiam.

### Conceitos
- **Revisão Criminal**: Recurso processual que pode ser requerido a qualquer tempo antes ou depois da extinção da pena
- **Advogado Constituído**: Não é necessário para o réu estar representado por advogado constituído para ingressar com a revisão criminal
- **Trânsito em Julgado**: É necessário que haja trânsito em julgado para que a revisão criminal seja cabível
- **Extinção da Pena**: A revisão criminal pode ser requerida antes ou depois da extinção da pena
- **Prazo Decadencial**: Não existe prazo decadencial para a revisão criminal
- **Requerimento de Revisão Criminal**: Pode ser feito a qualquer tempo, antes ou depois da extinção da pena

### Referências legais
- Art. 622 do CPP
- Art. 626 do CPP
- Súmula nº 393 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre a revisão criminal e a extinção da pena
- Entendimento do art. 622, caput, do CPP sobre a reiteração de pedidos de revisão criminal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf", "source_ref": "IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf · p.712", "page_number": 712, "discipline": "Direito Processual Penal", "legal_refs": ["Art. 622 do CPP", "Art. 626 do CPP", "Súmula nº 393 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:31:49.639353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Penal - Vol. 07 - 2025.pdf#page=712", "doc_key": "bfab91b5031f43fd70ffe8e0a8212148"}'::jsonb, '{"materia": "Direito Processual Penal"}'::jsonb, 'cp_iuris_2025', 'ade235a22e49c6e4f885fd8b2d228ca95af00dc93fd6eb6791d0c07e5a42d203'),
  ('cpiuris2025::3e9d8579cf02d540fe2d2b86883f8ba8', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Listagem de Informativos', '## Listagem de Informativos

Lista de números de informativos apresentados no texto, sem contexto específico.

### Conceitos
- **Informativo**: Elemento da lista
- **Números**: Elementos da lista numerada

### Dicas de prova
- Pergunte sobre a lista de números de informativos apresentados.
