  ('cpiuris2025::6c653e2aadf5b88a78616e012fcaf026', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Ações Diretas de Constitucionalidade e Agravo Regumental', '## Ações Diretas de Constitucionalidade e Agravo Regumental

Resumo objetivo: Este texto lista diversas ações diretas de constitucionalidade (ADI) e agravos regimentais (AgRg) com seus respectivos números, processos e decisões.

