  ('cpiuris2025::a5269b9842cdd03d123f9bcccad8aeb0', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Princípio do in dubio pro societate e reabertura de inquérito policial arquivado por excludente de ilicitude', '## Princípio do in dubio pro societate e reabertura de inquérito policial arquivado por excludente de ilicitude

Resumo objetivo: O princípio do in dubio pro societate é aplicado na reabertura de inquéritos policiais arquivados por excludente de ilicitude, considerando a dúvida razoável sobre a existência da ilicitude. Além disso, a jurisprudência destaca a necessidade de uma abordagem cautelosa ao reabrir inquéritos arquivados.

### Conceitos
- **Princípio do in dubio pro societate**: Aplicação do princípio da dúvida razoável para reabertura de inquéritos policiais arquivados por excludente de ilicitude
- **Reabertura de inquérito policial**: Ação que visa reativar um inquérito policial arquivado
- **Excludente de ilicitude**: Condição que justifica a não imputação de crime ao autor, considerando que o agir não é punível por lei

### Referências legais
- Art. 107, § 3º, do Código de Processo Penal

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Reabertura de inquérito policial arquivado por excludente de ilicitude''}

### Dicas de prova
- Entenda o princípio do in dubio pro societate e sua aplicação na reabertura de inquéritos policiais
