  ('cpiuris2025::952a8bc963bcf43d0beb55e2d483b899', 'doutrina', 'cp_iuris', 'Direito Processual Penal — Condução Coercitiva como Cautelar Pessoal Autônoma', '## Condução Coercitiva como Cautelar Pessoal Autônoma

