  ('cpiuris2025::ee89c3ec36edf3f73dd4b8c2440146b4', 'doutrina', 'cp_iuris', 'Direito Tributário — Introdução ao Direito Tributário', '## Introdução ao Direito Tributário

Resumo objetivo: Este texto apresenta a introdução ao direito tributário, destacando sua importância e estrutura. O direito tributário é um ramo do direito que se preocupa com as relações entre o Estado e os contribuintes, abordando temas como a natureza dos tributos, a competência para cobrar tributos e a responsabilidade do contribuinte.

### Conceitos
- **Direito Tributário**: Ramo do direito que se preocupa com as relações entre o Estado e os contribuintes
- **Tributo**: Contribuição obrigatória imposto pelo Estado sobre a pessoa jurídica ou física
- **Contribuinte**: Pessoa jurídica ou física obrigada a pagar tributos

### Referências legais
- Art. 110 da CF
- ...

### Jurisprudência
- RE 123456
- ...

