- Conheça as fontes do direito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.4 (1)", "page_number": 4, "discipline": "Direito Tributário", "legal_refs": ["Art. 2º, CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:42:17.187551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=4", "doc_key": "5a011a5d385f4732e45e5b8da296c9e1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6df20d254e46a1cbc08bcc757e5ef1c367a8f454ec544c2f20c18d2f0ea65bfc'),
  ('cpiuris2025::1f414efd0cdc4dd2a99f3b7ea03f7aa6', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária e Capacidade Tributária Ativa', '## Competência Tributária e Capacidade Tributária Ativa

O capítulo discute a competência tributária e a capacidade tributária ativa, incluindo a delegabilidade e a relação entre as duas.

### Conceitos
- **Competência Tributária**: A competência tributária é o direito do Estado de exigir impostos ou taxas de uma pessoa ou entidade.
- **Capacidade Tributária Ativa**: A capacidade tributária ativa é a situação em que um contribuinte tem direito a não ser tributado por determinada fonte de renda.
- **Delegabilidade**: A delegabilidade é o poder do Estado de outorgar a outrem a competência tributária, ou seja, a capacidade de exigir impostos ou taxas.

### Referências legais
- Art. 100 da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: delegabilidade

