  ('cpiuris2025::63ee7f7366b81360dad5283c64bca1d2', 'doutrina', 'cp_iuris', 'Direito Tributário — Limitações constitucionais ao poder de tributar', '## Limitações constitucionais ao poder de tributar

Discute-se a limitação do poder de tributar pela Constituição Federal de 1988, abordando princípios e imunidades tributárias.

### Conceitos
- **Capacidade Contributiva**: O direito de um contribuinte a ser isento ou não de certos impostos
- **Legalidade**: A necessidade de que as leis e atos do Poder Público sejam feitos em conformidade com a Constituição
- **Isonomia**: O princípio de igualdade perante a lei, garantido pela Constituição Federal
- **Não Surpresa**: A não aplicação de penalidades excessivas ou injustas aos contribuintes
- **Irretroatividade**: O princípio que proíbe a retroatividade de leis e atos que aumentem ou diminuam benefícios tributários

### Referências legais
- Art. 150 da CF/88
- Súmula 773 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Limitações constitucionais ao poder de tributar

### Dicas de prova
- Entenda a capacidade contributiva e sua importância
- Aprenda a aplicar o princípio da legalidade em casos práticos
- Conheça as imunidades tributárias e suas exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.4 (3)", "page_number": 4, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88", "Súmula 773 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Limitações constitucionais ao poder de tributar"], "confidence": 0.8, "extracted_at": "2026-05-29T12:44:28.958218+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=4", "doc_key": "63ee7f7366b81360dad5283c64bca1d2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '4b7140d27537857583a19ac315497eabd27c79ded5cd813c08252ac37a8a933e'),
  ('cpiuris2025::4a4802342fc0628b230a7d546921280d', 'doutrina', 'cp_iuris', 'Direito Tributário — Princípios Gerais do Direito Tributário', '## Princípios Gerais do Direito Tributário

Resumo de principais princípios tributários, incluindo a anterioridade, vedação ao confisco e imunidades.

### Conceitos
- **Anterioridade**: Regra que determina que os impostos devem ser aplicados à base do valor real da coisa ou pessoa alvo
- **Vedação ao Confisco**: Princípio que proíbe o confisco de bens sem a devida autorização legal
- **Imunidade**: Condição que exime uma pessoa jurídica ou física do pagamento de um imposto
- **Tipicidade Tributária**: Regra que determina que o imposto deve ser aplicado apenas ao valor real da coisa ou pessoa alvo
- **Non Olet**: Princípio que proíbe a alteração de leis tributárias sem a devida autorização legal
- **Responsabilidade Fiscal**: Condição que determina que o contribuinte é responsável pelo pagamento do imposto

### Referências legais
- Art. 150, VI, ''a'' da CF/88
- Súmula 646 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Imunidades Tributárias

### Dicas de prova
- Entenda a anterioridade e sua aplicação prática
- Conheça as diferentes formas de imunidade tributária
- Avalie a responsabilidade fiscal do contribuinte', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.5 (1)", "page_number": 5, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, ''a'' da CF/88", "Súmula 646 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Imunidades Tributárias"], "confidence": 0.8, "extracted_at": "2026-05-29T12:45:15.596911+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=5", "doc_key": "4a4802342fc0628b230a7d546921280d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b44179dbd79fd57021d4326df7452e32abc3dcec272d813554b72513f54339c3'),
  ('cpiuris2025::8907f152b415f9d9030e2cafb0fc187a', 'doutrina', 'cp_iuris', 'Direito Tributário — Imunidades Tributárias', '## Imunidades Tributárias

Descreve as imunidades tributárias objetivas e subjetivas, bem como as imunidades especiais aos impostos.

### Conceitos
- **Art. 153, § 4º, I da CF/88**: Imunidade objetiva-subjetiva
- **Imunidade recíproca**: Exceção tributária que exclui a incidência de impostos sobre determinados tipos de receitas
- **ICMS**: Imposto sobre a Renda ou Serviços de State
- **ISSQN**: Imposto Sobre o Valor Acrescido
- **Imunidade dos templos**: Exceção tributária que exclui a incidência de impostos sobre instituições religiosas
- **Imunidade cultural**: Exceção tributária que exclui a incidência de impostos sobre obras culturais
- **Músicas nacionais**: Exceção tributária que exclui a incidência de impostos sobre músicas nacionais
- **Taxas e contribuições**: Exceções tributárias que excluem a incidência de taxas e contribuições

### Referências legais
- Art. 153, § 4º, I da CF/88
- EC 132/2023

### Dicas de prova
- Entenda a distinção entre imunidades objetivas e subjetivas
- Conheça as exceções tributárias especiais aos impostos
- Avalie a importância da emenda constitucional n. 116/2022', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.5 (2)", "page_number": 5, "discipline": "Direito Tributário", "legal_refs": ["Art. 153, § 4º, I da CF/88", "EC 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:46:42.470309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=5", "doc_key": "8907f152b415f9d9030e2cafb0fc187a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'f542f0495dbbaf67e48e0c3858eb906a04fa7417df64573d9b74040711d701cb'),
  ('cpiuris2025::f4136e14893c681931f3c1ba6696f4e7', 'doutrina', 'cp_iuris', 'Direito Tributário — Legislação Tributária', '## Legislação Tributária

O capítulo aborda a legislação tributária, incluindo leis complementares, normas complementares e sua aplicação.

### Conceitos
- **Lei Complementar**: Lei que complementa a Constituição Federal
- **Normas Complementares Tributárias**: Regras adicionais que regulamentam a legislação tributária
- **Art. 98 do CTN**: Tratados Internacionais são considerados fonte de direito tributário
- **Art. 100 do CTN**: Normas complementares tributárias são regras adicionais que regulamentam a legislação tributária

### Referências legais
- Art. 98 do CTN
- Art. 100 do CTN
- CF/88, art. 155, § 3º

### Dicas de prova
- Entenda a hierarquia entre leis complementares e ordinárias
- Conheça as normas complementares tributárias e sua aplicação
- Análise dos tratados internacionais como fonte de direito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.5 (3)", "page_number": 5, "discipline": "Direito Tributário", "legal_refs": ["Art. 98 do CTN", "Art. 100 do CTN", "CF/88, art. 155, § 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:46:51.971463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=5", "doc_key": "f4136e14893c681931f3c1ba6696f4e7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fabc57dc88d13c66e3660193fc0028833240a3ebe4f4696bb1a60798dafe2e32'),
  ('cpiuris2025::102e3b01f85103070e8a89915f8cc654', 'doutrina', 'cp_iuris', 'Direito Tributário — Interpretação e integração da legislação tributária', '## Interpretação e integração da legislação tributária

Capítulo que aborda a interpretação das leis tributárias, incluindo a literal e a interpretativa, bem como a repercußão geral do STF.

### Conceitos
- **Interpretação Literal**: interpretação baseada no texto literal da lei
- **Repercußão Geral**: aplicação de uma decisão do STF a outras áreas do direito tributário

### Referências legais
- Art. 111 do CTN
- Art. 144, § 1º do CTN

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre interpretação literal e interpretativa
- Conheça a repercußão geral do STF em questões tributárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.6 (1)", "page_number": 6, "discipline": "Direito Tributário", "legal_refs": ["Art. 111 do CTN", "Art. 144, § 1º do CTN"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T12:46:57.690409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=6", "doc_key": "102e3b01f85103070e8a89915f8cc654"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6ee842917229d6d5824be9adbd55c741ab9137bcf6f025d83e536a69da778801'),
  ('cpiuris2025::04154a52cbcec334f3c72609210a3da5', 'doutrina', 'cp_iuris', 'Direito Tributário — Responsabilidade Tributária e Lançamento Tributário', '## Responsabilidade Tributária e Lançamento Tributário

O capítulo aborda a responsabilidade tributária, incluindo substituição tributária e responsabilidade no CTN, além do lançamento tributário, suas modalidades e questões relacionadas.

### Conceitos
- **Substituição Tributária**: Prática de reduzir o valor do imposto devido ao substituir um bem ou serviço por outro com menor valor.
- **Responsabilidade Tributária no CTN**: O regime de responsabilidade tributária estabelecido pelo Código Tributário Nacional (CTN).
- **Lançamento Direito ou de Ofício**: Método de lançamento do imposto devido, onde o contribuinte declara o valor do imposto devido e é homologado pela autoridade tributária.
- **Lançamento por Declaração**: Método de lançamento do imposto devido, onde o contribuinte declara o valor do imposto devido, mas não é homologado pela autoridade tributária.
- **Lançamento por Homologação**: Método de lançamento do imposto devido, onde a autoridade tributária homologa o valor do imposto devido apresentado pelo contribuinte.
- **Constituição Definitiva e Provisória**: A definição da constituição definitiva e provisória do crédito tributário, que pode ser feita por meio de lançamento definutivo ou provisório.
- **Inauguração do Processo Administrativo**: O início do processo administrativo para a defesa do contribuinte, que é iniciado após a constatação da ocorrência de fato gerador do imposto.

### Referências legais
- Art. 145 do CTN
- Art. 166 do CTN

### Jurisprudência
- RE 123456
- Súmula 345/STF

### Dicas de prova
- Entenda a substituição tributária e sua importância no lançamento tributário.
- Conheça as diferentes modalidades de lançamento tributário e suas características.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.6 (2)", "page_number": 6, "discipline": "Direito Tributário", "legal_refs": ["Art. 145 do CTN", "Art. 166 do CTN"], "jurisprudence": ["RE 123456", "Súmula 345/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:48:02.102399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=6", "doc_key": "04154a52cbcec334f3c72609210a3da5"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '87d65032383263d7d4b56f08dc0aa4a20eacddbe8426f1aec1056bd3cb09e5ae'),
  ('cpiuris2025::d03a2fdacddfe02860543df12c749fdb', 'doutrina', 'cp_iuris', 'Direito Tributário — Suspensão do crédito tributário', '## Suspensão do crédito tributário

O crédito tributário pode ser suspenso por meio de moratória ou parcelamento, permitindo ao contribuinte uma suspensão temporária do pagamento do crédito.

### Conceitos
- **Moratória**: Suspensão do pagamento do crédito tributário por tempo determinado
- **Parcelamento**: Divisão do crédito tributário em parcelas menores, permitindo ao contribuinte um período mais longo para o pagamento

### Referências legais
- Art. 109 da CF
- Súmula 634/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Suspensão do crédito tributário

### Dicas de prova
- Diferenciar entre moratória e parcelamento
- Entender a importância da notificação para pagamento na constituição definitiva do crédito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.6 (3)", "page_number": 6, "discipline": "Direito Tributário", "legal_refs": ["Art. 109 da CF", "Súmula 634/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Suspensão do crédito tributário"], "confidence": 0.8, "extracted_at": "2026-05-29T12:50:05.810848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=6", "doc_key": "d03a2fdacddfe02860543df12c749fdb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a11349e318f45f85cc1ac945a9d62fa4d18ea674e1611c1826a7e7611daf29a2'),
  ('cpiuris2025::6a8acb44d9d8cf02e1611c58ef707e00', 'doutrina', 'cp_iuris', 'Direito Tributário — Infrações e Delitos Tributários', '## Infrações e Delitos Tributários

Trata-se de capítulo que aborda o direito tributário penal e penal tributário, bem como a interpretação benigna das sanções tributárias, denúncia espontânea e execução fiscal.

### Conceitos
- **Direito Tributário Penal**: Brancha do direito que se occupa de punir as infrações tributárias
- **Direito Penal Tributário**: Sub-brancha do direito penal que se ocupa de punir os tributos
- **Interpretação Benigna**: Técnica utilizada para interpretar as sanções tributárias de forma mais favorável ao contribuinte
- **Denúncia Espontânea**: Ação realizada pelo contribuinte que denuncia a ocorrência de uma infração tributária sem a necessidade de uma investigação formal

### Referências legais
- Art. 208 do CTN

### Jurisprudência
- Súmula 487/STJ

### Dicas de prova
- Entenda a distinção entre direito tributário penal e penal tributário
- Conheça a interpretação benigna das sanções tributárias e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.7 (2)", "page_number": 7, "discipline": "Direito Tributário", "legal_refs": ["Art. 208 do CTN"], "jurisprudence": ["Súmula 487/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T12:50:47.083217+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=7", "doc_key": "6a8acb44d9d8cf02e1611c58ef707e00"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ea0c559ee4c25435f9cb9dba1827b233023eec3a7f627977fe5350e39b1e6989'),
  ('cpiuris2025::048e5f770914076c320a3618717968f7', 'doutrina', 'cp_iuris', 'Direito Tributário — Administração Tributária', '## Administração Tributária

Capítulo que aborda a administração tributária, incluindo fiscalização, sanções políticas e sigilo tributário.

### Conceitos
- **Fiscalização**: Ação do Estado para controlar e monitorar o cumprimento das obrigações fiscais.
- **Sanções Políticas**: Medidas adotadas pelo Estado para punir ou penalizar a não observância de normas tributárias.
- **Sílio Tributário**: Princípio que protege a privacidade das informações tributárias, proibindo o acesso não autorizado.
- **Responsabilização**: O dever de responder perante o Estado por suas obrigações fiscais.
- **Não submissão ao Sílio Tributário**: Ação que permite a divulgação de informações tributárias em determinados casos.
- **Sílio Bancário**: Princípio que protege a privacidade das informações bancárias, proibindo o acesso não autorizado.

### Referências legais
- Art. 194 a 200 do CTN

### Dicas de prova
- Entenda a importância da fiscalização e sanções políticas no contexto tributário.
- Conheça as regras de sigilo tributário e bancário para proteger a privacidade das informações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.7 (1)", "page_number": 7, "discipline": "Direito Tributário", "legal_refs": ["Art. 194 a 200 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:51:06.924263+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=7", "doc_key": "048e5f770914076c320a3618717968f7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8d8a6bb9b81bbdfe1a96e392a6e7f4f6419073503fd736a49dcb572a081046b3'),
  ('cpiuris2025::5e47fe190769be947ca96e359e3828bc', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos sobre Importação, Exportação e Renda', '## Impostos sobre Importação, Exportação e Renda

Discute as regras gerais para os impostos de importação, exportação e renda, incluindo contribuintes, bases de cálculo, alíquotas e lançamentos.

### Conceitos
- **Contribuinte**: Pessoa física ou jurídica responsável pelo pagamento do imposto
- **Base de cálculo**: Valor do bem ou serviço sujeito à tributação
- **Alíquota**: Taxa percentual aplicada à base de cálculo para calcular o valor do imposto
- **Lançamento**: Registro do imposto pago ou devido em um registro oficial
- **Tributação exclusiva**: Obrigação de pagar impostos sobre a importação ou exportação de bens

### Referências legais
- Art. 153, I, da CF/88
- Súmula 455 do STF

### Jurisprudência
- RE 123456/2019
- Tema repetitivo: Tributação exclusiva

### Dicas de prova
- Entenda a distinção entre contribuinte e responsável pelo imposto
- Conheça as bases de cálculo para cada tipo de imposto
- Identifique as alíquotas aplicáveis ao imposto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.7 (3)", "page_number": 7, "discipline": "Direito Tributário", "legal_refs": ["Art. 153, I, da CF/88", "Súmula 455 do STF"], "jurisprudence": ["RE 123456/2019", "Tema repetitivo: Tributação exclusiva"], "confidence": 0.8, "extracted_at": "2026-05-29T12:52:39.535203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=7", "doc_key": "5e47fe190769be947ca96e359e3828bc"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '99007330c31a375392308e5f3f3581039a8212b165a2e289553035b42eb2b6ce'),
  ('cpiuris2025::9ba7e91915d5599c19c5fa0f3b849e26', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos Residuais e IGF', '## Impostos Residuais e IGF

Resumo do capítulo sobre impostos residuais e IGF, incluindo a definição de cada um e suas características.

### Conceitos
- **Fato gerador**: Elemento que determina a incidência do imposto
- **Competência**: Entidade responsável por cobrar o imposto
- **Base de cálculo**: Valor utilizado para calcular a alíquota do imposto
- **Alíquota**: Taxa percentual aplicada à base de cálculo para determinar o valor do imposto

### Referências legais
- Art. 155 da CF
- Súmula 646/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: competência tributária

### Dicas de prova
- Entenda a noção de fato gerador e sua importância na incidência do imposto
- Conheça as diferentes formas de competência tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.8 (2)", "page_number": 8, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da CF", "Súmula 646/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência tributária"], "confidence": 0.8, "extracted_at": "2026-05-29T12:53:12.451103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=8", "doc_key": "9ba7e91915d5599c19c5fa0f3b849e26"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'e3ebef3a7612d3eddce1ed8214cbfc3db6dcb7b7c6450d0d4476866f508cfb58'),
  ('cpiuris2025::b17d097b12cee0d7a4164bed76162e51', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos sobre Produtos e Operações Financeiras', '## Impostos sobre Produtos e Operações Financeiras

Trecho que detalha as regras para os impostos IPI, IOF e ITR, incluindo fato gerador, base de cálculo, alíquotas e lançamento.

### Conceitos
- **Base de cálculo**: Valor utilizado para calcular o valor do imposto
- **Contribuinte**: Pessoa física ou jurídica responsável pelo pagamento do imposto
- **Fato gerador**: O evento que gera a obrigação de pagar o imposto
- **Imunidade**: Exceção ao pagamento do imposto
- **Lançamento**: Ação de registrar o valor do imposto em uma declaração ou documento
- **Alíquota**: Taxa percentual aplicada ao valor da base de cálculo para calcular o valor do imposto

### Referências legais
- Art. 155 da Lei nº 10.865/2004
- Súmula 646 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo IPI e IOF

### Dicas de prova
- Entenda a diferença entre base de cálculo e fato gerador
- Conheça as alíquotas aplicáveis para cada imposto
- Lembre-se de que o lançamento do imposto é obrigatório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.8 (1)", "page_number": 8, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da Lei nº 10.865/2004", "Súmula 646 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo IPI e IOF"], "confidence": 0.8, "extracted_at": "2026-05-29T12:53:26.025921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=8", "doc_key": "b17d097b12cee0d7a4164bed76162e51"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '2f149ada45e7f0c62e32d0b6c496764988831ae3ef005346125a1cbfc055a2c7'),
  ('cpiuris2025::6d2b06203b289afb26e265dc10fe6d0f', 'doutrina', 'cp_iuris', 'Direito Tributário — Fato Gerador', '## Fato Gerador

Define o fato gerador como a ocorrência de um evento que gera direito tributário.

### Conceitos
- **Fato Gerador**: Ocorrencia de um evento que gera direito tributário.
- **Evento**: Ação ou ocorrência que gera um direito ou obrigação.

### Referências legais
- Art. 29 da Lei nº 10.865/2004

### Dicas de prova
- Entenda a noção de fato gerador como o evento que gera direito tributário.
- Diferencie entre fato gerador e fato gênero.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.8 (4)", "page_number": 8, "discipline": "Direito Tributário", "legal_refs": ["Art. 29 da Lei nº 10.865/2004"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:54:41.069059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=8", "doc_key": "6d2b06203b289afb26e265dc10fe6d0f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '392815bb3420318aa34bf1de0b720fd0defb30e96c198b1c4d4ccbf8c51759dd'),
  ('cpiuris2025::033ac7dcb96d03d3f3f956e01f1d67f4', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuintes do ICMS e outros aspectos tributários', '## Contribuintes do ICMS e outros aspectos tributários

Este capítulo aborda os contribuintes do ICMS, não cumulatividade, alíquotas, imunidades, convênios de ICMS, substituição tributária progressiva e outros casos jurisprudenciais relacionados ao imposto de valor agregado.

### Conceitos
- **Contribuinte**: Pessoa jurídica ou física obrigada a pagar o ICMS
- **Não cumulatividade**: Regra que proíbe a acumulação de impostos sobre a mesma atividade econômica
- **Alíquota**: Taxa percentual aplicada ao valor da base de cálculo para calcular o valor do ICMS
- **Imunidade**: Exceção à obrigação de pagar o ICMS em determinadas situações
- **Convênio de ICMS**: Acordo entre os estados ou municípios para reduzir ou eximir o ICMS
- **Substituição tributária progressiva**: Mecanismo que reduz a alíquota do ICMS à medida que o valor da transação aumenta

### Referências legais
- Art. 155 da CF
- Súmula 646/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Contribuinte e não cumulatividade

### Dicas de prova
- Entenda a noção de contribuinte do ICMS
- Conheça as regras de não cumulatividade e imunidades
- Aprenda a calcular as alíquotas do ICMS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.8 (3)", "page_number": 8, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da CF", "Súmula 646/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Contribuinte e não cumulatividade"], "confidence": 0.8, "extracted_at": "2026-05-29T12:55:50.294439+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=8", "doc_key": "033ac7dcb96d03d3f3f956e01f1d67f4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '452a1bf31fb19acad114f4289ef0139a77e3845826bd6c0f3cb18ba49259268d'),
  ('cpiuris2025::cea50ab21ccfbc679b239e3bd60574b1', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição e estrutura do Imposto de Renda', '## Definição e estrutura do Imposto de Renda

O texto apresenta a estrutura do Imposto de Renda, incluindo zona urbana, base de cálculo, alíquota, lançamento e extrafiscalidade.

### Conceitos
- **Zona urbana**: Área definida pela legislação para fins fiscais
- **Base de cálculo**: Valor do patrimônio ou renda sujeito à tributação
- **Alíquota**: Taxa percentual aplicada à base de cálculo para calcular o valor do imposto
- **Lançamento**: Atividade que gera renda ou patrimônio sujeito à tributação
- **Extrafiscalidade**: Ações do Estado que não são tributárias, mas que afetam a economia
- **Progressividade**: Princípio de que os impostos são aplicados em percentual maior aos rendimentos mais altos
- **EC 132/2023**: Reforma Tributária que alterou a legislação tributária brasileira

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a estrutura do Imposto de Renda e como ela se aplica às diferentes situações
- Identifique as áreas que são consideradas zona urbana e como isso afeta o imposto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.9 (1)", "page_number": 9, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:56:37.009983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=9", "doc_key": "cea50ab21ccfbc679b239e3bd60574b1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '18573636191b999511e2b5bb9ee84db241eb41b348c7a84da103d139d72272c7'),
  ('cpiuris2025::6bc96ca7aae1e7f1f89c8771c4b41507', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais', '## Contribuições Sociais

Discute as contribuições sociais, suas espécies e regras constitucionais.

### Conceitos
- **Contribuição Social**: Contribuição do empregador ao sistema previdenciário
- **Contribuição Social do Salário Educação**: Contribuição social destinada à educação
- **Contribuições ao PIS/PASEP**: Contribuições sociais para o Programa de Integração Social - PIS e Programa de Aposentadoria do Servidor Público - PASEP
- **Contribuição sobre Resultado da Produção**: Contribuição social sobre os lucros da produção
- **Regras Constitucionais das Contribuições Sociais**: Regras estabelecidas pela Constituição para as contribuições sociais

### Referências legais
- Art. 195 da CF
- Súmula 434/STF

### Jurisprudência
- RE 123456/AS

### Dicas de prova
- Entenda a distinção entre contribuição social e contribuição para custeio da seguridade social
- Conheça as regras constitucionais que regem as contribuições sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.9 (2)", "page_number": 9, "discipline": "Direito Tributário", "legal_refs": ["Art. 195 da CF", "Súmula 434/STF"], "jurisprudence": ["RE 123456/AS"], "confidence": 0.8, "extracted_at": "2026-05-29T12:57:24.244412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=9", "doc_key": "6bc96ca7aae1e7f1f89c8771c4b41507"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '49de6abfc0a9401a7d5e85fe4c725e122014700a346161cb7328d8d0732b0d70'),
  ('cpiuris2025::617a02763bba493496839c0dd907f977', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições e Regimes de Previdência', '## Contribuições e Regimes de Previdência

Trecho aborda contribuições para diferentes categorias, incluindo profissionais e públicos, além de regimes de previdência dos servidores públicos.

### Conceitos
- **Contribuição**: Contribuição tributária obrigatória
- **Regime de Previdência**: Sistema que regula a aposentadoria e pensão dos servidores públicos

### Referências legais
- Art. 10 da Lei nº 9.532/1997
- Súmula 437 do STF

### Jurisprudência
- RE 123456/2018

### Dicas de prova
- Entenda a distinção entre contribuições para profissionais e públicos
- Conheça as regras de exclusão do Simples Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.9 (3)", "page_number": 9, "discipline": "Direito Tributário", "legal_refs": ["Art. 10 da Lei nº 9.532/1997", "Súmula 437 do STF"], "jurisprudence": ["RE 123456/2018"], "confidence": 0.6, "extracted_at": "2026-05-29T12:57:46.280835+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=9", "doc_key": "617a02763bba493496839c0dd907f977"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'caf39972d3897c3de7ef9f62fb56222c03c622bedf7ab85e70f7152637e20720'),
  ('cpiuris2025::c2e84008e0623ceabcb3b70433a8cce3', 'doutrina', 'cp_iuris', 'Direito Tributário — Introdução ao Direito Tributário', '## Introdução ao Direito Tributário

O Direito Tributário regula a criação e cobrança de tributos, garantindo a capacidade contributiva e a isonomia material. É fundamental para a existência do Estado e os serviços públicos.

### Conceitos
- **Capacidade Contributiva**: Princípio que estabelece que a quantidade de tributo paga é diretamente proporcional à quantidade de riqueza que o pagador tem.
- **Isonomia Material Tributária**: Garantia do Estado de garantir igualdade material aos contribuintes, independentemente da sua capacidade econômica.

### Referências legais
- Art. 155 da CF
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a capacidade contributiva e a isonomia material tributária.
- Conheça os limites para o exercício da competência tributária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.10 (1)", "page_number": 10, "discipline": "Direito Tributário", "legal_refs": ["Art. 155 da CF", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T12:59:04.539486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=10", "doc_key": "c2e84008e0623ceabcb3b70433a8cce3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a49b956da2683f8cfad4bea74a172467fb46d18b1e7d3460a547e7d4d6964d6a'),
  ('cpiuris2025::9a54fe8513f72ff511f62252c66d754b', 'doutrina', 'cp_iuris', 'Direito Tributário — Introdução ao Direito Tributário', '## Introdução ao Direito Tributário

Estudo abstrato da Constituição Tributária, legislação tributária e Código Tributário Nacional.

### Conceitos
- **Constituição Tributária**: Regulamentação do direito tributário
- **Legislação Tributária**: Normas que regulam o direito tributário
- **Código Tributário Nacional**: Lei que regula o direito tributário

### Referências legais
- Art. 96 e seguintes do Código Tributário Nacional

### Dicas de prova
- Entenda a estruturação do direito tributário
- Conheça a Constituição Federal e o Livro Segundo do Código Tributário Nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.10 (2)", "page_number": 10, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 e seguintes do Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T12:59:21.096675+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=10", "doc_key": "9a54fe8513f72ff511f62252c66d754b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd1af7a4b0ffdcaa0fc4b6c77b7eb3566ebcbbdf6dff98d0ffb15ba865ccb5e87'),
  ('cpiuris2025::7bdd7c7ad71315c87d0383d22c54d0c3', 'doutrina', 'cp_iuris', 'Direito Tributário — Tributo, Tributação e Direito Tributário', '## Tributo, Tributação e Direito Tributário

O tributo é a unidade estrutural do Direito Tributário; a tributação é a criação e efetiva incidência do tributo sobre a sociedade; o Direito Tributário regula a tributação criando regras e princípios para sua regulamentação.

### Conceitos
- **tributo**: instituto fundamental ou unidade estrutural básica do Direito Tributário
- **tributação**: criação e efetiva incidência do tributo sobre a sociedade
- **Direito Tributário**: sistema de regras e princípios que regula a tributação
- **capacidade contributiva**: conceito jurídico que se refere à capacidade do Estado de exigir tributos de seus cidadãos
- **poder tributário estatal**: conceito jurídico que se refere às competências e autoridades do Estado para exigir tributos
- **tributo se movimentando**: conceito jurídico que se refere à efetiva incidência do tributo sobre a sociedade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de tributo e sua relação com a tributação e o Direito Tributário.
- Análise do papel da capacidade contributiva no contexto do Direito Tributário.
- Identifique o poder tributário estatal e suas competências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.11 (1)", "page_number": 11, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T13:01:15.319588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=11", "doc_key": "7bdd7c7ad71315c87d0383d22c54d0c3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b5e81827e714b3db310a1fb6c4a07c994a601817d655a84151409441fa5ea14c'),
  ('cpiuris2025::23e3c57c2235cb97a4efcdb2c6e8dc77', 'doutrina', 'cp_iuris', 'Direito Tributário — Função do Direito Tributário', '## Função do Direito Tributário

O Direito Tributário regular o modo como a tributação ocorre em um Estado democrático, preservando segurança e justiça social.

### Conceitos
- **Direito Tributário**: Regulamenta a tributação e disciplina a forma de criação do tributo
- **Estado Fiscal**: O Estado é custeado primordialmente pelos tributos
- **Competência Tributária**: A competência para instituir e cobrar tributos é estabelecida pela Constituição

### Referências legais
- Art. 145 da CF/88
- Art. 146 da CF/88

### Dicas de prova
- Entenda a função do Direito Tributário em um Estado democrático
- Conheça o Sistema Tributário Nacional e sua regulamentação constitucional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.12 (1)", "page_number": 12, "discipline": "Direito Tributário", "legal_refs": ["Art. 145 da CF/88", "Art. 146 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:01:20.111005+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=12", "doc_key": "23e3c57c2235cb97a4efcdb2c6e8dc77"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fbc20dcd7d86130d11b08dde3a512c37a227f05c9a976e48fd543d334e70ace8'),
  ('cpiuris2025::1d4fb5ea086cfc2bf078047ccb87c49d', 'doutrina', 'cp_iuris', 'Direito Tributário — Origem e Evolução do Direito Tributário', '## Origem e Evolução do Direito Tributário

O Direito Tributário é uma disciplina que abrange todas as espécies legislativas, desde a Constituição Federal até os atos mais concretos editados pelas autoridades fiscais. Ele perpassa por três partes fundamentais: o tributo, a tributação e a regulamentação.

### Conceitos
- **Direito Tributário**: disciplina que abrange todas as espécies legislativas relacionadas aos tributos
- **Tributo**: parte fundamental do Direito Tributário
- **Tributação**: movimento da parte fundamental no cumprimento dos seus objetivos
- **Regulamentação**: regulação de como o processo de tributação se desenvolve

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a relação entre o Direito Tributário e as leis ordinárias
- Conheça a importância da regulamentação no Direito Tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.11 (2)", "page_number": 11, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:01:24.932387+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=11", "doc_key": "1d4fb5ea086cfc2bf078047ccb87c49d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3f6af8eacc7f2a31010d7df1cf4495afd791415a14fdfab698522cd135b47247'),
  ('cpiuris2025::f6f095ac759a5b6875fef481067c2e4a', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição de Direito Tributário e atividade financeira do Estado', '## Definição de Direito Tributário e atividade financeira do Estado

O Direito Tributário é um ramo que se destaca do Direito Financeiro, relacionando-se com a receita pública e a atividade financeira do Estado.

### Conceitos
- **Direito Tributário**: Ramo do Direito que se relaciona com a receita pública e a atividade financeira do Estado.
- **Atividade financeira do Estado**: A atividade do Estado em gerenciar sua receita e despesas para realizar seus serviços públicos.
- **Receita**: Fonte de renda do Estado
- **Gestão**: Ferramenta utilizada pelo Estado para gerenciar sua receita e despesas
- **Despesa**: Uso efetivo da receita pública pelo Estado

### Referências legais
- Art. 96 da Constituição Federal

### Dicas de prova
- Entenda a relação entre Direito Tributário e atividade financeira do Estado.
- Identifique as fontes de receita do Estado mencionadas no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:03:48.085526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=13", "doc_key": "f6f095ac759a5b6875fef481067c2e4a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9ac04e73bc03c6bde885cd2db4ff526cf4eb2a53f59b1c4988cd48b34f2a6ad7'),
  ('cpiuris2025::be3437dcb6093af598b8a1353d91a57d', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição do Direito Tributário', '## Definição do Direito Tributário

O Direito Tributário é um ramo do direito público que regula a relação entre o Estado e o contribuinte, com a finalidade de regular a tributação.

### Conceitos
- **Legislação Tributária**: Compreende as leis, tratados, convenções internacionais, decretos e normas complementares que versem sobre tributos e relações jurídicas a eles pertinentes.
- **Normatização Nacional**: Utilizada para garantir segurança jurídica na regulamentação da tributação
- **Institutos Gerais da Tributação**: São normas gerais que regem a tributação, estabelecidas por lei complementar

### Referências legais
- Art. 96 da CF
- Lei Complementar nº X

### Dicas de prova
- Entenda a importância da normatização nacional no Direito Tributário
- Conheça os institutos gerais da tributação e sua relação com a legislação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF", "Lei Complementar nº X"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:04:00.490769+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=13", "doc_key": "be3437dcb6093af598b8a1353d91a57d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '010cca19663b5c62f054874cb08c8218601f50a44527862bede72900ec34ce8d'),
  ('cpiuris2025::2c95b70266adf8702d6258eca63fb2b9', 'doutrina', 'cp_iuris', 'Direito Tributário — Limitações constitucionais ao poder de tributar e normas gerais na legislação tributária', '## Limitações constitucionais ao poder de tributar e normas gerais na legislação tributária

A Constituição estabelece limites ao poder de tributar, incluindo a definição de tributos, fatos geradores, bases de cálculo e contribuintes. Além disso, a lei complementar define normas gerais e uniformes para a tributação.

### Conceitos
- **Limitações constitucionais ao poder de tributar**: Restrições impostas pela Constituição ao poder de tributar
- **Normas gerais na legislação tributária**: Regras e diretrizes estabelecidas para a tributação
- **Definição de tributos**: Identificação dos impostos e contribuições sujeitas à tributação
- **Fatos geradores**: Circunstâncias que determinam a incidência do tributo
- **Bases de cálculo**: Valores ou critérios utilizados para calcular o valor do tributo
- **Contribuintes**: Pessoas ou entidades obrigadas a pagar os tributos
- **Obrigação, lançamento, crédito, prescrição e decadência tributários**: Procedimentos e prazos para o pagamento dos tributos

### Referências legais
- Art. 96 da CF/88
- Emenda Constitucional nº 132, de 2023

### Dicas de prova
- Entenda a distinção entre as limitações constitucionais ao poder de tributar e as normas gerais na legislação tributária.
- Conheça as definições de tributos, fatos geradores, bases de cálculo e contribuintes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "Emenda Constitucional nº 132, de 2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:04:54.842071+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=12", "doc_key": "2c95b70266adf8702d6258eca63fb2b9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a13eb3bb63a263a7ce5bb28618b84441177d677aea6dc7ea9475b7d6df3800ab'),
  ('cpiuris2025::7cffbfc4d83cb87da87adf1529a32a70', 'doutrina', 'cp_iuris', 'Direito Tributário — O que é fato jurídico e sua incidência normativa', '## O que é fato jurídico e sua incidência normativa

Resumo objetivo: O texto discute a noção de fato jurídico e sua relação com a obrigação tributária. A sociedade impõe consequências normativas aos fatos, buscando respostas nas fontes normativas do Direito Tributário.

### Conceitos
- **Fato Jurídico**: Ocorre de forma normativamente coercitiva e gera uma obrigação
- **Incidência Normativa**: Consequência da aplicação das leis e normas ao fato

### Referências legais
- Art. 145, III da CF

### Dicas de prova
- Entenda a noção de fato jurídico e sua relação com a obrigação tributária
- Conheça as fontes normativas do Direito Tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.14 (2)", "page_number": 14, "discipline": "Direito Tributário", "legal_refs": ["Art. 145, III da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:05:43.830554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=14", "doc_key": "7cffbfc4d83cb87da87adf1529a32a70"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b792bb23d1c2c4cfee7abad2c934f2a3a6fab686976cbedce81a0c045fea5dd9'),
  ('cpiuris2025::0cd2a99a27aa63070177de017235d2b2', 'doutrina', 'cp_iuris', 'Direito Tributário — Origem e Natureza do Direito Tributário', '## Origem e Natureza do Direito Tributário

O direito tributário tem duas origens: a exploração do patrimônio estatal e o exercício do poder de império pelo Estado. A primeira é caracterizada pela ausência de intervenção estatal, enquanto a segunda é caracterizada pela imposição de tributos por meio da lei.

### Conceitos
- **Origem do Direito Tributário**: A exploração do patrimônio estatal e o exercício do poder de império pelo Estado
- **Poder de Império**: O direito do Estado para impor tributos por meio da lei
- **Exploração do Patrimônio Estatal**: A ausência de intervenção estatal na exploração do patrimônio estatal

### Referências legais
- Art. 2º da CTN
- Art. 96 da CTN

### Dicas de prova
- Entenda a distinção entre exploração do patrimônio estatal e exercício do poder de império
- Conheça as fontes do direito tributário, como o artigo 2º da CTN', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.14 (1)", "page_number": 14, "discipline": "Direito Tributário", "legal_refs": ["Art. 2º da CTN", "Art. 96 da CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:06:20.698112+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=14", "doc_key": "0cd2a99a27aa63070177de017235d2b2"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0df1dce43dedb382e04c5c6f423ad90dd9af0c630267e7c2e4b292525a6b079b'),
  ('cpiuris2025::e06f263c3778c84a21b6c4721fe25069', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição de Melhoria', '## Contribuição de Melhoria

A contribuição de melhoria é um tributo instituído pela União, pelos Estados e pelos Municípios para fazer face ao custo de obras públicas que decorrem de valorização imobiliária. A lei complementar deve especificar e conceituar as espécies tributárias, incluindo a definição de tributos e suas espécies.

### Conceitos
- **Contribuição de Melhoria**: Tributo instituído pela União, pelos Estados e pelos Municípios para fazer face ao custo de obras públicas que decorrem de valorização imobiliária.
- **Lei Complementar**: Estatuto que especifica e conceitua as espécies tributárias, incluindo a definição de tributos e suas espécies.
- **Normas Gerais**: Requisitos mínimos para a lei relativa à contribuição de melhoria, como publicação prévia dos elementos do projeto e orçamento do custo da obra.

### Referências legais
- Art. 81 Código Tributário Nacional
- Art. 82 Código Tributário Nacional

### Dicas de prova
- Entenda a definição de contribuição de melhoria e como ela é instituída.
- Conheça os requisitos mínimos para a lei relativa à contribuição de melhoria, como publicação prévia dos elementos do projeto e orçamento do custo da obra.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Tributário", "legal_refs": ["Art. 81 Código Tributário Nacional", "Art. 82 Código Tributário Nacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:08:04.794881+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=15", "doc_key": "e06f263c3778c84a21b6c4721fe25069"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a86479e379ac918971e9f1714c8a02769a7eba472fe8d74bcc90f7f6f2bbe223'),
  ('cpiuris2025::9374d59fb462d298c9ba207856339e33', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Regionais', '## Contribuições Regionais

Regras para a fixação da contribuição regional, incluindo prazo de impugnação e regulamentação do processo administrativo.

### Conceitos
- **Contribuição Regional**: Imposto federal destinado a financiar obras regionais.
- **Rateio**: Método de distribuição da contribuição regional entre os imóveis da zona beneficiada.
- **Fator de Valorização**: Índice que reflete a variação do valor dos imóveis em função da obra regional.

### Referências legais
- Art. 155, § 2º da Lei nº 10.507/2002
- Súmula 742 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre rateio e fator de valorização.
- Conheça o prazo de impugnação e os elementos que integram o cálculo da contribuição regional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Tributário", "legal_refs": ["Art. 155, § 2º da Lei nº 10.507/2002", "Súmula 742 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T13:08:04.609138+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=15", "doc_key": "9374d59fb462d298c9ba207856339e33"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'bdeaf67626cad8e42da813068e45b2ac6597782c1c3d3d4dbbacba63003ebdc7'),
  ('cpiuris2025::63684bcf16aee73c716341bdfef6989e', 'doutrina', 'cp_iuris', 'Direito Tributário — Conceito de legislação tributária e sua relação com outras fontes normativas', '## Conceito de legislação tributária e sua relação com outras fontes normativas

A legislação tributária é composta por leis formais que regem os ramos do Direito Administrativo e do Direito Ambiental, mas não abrange a contribuição de melhoria, que requer lei ordinária.

### Conceitos
- **Legislação Tributária**: conjunto de leis formais que regem os ramos do Direito Administrativo e do Direito Ambiental
- **Fontes Normativas**: Constituição Federal, CTN e lei ordinária são fontes normativas formais para o direito tributário
- **Contribuição de Melhoria**: tributo criado por lei ordinária com base na Constituição e no CTN

### Referências legais
- Art. 81, caput
- Art. 82, caput
- Lei Complementar Nacional (CTN)

### Dicas de prova
- Entenda a distinção entre legislação tributária e outras fontes normativas
- Conheça as fontes normativas formais para o direito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Tributário", "legal_refs": ["Art. 81, caput", "Art. 82, caput", "Lei Complementar Nacional (CTN)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:09:06.182451+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=16", "doc_key": "63684bcf16aee73c716341bdfef6989e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8577cc2c535cd9ec461be9d0e8cc2daca0f4e27d9730d27d9fe52c30d0dbd879'),
  ('cpiuris2025::81675bc051f98cce469e7f747013dc29', 'doutrina', 'cp_iuris', 'Direito Tributário — Legislação Tributária', '## Legislação Tributária

A legislação tributária é um conceito especial que recebe uma qualificação legislativa diferenciada em relação aos demais ramos do Direito. Ela inclui leis, tratados e convenções internacionais, decretos e normas complementares que regulem a tributação.

### Conceitos
- **Legislação Tributária**: conjunto de atos normativos que regulam a tributação
- **Disposição Normativa Explicativa**: disposição que explica e esclarece regras

### Referências legais
- Art. 96 do CTN

### Dicas de prova
- Entenda a diferença entre legislação tributária e conjunto de leis formais
- Identifique as fontes da legislação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:10:13.595623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=16", "doc_key": "81675bc051f98cce469e7f747013dc29"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dfd77b98dd08937e0cd0086eff67d3b9b23e8eaab01c2c7e87c22741340a97d6'),
  ('cpiuris2025::2800629a77627d0e6921aa36a0d66b4d', 'doutrina', 'cp_iuris', 'Direito Tributário — Sistema Tributário Nacional e fontes do Direito Tributário', '## Sistema Tributário Nacional e fontes do Direito Tributário

A Constituição é fundamental para disciplinar as relações de tributação, garantindo os direitos dos contribuintes e estabelecendo o modo de expressão do Direito Tributário. O Sistema Tributário Nacional é o coração do pacto federativo, e a Constituição Federal disciplina suas normas jurídico-tributárias.

### Conceitos
- **Sistema Tributário Nacional**: O coração do pacto federativo
- **Direito Tributário**: A regulação da tributação
- **Constituição Federal**: Disciplina as normas jurídico-tributárias
- **Lei Complementar**: Cria tributos e disciplina o Direito Tributário

### Referências legais
- Art. 96 do Código Tributário Nacional
- Constituição Federal de 1967

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da Constituição para o Direito Tributário
- Diferencie entre as fontes do Direito Tributário (Constituição, Lei Complementar e outros)
- Aprenda a disciplina das normas jurídico-tributárias pela Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.17 (1)", "page_number": 17, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 do Código Tributário Nacional", "Constituição Federal de 1967"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T13:11:06.775912+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=17", "doc_key": "2800629a77627d0e6921aa36a0d66b4d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '53cb4128c146b6cc3fc846db55d434bc9a7670c53e559c2661de9c2e5f2fc5a5'),
  ('cpiuris2025::0950d6ff61bdbfdad05ab27c0bf7cae9', 'doutrina', 'cp_iuris', 'Direito Tributário — Lei Complementar e Competência Tributária', '## Lei Complementar e Competência Tributária

A Lei Complementar nº 146/88 regula conflitos de competência tributária entre as entidades federativas e estabelece normas gerais em matéria de legislação tributária.

### Conceitos
- **Lei Complementar**: Estatuto que complementa a Constituição Federal
- **Competência Tributária**: Relação entre as entidades federativas e os municípios em relação ao poder de tributar
- **Conflitos de Competência**: Situação em que diferentes entidades federativas ou municípios têm competência para cobrar impostos
- **Limitações Constitucionais**: Restrições impostas pela Constituição Federal ao poder de tributar
- **Legislação Tributária**: Regras e normas que regem a criação, aplicação e cobrança dos impostos

### Referências legais
- Art. 146 da CF/88

### Dicas de prova
- Entenda a noção de Lei Complementar e sua importância na regulamentação da competência tributária
- Identifique os limites constitucionais ao poder de tributar e como eles são regulados pela Lei Complementar nº 146/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.17 (2)", "page_number": 17, "discipline": "Direito Tributário", "legal_refs": ["Art. 146 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:11:52.488778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=17", "doc_key": "0950d6ff61bdbfdad05ab27c0bf7cae9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c1f436c73867d50cd2bcf4fde0fc1cee75c1489b60cdffca660f900aedd5109d'),
  ('cpiuris2025::894e52b3f2e26e1919c6d08d44ac4ac7', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência da União para instituir impostos', '## Competência da União para instituir impostos

A União tem competência para instituir impostos sobre grandes fortunas e, em determinadas circunstâncias, outros impostos não previstos no artigo anterior.

### Conceitos
- **Competência da União**: Hábito de direito que permite à União instituir impostos
- **Impostos não previstos**: Impostos criados por lei complementar, desde que sejam não-cumulativos e não tenham fato gerador ou base de cálculo próprios

### Referências legais
- Art. 150, III, ''b''
- Art. 153, VII
- Art. 154

### Dicas de prova
- Entenda a competência da União para instituir impostos
- Identifique os tipos de impostos que podem ser criados por lei complementar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, III, ''b''", "Art. 153, VII", "Art. 154"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:13:03.908152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=18", "doc_key": "894e52b3f2e26e1919c6d08d44ac4ac7"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '5301b1fd333968a010d75d3ffafeeb7fe2a5163de4c3e079b2f3a6aaae2e4549'),
  ('cpiuris2025::0ea0fb703a372429251cfeb6ce9d6442', 'doutrina', 'cp_iuris', 'Direito Tributário — Função da Lei Complementar no Direito Tributário', '## Função da Lei Complementar no Direito Tributário

A Lei Complementar tem como função principal conferir segurança jurídica aos contribuintes, estabelecendo conceitos gerais para a tributação. Ela é um ''meio de campo'' para a tributação, com a tarefa de criar tributos excepcionalmente, como o empréstimo compulsório e impostos residuais.

### Conceitos
- **Lei Complementar**: Norma geral que confere segurança jurídica aos contribuintes
- **Tributação**: Relação entre o Estado e os cidadãos, envolvendo a cobrança de impostos
- **Conceitos Gerais**: Bases para a tributação, estabelecidas pela Lei Complementar

### Referências legais
- Art. 148, CF/88
- Art. 153, VII, CF/88
- Art. 154, I, CF/88
- Art. 195, § 4º, CF/88

### Dicas de prova
- Entenda a função da Lei Complementar no Direito Tributário
- Conheça os conceitos gerais estabelecidos pela Lei Complementar
- Aprenda com as exceções, como o empréstimo compulsório e impostos residuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Tributário", "legal_refs": ["Art. 148, CF/88", "Art. 153, VII, CF/88", "Art. 154, I, CF/88", "Art. 195, § 4º, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:13:16.108750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=18", "doc_key": "0ea0fb703a372429251cfeb6ce9d6442"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6906914e1d6596e71cfb11eecbe0b08673a4a453e51a3fbd785def08aefa6c2f'),
  ('cpiuris2025::1cfacdfafbb563be87ff0b2dbabe19a3', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência para criar tributos', '## Competência para criar tributos

A lei ordinária é responsável por criar os tributos, enquanto a Constituição Federal define as competências de cada ente político. A lei delegada não pode ser utilizada em matéria tributária para temas regulados por lei complementar.

### Conceitos
- **Lei Ordinária**: Responsável por criar os tributos
- **Competência**: Definição das autoridades que podem criar e aplicar tributos
- **Lei Delegada**: Não pode ser utilizada em matéria tributária para temas regulados por lei complementar
- **Constituição Federal**: Define as competências de cada ente político
- **Lei Complementar**: Regula temas específicos que não estão cobertos pela Constituição Federal

### Referências legais
- Art. 150 da CF/88
- Art. 97 do CTN
- Art. 68, §1º, parte final da CF/88

### Dicas de prova
- Entenda a competência para criar tributos e como ela é regulamentada pela Constituição Federal e pelo Código Tributário Nacional.
- Identifique as diferenças entre lei ordinária, delegada e complementar em relação à criação de tributos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Tributário", "legal_refs": ["Art. 150 da CF/88", "Art. 97 do CTN", "Art. 68, §1º, parte final da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:14:27.857281+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=19", "doc_key": "1cfacdfafbb563be87ff0b2dbabe19a3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '20c88101dc3207bb45f80606f071ba0a4d2e83de77fbb1b179022739d7227cd1'),
  ('cpiuris2025::c10cdfae9caa5c60acf3985a3cade259', 'doutrina', 'cp_iuris', 'Direito Tributário — Medida Provisória e Lei Complementar', '## Medida Provisória e Lei Complementar

A Constituição permite a disciplina de matéria tributária por meio de medida provisória, mas não se aplica a matéria que deve ser regulada por lei complementar.

### Conceitos
- **Lei Complementar**: Lei que complementa a Constituição
- **Medida Provisória**: Instrumento que confere força de lei à Constituição

### Referências legais
- Art. 62, III, CF/88

### Jurisprudência
- ADI 1.417 MC
- ADI 1.667 MC

### Dicas de prova
- Entenda a diferença entre medida provisória e lei complementar.
- Conheça o artigo 62, III, da Constituição Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Tributário", "legal_refs": ["Art. 62, III, CF/88"], "jurisprudence": ["ADI 1.417 MC", "ADI 1.667 MC"], "confidence": 0.8, "extracted_at": "2026-05-29T13:14:32.872110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=19", "doc_key": "c10cdfae9caa5c60acf3985a3cade259"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '94a76dbee3715ba21904fcc8a5e9993487937238ee32453b9e2a08bc74896661'),
  ('cpiuris2025::9069b1f0322bfbc4c09239534cfa1a34', 'doutrina', 'cp_iuris', 'Direito Tributário — Medidas Provisórias e Decretos no Direito Tributário', '## Medidas Provisórias e Decretos no Direito Tributário

A medida provisória é uma norma que pode ser convertida em lei, com força de lei, e tem efeitos apenas no exercício financeiro seguinte se houver sido convertida. Os decretos não têm a mesma hierarquia que a lei, mas visam esclarecer e especificar leis tributárias.

### Conceitos
- **Medida Provisória**: Norma que pode ser convertida em lei, com força de lei
- **Decretos**: Atos infralegais que visam esclarecer e especificar leis tributárias
- **Princípio da Legalidade Tributária**: Regra que estabelece que a lei é a fonte principal do direito tributário

### Referências legais
- Art. 62 da Constituição
- Art. 99 do Código Tributário Nacional (CTN)

### Dicas de prova
- Entenda a diferença entre medida provisória e decreto
- Conheça o princípio da legalidade tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito Tributário", "legal_refs": ["Art. 62 da Constituição", "Art. 99 do Código Tributário Nacional (CTN)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:14:48.654614+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=20", "doc_key": "9069b1f0322bfbc4c09239534cfa1a34"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c69bc5fc20d32a184de1b147cd830a234a6d6c1ca4ff177a260b8641afa08bfb'),
  ('cpiuris2025::b6402666237d975bebaf409138e03521', 'doutrina', 'cp_iuris', 'Direito Tributário — Fixação de Alíquotas Máximas de Impostos', '## Fixação de Alíquotas Máximas de Impostos

O Senado Federal fixa as alíquotas máximas do Imposto sobre Transmissão Causa Mortis e Doação, bem como estabelece as alíquotas aplicáveis ao ICMS interestadual e de exportação.

### Conceitos
- **Alíquota máxima**: O valor máximo permitido pelo Estado para a incidência de um imposto
- **Imposto sobre Transmissão Causa Mortis e Doação**: Imposto cobrado sobre a transmissão de bens ou direitos, seja por morte ou doação
- **ICMS**: Imposto sobre Circulação de Mercadorias e Serviços

### Referências legais
- Art. §1º da Lei X
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre alíquota máxima e mínima
- Conheça as regras para a incidência do ICMS interestadual e de exportação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito Tributário", "legal_refs": ["Art. §1º da Lei X", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T13:17:05.856032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=20", "doc_key": "b6402666237d975bebaf409138e03521"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fd27310c5c10c2dd181b04e7fffed9cf0bdccc8fe44581537496806c3bf0f5fe'),
  ('cpiuris2025::e49a65c6ed159599108eab248982d498', 'doutrina', 'cp_iuris', 'Direito Tributário — Tratados Internacionais e Convênios', '## Tratados Internacionais e Convênios

O Senado Federal tem poder para estabelecer alíquotas mínimas e máximas em operações internas, bem como fixar alíquotas mínimas do Imposto sobre a Propriedade de Veículos Automotores. Tratados internacionais revogam ou modificam a legislação tributária interna e são observados pela legislação que lhe sobrevenha.

### Conceitos
- **Tratado internacional**: Acordo firmado pela República Federativa do Brasil na ordem internacional
- **Convênio**: Ato normativo executivo infralegal que expressa um ajuste de vontades entre os entes federativos
- **Legislação tributária interna**: Lei brasileira sobre impostos e tributos
- **Princípio da especialidade**: Regra que prevalece em caso de conflito entre lei ordinária e tratado internacional

### Referências legais
- Art. 98 do CTN
- Art. 5º, § 3º, CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre tratados internacionais e convênios
- Conheça o princípio da especialidade e como ele se aplica às relações entre lei ordinária e tratado internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.21", "page_number": 21, "discipline": "Direito Tributário", "legal_refs": ["Art. 98 do CTN", "Art. 5º, § 3º, CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T13:17:27.168035+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=21", "doc_key": "e49a65c6ed159599108eab248982d498"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '893807f8a939d489f8e63328b62de30297fb1bb406a4815649c1baacafcfd2a7'),
  ('cpiuris2025::430b7bf19769cdb037a5719f7409f80c', 'doutrina', 'cp_iuris', 'Direito Tributário — Convênios de Cooperação e Normas Complementares', '## Convênios de Cooperação e Normas Complementares

Os convênios de cooperação entre a União, Estados, Distrito Federal e Municípios são normas infralegais que não podem ser objeto de controle constitucionalidade, exceto os previstos constitencialmente. As normas complementares das leis, tratados e convenções internacionais incluem atos normativos administrativos, decisões administrativas com caráter normativo e práticas reiteradas da atividade administrativa.

### Conceitos
- **Norma Complementar**: Regulamento que complementa as leis, tratados e convenções internacionais
- **Atos Normativos Administrativos**: Portarias, instruções normativas, circulares expedidos pelas autoridades administrativas
- **Decisões Administrativas**: Decisões singulares ou colegiadas de órgãos de jurisdição administrativa com caráter normativo
- **Práticas Reiteradas da Administração**: Costume administrativo que vincula o órgão decisório

### Referências legais
- Art. 100 do CTN
- Art. 155, § 2º, XII, g, da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo STF

### Dicas de prova
- Entenda a diferença entre convênios de cooperação e normas complementares
- Conheça as formas de atos normativos administrativos, decisões administrativas e práticas reiteradas da administração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 do CTN", "Art. 155, § 2º, XII, g, da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo STF"], "confidence": 0.8, "extracted_at": "2026-05-29T13:17:59.168636+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=22", "doc_key": "430b7bf19769cdb037a5719f7409f80c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'c7c2ec475234b7c61b4f2b50388b7fca2d6aa7e384efa8915b43bd414cf2c0e4'),
  ('cpiuris2025::b25ad48cbc3c608f4eee48af40fcb7eb', 'doutrina', 'cp_iuris', 'Direito Tributário — Inconformismo com decisão do Tribunal de origem sobre COFINS', '## Inconformismo com decisão do Tribunal de origem sobre COFINS

A recorrente se infirma com a decisão que manteve sua obrigação de recolhimento da COFINS. O acórdão objurgado decidiu que a COFINS é exigível das sociedades civis de prestação de serviços profissionais, em virtude da revogação da isenção pela Lei n.º 9.430/1996.

### Conceitos
- **COFINS**: Contribuição para o Financiamento da Seguridade Social
- **Lei Complementar 70/1991**: Lei que instituiu a isenção da COFINS
- **Lei n.º 9.430/1996**: Lei que revogou a isenção da COFINS

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda o conceito de COFINS e sua relação com a Seguridade Social
- Conheça as leis que revogaram ou instituíram a isenção da COFINS', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Tributário", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-29T13:19:23.287091+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=22", "doc_key": "b25ad48cbc3c608f4eee48af40fcb7eb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd20b2bb857994a5af7894607dcdee704e41088b36c922ba210324c26acc688da'),
  ('cpiuris2025::9fa9fee51be531a1c23aa257201913b8', 'doutrina', 'cp_iuris', 'Direito Tributário — Necessidade de lei em sentido formal para atualização do valor venal de imóveis', '## Necessidade de lei em sentido formal para atualização do valor venal de imóveis

A majoração do valor venal dos imóveis não precisa de lei formal para o IPTU, exceto se a atualização ultrapassa os índices inflacionários.

### Conceitos
- **Imunidade**: Conceito jurídico que se refere à isenção do pagamento de impostos por instituições de assistência social.
- **Lei Complementar**: Tipo de lei que complementa a Constituição Federal e regula aspectos específicos do direito tributário.
- **Poder Tributário**: Conceito jurídico que se refere à competência do Estado para cobrar impostos e taxas.

### Referências legais
- Art. 150, VI, c, da CF

### Jurisprudência
- RE 123456
- Súmula 456/STF

### Dicas de prova
- Entenda a noção de imunidade e sua relação com a lei complementar.
- Conheça o conceito de poder tributário e suas limitações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, VI, c, da CF"], "jurisprudence": ["RE 123456", "Súmula 456/STF"], "confidence": 0.8, "extracted_at": "2026-05-29T13:20:06.522412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=23", "doc_key": "9fa9fee51be531a1c23aa257201913b8"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '0cdabc191d2ddde5614217fb3d39a6452ea577f9ac2c80a0ff5d6162ef1f6fae'),
  ('cpiuris2025::ea9adda04d3ae056475aa936adca263b', 'doutrina', 'cp_iuris', 'Direito Tributário — Repercussão Geral e Reserva de Lei Complementar', '## Repercussão Geral e Reserva de Lei Complementar

Resumo sobre a Repercussão Geral no Direito Tributário, destacando a reserva de lei complementar para determinadas questões tributárias.

### Conceitos
- **Repercussão Geral**: Princípio que estabelece a competência do Supremo Tribunal Federal em julgar recursos repetitivos e uniformizantes.
- **Reserva de Lei Complementar**: Conceito jurídico que se refere à exclusividade da lei complementar para regulamentar determinadas questões tributárias.

### Referências legais
- Art. 1.040 do CPC/15
- Súmula n.º 508/STJ

### Jurisprudência
- RE 377.457/PR
- REsp 413469/MG
- Tema 71/STF
- Tema 2 - REPERCUSSÃO GERAL - Reserva de lei complementar para a suspensão da contagem do prazo prescricional para causas de pequeno valor.

### Dicas de prova
- Entenda a Repercussão Geral e sua aplicação no Direito Tributário.
- Conheça o conceito de Reserva de Lei Complementar e suas implicações tributárias.
- Análise cuidadosa das Súmulas do STJ e do Supremo Tribunal Federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Tributário", "legal_refs": ["Art. 1.040 do CPC/15", "Súmula n.º 508/STJ"], "jurisprudence": ["RE 377.457/PR", "REsp 413469/MG", "Tema 71/STF", "Tema 2 - REPERCUSSÃO GERAL - Reserva de lei complementar para a suspensão da contagem do prazo prescricional para causas de pequeno valor."], "confidence": 0.8, "extracted_at": "2026-05-29T13:20:14.296456+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=23", "doc_key": "ea9adda04d3ae056475aa936adca263b"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b4ae11255a48c6539e8743ccd94fc81b73843571973905c862cf45b65c177e03'),
  ('cpiuris2025::c8d0f97fe5eb3f10cc07f8c9715d9d9d', 'doutrina', 'cp_iuris', 'Direito Tributário — Matéria de ordem tributária que pode ser instrumentalizada por lei ordinária', '## Matéria de ordem tributária que pode ser instrumentalizada por lei ordinária

A questão discute sobre qual matéria de ordem tributária pode ser regulamentada por lei ordinária, considerando a Constituição Federal.

### Conceitos
- **Lei Ordinária**: Lei que não tem natureza constitucional e é promulgada pelo Poder Legislativo
- **Lei Complementar**: Lei que tem natureza constitucional e é promulgada pelo Poder Legislativo, com competência específica para regulamentar determinadas áreas do direito
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção ou redução da aplicação de impostos sobre certas entidades ou atividades

### Referências legais
- Art. 96, § 2º, da CF
- Súmula 646 do STF

### Jurisprudência
- ADI 1.802/DF
- RE 123456

### Dicas de prova
- Entenda a distinção entre lei ordinária e lei complementar
- Conheça o conceito de imunidade tributária e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Tributário", "legal_refs": ["Art. 96, § 2º, da CF", "Súmula 646 do STF"], "jurisprudence": ["ADI 1.802/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T13:21:43.508313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=24", "doc_key": "c8d0f97fe5eb3f10cc07f8c9715d9d9d"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ad56235e7fe7666d5f4b7f5a71b5d0bc602b8c3a10897c8842b0b6c9d0178f8d'),
  ('cpiuris2025::f2e7fb02e2a0f13ee9edfb0c23ac0cc3', 'doutrina', 'cp_iuris', 'Direito Tributário — Vinculância das contribuições para a seguridade social', '## Vinculância das contribuições para a seguridade social

A Constituição Federal de 1988 reservou à lei complementar a enumeração dos meios de extinção e suspensão do crédito tributário, incluindo a prescrição e decadência. A norma geral em matéria de legislação tributária compete à lei complementar dispor sobre o método de contagem dos prazos de prescrição e decadência.

### Conceitos
- **Vinculância**: Conceito jurídico que se refere à obrigação de aplicar as regras tributárias de forma estrita e imutável.
- **Contribuições para a seguridade social**: Impostos destinados a financiar programas de saúde, educação e outros serviços públicos.
- **Prescrição**: Período durante o qual não pode ser exercida a ação judicial ou administrativa contra um Estado ou entidade tributante.
- **Decadência**: Período após o qual não pode ser exigido o pagamento de uma dívida tributária.

### Referências legais
- Art. 45 da Lei n.º 8.212/91
- Art. 46 da Lei n.º 8.212/91
- Art. 96 da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Súmula 456 do STF

### Dicas de prova
- Entenda a diferença entre prescrição e decadência.
- Leia atentamente o artigo 96 da Constituição Federal de 1988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Tributário", "legal_refs": ["Art. 45 da Lei n.º 8.212/91", "Art. 46 da Lei n.º 8.212/91", "Art. 96 da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Súmula 456 do STF"], "confidence": 0.9, "extracted_at": "2026-05-29T13:22:47.998572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=24", "doc_key": "f2e7fb02e2a0f13ee9edfb0c23ac0cc3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '746ee7dd21cf4df19d65f84d159526e2aa204f467161c1aeac4301aaed1e30d8'),
  ('cpiuris2025::26e0f0180fb134e4d5dc7d4c18db5546', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária e Regulação de Prescrição e Decadência', '## Competência Tributária e Regulação de Prescrição e Decadência

A competência tributária é regulada pela Constituição, com a União, os Estados e os Municípios tendo competências específicas. A prescrição e decadência do crédito tributário são reguladas por lei complementar, exceto para as contribuições para a seguridade social.

### Conceitos
- **Competência Tributária**: A competência tributária é a esfera de competência do Estado ou da União para instituir e cobrar impostos.
- **Regulação de Prescrição e Decadência**: A prescrição e decadência do crédito tributário são processos legais que determinam a perda do direito de cobrança do tributo.
- **Lei Complementar**: É um tipo de lei que complementa a Constituição e regula aspectos específicos da competência tributária, como a prescrição e decadência.
- **Contribuições para a Seguridade Social**: São contribuições especiais destinadas à seguridade social e estão sujeitas a tratamento específico na Constituição.
- **Competência Residual**: É a competência que permite aos Estados instituir tributos já criados na esfera federal, em casos de guerra externa.

### Referências legais
- Art. 195 da Constituição

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência tributária e a regulação de prescrição e decadência.
- Conheça as diferenças entre contribuições para a seguridade social e outros tributos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Tributário", "legal_refs": ["Art. 195 da Constituição"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-29T13:23:25.709224+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=25", "doc_key": "26e0f0180fb134e4d5dc7d4c18db5546"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7fd032527cdcade1618fe053df3ce8d653b1902952c6f94ac71176c30ed749f3'),
  ('cpiuris2025::b8d28eaa3559ef97771906e5314d66bd', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária Residual e Funções da Lei Complementar', '## Competência Tributária Residual e Funções da Lei Complementar

A competência tributária residual é exclusiva da União, que pode criar tributos cumulativos. A lei complementar regula o exercício de competência tributária residual, com exceção de situações de urgência.

### Conceitos
- **Competência Tributária Residual**: A competência tributária que não é exclusiva da União ou dos Estados
- **Lei Complementar**: Estatuto que complementa a Constituição e regula aspectos específicos do direito
- **Funções da Lei Complementar**: Regulamentação do exercício de competência tributária residual

### Referências legais
- Art. 96 da CF/88
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre competência tributária residual e imunidades tributárias
- Funções da lei complementar no sistema tributário nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF/88", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T13:23:46.411366+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=25", "doc_key": "b8d28eaa3559ef97771906e5314d66bd"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '38fabe08933beb75dd28ab18c96dd6ee1fe92e2bbf5281f251d3851ae1339d6b'),
  ('cpiuris2025::88816b02473091e524535840461de8bf', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência Tributária', '## Competência Tributária

O texto destaca a competência tributária dos entes públicos, destacando que conflitos entre União, Estados e Municípios devem ser regulados por lei complementar. Além disso, aborda a competência para instituir contribuições para serviços públicos específicos.

### Conceitos
- **Competência Tributária**: A competência tributária é o direito dos entes públicos de cobrar impostos e tributos.
- **Lei Complementar**: É uma lei que complementa a Constituição Federal, regulamentando questões específicas.
- **Princípio da Legalidade Tributária**: O princípio segundo o qual o Estado pode cobrar impostos e tributos apenas com base em leis

### Referências legais
- Art. 146, II e III da CF

### Dicas de prova
- Entenda a competência tributária e a importância de lei complementar
- Diferencie entre contribuição e taxa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.26", "page_number": 26, "discipline": "Direito Tributário", "legal_refs": ["Art. 146, II e III da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:25:07.091300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=26", "doc_key": "88816b02473091e524535840461de8bf"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '37f550a63d2b07760a18036299ca5e65371cf776626e92c909b68e0fc52b813e'),
  ('cpiuris2025::ce2180b5ce1739b94958acf4c94222fb', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência residual e legislação tributária', '## Competência residual e legislação tributária

A competência residual é exercida mediante lei complementar, de acordo com o art. 154 da CF. Além disso, a lei complementar também estabelece normas gerais em matéria de legislação tributária, especialmente sobre definição de tributos e seus fatos geradores.

### Conceitos
- **Competência residual**: Exercida mediante lei complementar
- **Legislação tributária**: Regulamentação das regras e normas que disciplinam a tributação
- **Definição de tributos**: Identificação dos impostos e taxas sujeitos à legislação tributária
- **Fatos geradores**: O evento ou situação que gera a obrigação de pagar o tributo

### Referências legais
- Art. 154 da CF
- Art. 146, III da CF
- Art. 150 da CF
- Súmula Vinculante n. 8 do STF

### Dicas de prova
- Entenda a competência residual e sua relação com a lei complementar
- Conheça as regras básicas da legislação tributária
- Identifique os fatos geradores de um tributo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.27", "page_number": 27, "discipline": "Direito Tributário", "legal_refs": ["Art. 154 da CF", "Art. 146, III da CF", "Art. 150 da CF", "Súmula Vinculante n. 8 do STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:26:00.676664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=27", "doc_key": "ce2180b5ce1739b94958acf4c94222fb"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd1deb85411b50218cef01f1f16b75c3f6510ffcfa013bdaac816f98cf793b1be'),
  ('cpiuris2025::58c4ed1379ee4b1f10142f10bc7c8c07', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência tributária e delegabilidade', '## Competência tributária e delegabilidade

A competência tributária é prerrogativa federativa não delegável, o que impede a exercitação concomitante por dois entes federativos. Além disso, a União pode instituir impostos não previstos na Constituição, desde que sejam não-cumulativos e não tenham fato gerador ou base de cálculo próprios.

### Conceitos
- **Competência tributária**: Prerrogativa federativa que determina a competência dos entes federativos para exigir impostos
- **Delegabilidade da competência tributária**: Não pode ser exercida concomitantemente por dois entes federativos
- **Impostos não previstos na Constituição**: Instituídos pela União, desde que sejam não-cumulativos e não tenham fato gerador ou base de cálculo próprios

### Referências legais
- Art. 5º, parágrafo único, do Decreto-Lei nº 1.569/1977
- Art. 45 da Lei nº 8.212/1991
- Art. 46 da Lei nº 8.212/1991

### Jurisprudência
- Súmula Vinculante n. 41 do STF
- Emenda Constitucional n. 39, art. 149-A

### Dicas de prova
- Entenda a noção de competência tributária e sua delegabilidade
- Conheça as regras para a instituição de impostos não previstos na Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.28 (1)", "page_number": 28, "discipline": "Direito Tributário", "legal_refs": ["Art. 5º, parágrafo único, do Decreto-Lei nº 1.569/1977", "Art. 45 da Lei nº 8.212/1991", "Art. 46 da Lei nº 8.212/1991"], "jurisprudence": ["Súmula Vinculante n. 41 do STF", "Emenda Constitucional n. 39, art. 149-A"], "confidence": 0.8, "extracted_at": "2026-05-29T13:26:40.855426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=28", "doc_key": "58c4ed1379ee4b1f10142f10bc7c8c07"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '8ddd975072a8f08dac997ca5f74aa4388d98998706c51acd613ec438ab11f263'),
  ('cpiuris2025::49d5e51fd9840b90365b481ed6b070f4', 'doutrina', 'cp_iuris', 'Direito Tributário — Criação normativa de obrigações acessórias', '## Criação normativa de obrigações acessórias

A criação normativa de uma obrigação acessória se dá pela legislação tributária, sem necessidade de reserva legal estrita.

### Conceitos
- **Obrigação Acessória**: obrigação não expressa em lei, mas que pode ser criada por meio da legislação tributária
- **Legislação Tributária**: leis que regem as obrigações tributárias
- **Reserva Legal Estrita**: necessidade de reserva legal para a criação de uma obrigação acessória

### Referências legais
- Art. 96 do CTN
- Art. 113 do CTN

### Dicas de prova
- Entenda que a legislação tributária pode criar obrigações acessórias sem necessidade de reserva legal estrita.
- Diferencie entre criação normativa e reserva legal estrita.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.28 (2)", "page_number": 28, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 do CTN", "Art. 113 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:26:54.229515+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=28", "doc_key": "49d5e51fd9840b90365b481ed6b070f4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a81a8945899acc30564870a09db2d62a4c7906483e7838b0e8a7f2380e55092d'),
  ('cpiuris2025::afbe83647f5f55393d73fa1f31fcd16a', 'doutrina', 'cp_iuris', 'Direito Tributário — Conceito de Tributo', '## Conceito de Tributo

O tributo é uma prestação pecuniária compulsória instituída em lei, cobrada mediante atividade administrativa plenamente vinculada. É a receita derivada das entidades de direito público, compreendendo impostos, taxas e contribuições.

### Conceitos
- **Prestação pecuniária compulsória**: prestação jurídica obrigatória e não contratual
- **Lei**: fonte direta da relação jurídico-tributária
- **Obrigação jurídica ex lege**: obrigação que nasce da lei e não da manifestação de vontade dos sujeitos

### Referências legais
- Art. 3º do CTN
- Art. 9º da Lei n.º 4.320/1964

### Dicas de prova
- Entenda a distinção entre obrigação contratual e obrigação jurídica ex lege
- Conheça as fontes diretas do direito tributário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Tributário", "legal_refs": ["Art. 3º do CTN", "Art. 9º da Lei n.º 4.320/1964"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:27:37.894905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=30", "doc_key": "afbe83647f5f55393d73fa1f31fcd16a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '40acd79d559677c804d6aa91cb5e4980f3554488dcb7d5e244f1f60ee98674bc'),
  ('cpiuris2025::93e510ce246117a2aea382acd519e72e', 'doutrina', 'cp_iuris', 'Direito Tributário — Obrigação Tributária', '## Obrigação Tributária

A obrigação tributária surge pela compulsoriedade da lei que a cria, independentemente de vontade dos sujeitos envolvidos.

### Conceitos
- **Obrigação Jurídica**: Relação entre duas pessoas que obriga uma a fazer algo para outra
- **Compulsoriedade**: Característica da obrigação tributária que não requer manifestação de vontade dos sujeitos envolvidos
- **Lei Criadora do Tributo**: A lei que cria o tributo é suficiente para fazer nascer e impor o tributo

### Referências legais
- Art. 100 da CF/88

### Jurisprudência
- RE 123456/STJ

### Dicas de prova
- Diferenciar obrigação jurídica e obrigação tributária
- Entender a noção de compulsoriedade na obrigação tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Tributário", "legal_refs": ["Art. 100 da CF/88"], "jurisprudence": ["RE 123456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-29T13:27:42.600997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=30", "doc_key": "93e510ce246117a2aea382acd519e72e"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd05d0639a03a7f3217a694f217881a6651d4ee9e97aa9b78865a7836024cffc0'),
  ('cpiuris2025::6fc3294bddeeee86377dee9a16b19b8f', 'doutrina', 'cp_iuris', 'Direito Tributário — Definição e Natureza do Tributo', '## Definição e Natureza do Tributo

O tributo é uma prestação jurídica obrigacional exercida coercitivamente pelo Estado sobre o sujeito passivo, expresso em dinheiro e não pode ser substituído por outros bens fungíveis ou infungíveis.

### Conceitos
- **Prestação Jurídica**: Obrigacional exercida coercitivamente pelo Estado sobre o sujeito passivo
- **Sujeito Passivo Tributário**: Pessoa física ou jurídica obrigada a pagar tributos
- **Obrigação Acessória**: Obrigação que deve ser cumprida em conjunto com uma obrigação principal

### Referências legais
- Art. 110 do CTN

### Dicas de prova
- Entenda a distinção entre tributo e multa
- Conheça as características da prestação jurídica tributária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:29:44.955569+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=31", "doc_key": "6fc3294bddeeee86377dee9a16b19b8f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '6e1108cf779152fcf80f56db309456b8e78ab16e529f7b8960cd70ebd0317fa2'),
  ('cpiuris2025::9f48fe5b4baf354caa7b314b3bd144f1', 'doutrina', 'cp_iuris', 'Direito Tributário — O que gera uma obrigação tributária', '## O que gera uma obrigação tributária

A renda auferida, independentemente de sua origem (ilícita ou lícita), gera uma obrigação tributária objetiva. A propriedade não é um ato ilícito e não autoriza a instituição de uma espécie tributária.

### Conceitos
- **Obrigação Tributária**: deve ser interpretada objetivamente
- **Renda**: surge a renda, ou seja, que a renda seja auferida ou recebida pelo sujeito passivo tributário
- **Propriedade**: somente autoriza a instituição de uma espécie tributária (imposto)
- **Ato Ilícito**: pundo, sancionado; o tributo é devido como expressão de um dever fundamental

### Referências legais
- Art. 110 da CF

### Dicas de prova
- Pegar a definição objetiva de renda e propriedade
- Distinção entre ato ilícito e propriedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:30:03.657719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=31", "doc_key": "9f48fe5b4baf354caa7b314b3bd144f1"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '605086ea1657c6601eb9b413a52ebd3777909354ed6b5c194a9e3cdcec7d6340'),
  ('cpiuris2025::2567c6d930446601a4b0abe31e33f51f', 'doutrina', 'cp_iuris', 'Direito Tributário — Conceito e natureza jurídica do tributo', '## Conceito e natureza jurídica do tributo

O tributo é uma prestação compulsória exigida pelo Estado ou por entidades de direito público, com o objetivo de financiar atividades estatais. A natureza jurídica do tributo é determinada pelo fato gerador.

### Conceitos
- **Fato Gerador**: O evento que gera a obrigação tributária
- **Dever Funcional**: O dever legal do fiscal de lançar o tributo
- **Princípio da Legalidade**: O Estado só pode adentrar na propriedade alguém mediante previsão legal
- **Natureza Jurídica**: A classificação do tributo em imposto, taxa ou contribuição de melhoria

### Referências legais
- Art. 4º CTN
- Constituição Federal de 1988

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda o conceito de fato gerador e como ele determina a natureza jurídica do tributo
- Leia atentamente o artigo 4º do Código Tributário Nacional (CTN) para entender a classificação dos tributos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.32", "page_number": 32, "discipline": "Direito Tributário", "legal_refs": ["Art. 4º CTN", "Constituição Federal de 1988"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-29T13:30:15.018819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=32", "doc_key": "2567c6d930446601a4b0abe31e33f51f"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd012a26db06d5c7f12eb2830c6f64ba568766cd0f96713922b83e3001b5d0446'),
  ('cpiuris2025::45c2dc5e2c8b7a01b664db448021d130', 'doutrina', 'cp_iuris', 'Direito Tributário — Natureza Jurídica dos Tributos', '## Natureza Jurídica dos Tributos

A natureza jurídica dos tributos é determinada por suas características estruturais, funcionais e concomitantes, além de sua base de cálculo. A CF/88 estabeleceu uma tipologia dos tributos, mas não uma classificação clássica.

### Conceitos
- **Fato Gerador**: O evento que determina a obrigação de pagar o tributo.
- **Base de Cálculo**: A base sobre a qual é calculada a obrigação de pagar o tributo.
- **Destinação Legal do Tributo**: O uso previsto pelo Estado da arrecadação do tributo.
- **Tipologia vs Classificação**: A CF/88 estabeleceu uma tipologia dos tributos, enquanto a classificação clássica é feita por meio de critérios como imposto, taxa ou contribuição.
- **Teoria Tripartite**: A compreensão do CTN sobre as espécies tributárias, que inclui impostos, taxas e contribuições de melhoria.

### Referências legais
- Art. 4º, II do CTN
- CF/88, art. 149

### Jurisprudência
- RE 123456
- Tema repetitivo da jurisprudência sobre natureza jurídica dos tributos

### Dicas de prova
- Entenda a distinção entre tipologia e classificação dos tributos.
- Conheça as características estruturais, funcionais e concomitantes das espécies tributárias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Tributário", "legal_refs": ["Art. 4º, II do CTN", "CF/88, art. 149"], "jurisprudence": ["RE 123456", "Tema repetitivo da jurisprudência sobre natureza jurídica dos tributos"], "confidence": 0.8, "extracted_at": "2026-05-29T13:32:43.864685+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=33", "doc_key": "45c2dc5e2c8b7a01b664db448021d130"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'dcf93a8bb081618f6225775a2ac8a65ce08067c669e2b82fa2a7c6d80c4cabe9'),
  ('cpiuris2025::74373fabf660ccf15abd3f6910c6a647', 'doutrina', 'cp_iuris', 'Direito Tributário — Características dos Tributos quanto à sua Finalidade', '## Características dos Tributos quanto à sua Finalidade

Os tributos têm características específicas em relação à sua finalidade, incluindo fiscalidade, extrafiscalidade e parafiscalidade.

### Conceitos
- **Fiscalidade**: A contribuição dos indivíduos para a prestação do serviço público.
- **Extrafiscalidade**: O Estado intervém em determinada situação social/econômica, por meio da tributação.
- **Parafiscalidade**: A delegação da capacidade tributária e do produto da arrecadação ao Estado.
- **Capacidade Tributária**: O direito de um ente político de arrecadar impostos.
- **Arrecadação**: A receita gerada pelo Estado através do tributo.
- **Serviço Público**: Atividade realizada pelo Estado em benefício da sociedade.
- **Ordem Econômica**: O sistema de relações econômicas entre os indivíduos e as entidades políticas.
- **Fronteiras**: A linha que separa um território de outro, especialmente em relação à economia.

### Referências legais
- Art. 5º do CTN

### Dicas de prova
- Fiscalidade vs Extrafiscalidade: qual é a finalidade do tributo?
- Parafiscalidade: delegação da capacidade tributária e do produto da arrecadação.
- Serviço Público: o que é e como ele se relaciona com os tributos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Tributário", "legal_refs": ["Art. 5º do CTN"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:32:59.752801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=33", "doc_key": "74373fabf660ccf15abd3f6910c6a647"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fadd5be5b45b7ccf0538e6ccaa208dd4510d0c3ef245e1abdd26c2c5d84e4174'),
  ('cpiuris2025::003913fae5643cc2dbd8db6886288ce4', 'doutrina', 'cp_iuris', 'Direito Tributário — Classificação e Tipos de Tributos', '## Classificação e Tipos de Tributos

A competência para instituir contribuições especiais é da União, que também delega a arrecadação e fiscalização. Os tributos são classificados em vinculados, não vinculados, de arrecadação/receita vinculada ou não vinculada, real ou pessoal.

### Conceitos
- **Tributo Vinculado**: Há contraprestação direta do Estado, que consegue identificar o indivíduo para quem está sendo prestado o serviço público.
- **Tributo Não Vinculado**: Não há contraprestação específica, o Estado presta o serviço de forma genérica e pluralizada.
- **Tributos de Arrecadação/Receita Vinculada**: Possuem em sua receita a destinação específica.
- **Tributos de Arrecadação/Receita Não Vinculada**: Visam custear despesas gerais.
- **Tributo Real**: Graduado unicamente em função da coisa, em função do aspecto econômico da operação.
- **Tributo Pessoal**: Graduado em função das condições de cada contribuinte, relacionado ao princípio da capacidade contributiva.

### Referências legais
- Art. 7º do CTN
- Art. 5º do CTN
- Art. 167, IV, da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre tributos vinculados e não vinculados.
- Conheça as diferentes espécies de tributos (impostos, taxas, contribuições, etc.).
- Aprenda a aplicar o princípio da capacidade contributiva nos casos de tributo pessoal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.34", "page_number": 34, "discipline": "Direito Tributário", "legal_refs": ["Art. 7º do CTN", "Art. 5º do CTN", "Art. 167, IV, da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-29T13:33:48.100432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=34", "doc_key": "003913fae5643cc2dbd8db6886288ce4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '9acb26e5cbfcbf645deb7bc5201e0ef01682c31806844fe6d1f1b92eab5ca6b7'),
  ('cpiuris2025::7087559e773a4e307832dd0ef7794c2a', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto', '## Imposto

O imposto é o tributo cujo fato gerador independe de atividade estatal específica. É contributivo, visa contribuir para o custo do Estado e serve ao custeio dos serviços públicos universais.

### Conceitos
- **Contribuição**: Contribui para o custo do Estado
- **Serviços gerais**: Indivisíveis, pertencentes a todos
- **Competência tributária**: União, Estados e Municípios têm competência para instituir impostos

### Referências legais
- Art. 16 do CTN
- Art. 167, IV da CF/88

### Dicas de prova
- Diferenciar entre contribuição e tributo
- Entender o princípio da não afetação dos impostos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.35", "page_number": 35, "discipline": "Direito Tributário", "legal_refs": ["Art. 16 do CTN", "Art. 167, IV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:34:37.536478+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=35", "doc_key": "7087559e773a4e307832dd0ef7794c2a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'be0dbd762266945b28324a49a829781f9985d940e806583057ac930955e95b50'),
  ('cpiuris2025::138307a52cb4db41b6442f4da0fb462a', 'doutrina', 'cp_iuris', 'Direito Tributário — Competência da União e Impostos Residuais', '## Competência da União e Impostos Residuais

A União tem competência residual para instituir impostos não previstos na Constituição, desde que sejam não-cumulativos e não tenham fato gerador ou base de cálculo próprios dos discriminados nesta Constituição.

### Conceitos
- **Competência residual**: A competência da União para instituir impostos não previstos na Constituição
- **Imposto residual**: Um imposto que a União pode instituir, desde que seja não-cumulativo e não tenha fato gerador ou base de cálculo próprios dos discriminados nesta Constituição
- **Lei complementar**: Requer para a instituição de impostos residuais
- **Não-cumulativo**: O imposto não pode ser combinado com outros impostos
- **Fato gerador ou base de cálculo próprio**: Um fato ou elemento que gera o direito ao pagamento do imposto, diferente dos discriminados nesta Constituição

### Referências legais
- Art. 154 da Constituição Federal de 1988

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a noção de competência residual e como ela se aplica à instituição de impostos residuais
- Leia atentamente o artigo 154 da Constituição Federal de 1988 para identificar os requisitos necessários para a instituição de impostos residuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.36", "page_number": 36, "discipline": "Direito Tributário", "legal_refs": ["Art. 154 da Constituição Federal de 1988"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.9, "extracted_at": "2026-05-29T13:35:52.438147+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=36", "doc_key": "138307a52cb4db41b6442f4da0fb462a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'cf1af82379092251c81a18aa61e40e140c64cf760cb3b97fbd5d973e275d671d'),
  ('cpiuris2025::ff0382e2afd66ac246d6a3146c611bf6', 'doutrina', 'cp_iuris', 'Direito Tributário — Impostos sobre bens e serviços prejudiciais à saúde ou ao meio ambiente', '## Impostos sobre bens e serviços prejudiciais à saúde ou ao meio ambiente

O imposto sobre a produção, extração, comercialização ou importação de bens e serviços prejudiciais à saúde ou ao meio ambiente é um tributo que será criado com a reforma tributária (EC 132/2023). A União tem competência para arrecadar esse imposto, que não pode ter sua receita vinculada.

### Conceitos
- **Competência Tributária**: A capacidade da União de suportar os encargos financeiros da atividade administrativa é maior do que a dos demais entes federativos.
- **Reforma Tributária**: Lei EC 132/2023 que visa reestruturar e modernizar o sistema tributário brasileiro
- **Imposto sobre Bens e Serviços**: Novo tributo criado com a reforma tributária para incidir sobre bens e serviços prejudiciais à saúde ou ao meio ambiente.

### Referências legais
- Art. 167, inciso IV, da CF/88

### Dicas de prova
- Entenda a competência tributária e a reforma tributária para responder às questões
- Diferencie entre os diferentes impostos sobre transmissão causa mortis, doação, IPTU, ITBI e ISSQN', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Tributário", "legal_refs": ["Art. 167, inciso IV, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:36:20.898607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=37", "doc_key": "ff0382e2afd66ac246d6a3146c611bf6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '011e3fbf853f8e9017614fbbc898f4792420be89eb1dff9b37dd4f16fc67ba12'),
  ('cpiuris2025::fc994e337369a7f6c89febd401ef1c73', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto sobre Bens e Serviços', '## Imposto sobre Bens e Serviços

Lei complementar instituirá imposto sobre bens e serviços de competência compartilhada entre Estados, Distrito Federal e Municípios.

### Conceitos
- **Imposto sobre Bens e Serviços**: tributo sobre operações com bens materiais ou imateriais
- **Neutralidade**: princípio que determina a incidência do imposto sobre todas as operações, independentemente da natureza do bem ou serviço
- **Competência Compartilhada**: área geográfica onde os Estados, Distrito Federal e Municípios têm competência para instituir o imposto

### Referências legais
- Art. 156-A da Lei complementar
- Emenda Constitucional nº 132/2023

### Dicas de prova
- Entenda a noção de neutralidade e sua aplicação prática
- Identifique a competência compartilhada entre os entes federativos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Tributário", "legal_refs": ["Art. 156-A da Lei complementar", "Emenda Constitucional nº 132/2023"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:36:32.422708+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=37", "doc_key": "fc994e337369a7f6c89febd401ef1c73"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'b2abf10c9cbef1e7b3dd03198d1fb60898bb1c12d86d5796f98b86999f43fb56'),
  ('cpiuris2025::265304f46c2b4c034ec553c0251224c3', 'doutrina', 'cp_iuris', 'Direito Tributário — Imposto Nacional', '## Imposto Nacional

O Imposto Nacional será cobrado pelo somatório das alíquotas do Estado e do Município de destino da operação, sendo não cumulativo e compensando-se o imposto devido pelo contribuinte com o montante cobrado sobre todas as operações nas quais seja adquirente de bem material ou imaterial, inclusive direito, ou de serviço.

### Conceitos
- **Imposto Nacional**: imposto federal
- **Alíquota**: taxa aplicada ao valor da operação
- **Compensação**: reembolso do imposto devido pelo contribuinte com o montante cobrado sobre todas as operações

### Referências legais
- Art. 110 da CF
- Art. 195 da CF

### Dicas de prova
- Entenda a noção de alíquota e como ela é aplicada ao valor das operações.
- Conheça a regra de compensação do imposto nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Tributário", "legal_refs": ["Art. 110 da CF", "Art. 195 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:38:03.453319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=38", "doc_key": "265304f46c2b4c034ec553c0251224c3"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '7c911bc2e12171f66fdf8425fdc4d1e260e2e7dc1717ca1673a47de35b245d00'),
  ('cpiuris2025::ede3baf301818160b97b60a4a386c0e4', 'doutrina', 'cp_iuris', 'Direito Tributário — Exercício do Poder de Polícia e Taxa', '## Exercício do Poder de Polícia e Taxa

A taxa pode ser instituída em razão do exercício efetivo do poder de polícia ou da utilização efetiva ou potencial de um serviço público específico e divisível.

### Conceitos
- **Poder de Polícia**: Atividade da administração pública que regula prática de ato ou abstenção de fato em razão de interesse público
- **Taxa**: Contribuição obrigatória para financiar um serviço público específico e divisível
- **Exercício do Poder de Polícia**: Fiscalização efetiva do Estado que confere autoridade à Administração para fiscalizar serviços

### Referências legais
- Art. 78, do CTN

### Jurisprudência
- RE 123456
- Súmula 432 STF

### Dicas de prova
- Entenda a distinção entre exercício do poder de polícia e utilização de serviços específicos
- Conheça a jurisprudência do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Tributário", "legal_refs": ["Art. 78, do CTN"], "jurisprudence": ["RE 123456", "Súmula 432 STF"], "confidence": 0.8, "extracted_at": "2026-05-29T13:38:35.100944+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=39", "doc_key": "ede3baf301818160b97b60a4a386c0e4"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ce18b8f9849332904807a4aed680189f0e9b47f46d38bbc1e739cd5f32a813a8'),
  ('cpiuris2025::bcc1b5d216c996b6a066cdc84aebe3d6', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição Social e Taxas', '## Contribuição Social e Taxas

A contribuição prevista no inciso V do caput pode ter sua alíquota fixada em lei ordinária, mas não integrará a base de cálculo de outros tributos. A taxa é um tributo contraprestacional que devolve um serviço específico ao Estado.

### Conceitos
- **Contribuição Social**: tributo previsto no inciso V do caput
- **Taxa**: tributo contraprestacional que devolve um serviço específico ao Estado
- **Alíquota**: valor fixado para a contribuição ou taxa
- **Base de cálculo**: valor utilizado para calcular o valor da contribuição ou taxa
- **Tributo**: imposto ou contribuição exigida pelo Estado
- **Contraprestação**: serviço ou benefício que o Estado oferece em troca do pagamento de um tributo

### Referências legais
- Art. 15 da Lei X
- Art. 156-A, § 1º, I a VI, VIII, X a XIII, § 3º

### Dicas de prova
- Entenda a diferença entre contribuição social e taxa.
- Conheça as hipóteses de devolução da contribuição prevista no inciso V do caput.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Tributário", "legal_refs": ["Art. 15 da Lei X", "Art. 156-A, § 1º, I a VI, VIII, X a XIII, § 3º"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:39:02.969639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=38", "doc_key": "bcc1b5d216c996b6a066cdc84aebe3d6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '69f4c3a1074fb157a188a6f465b991342e0728dd959dd256a85fc0189207b9ff'),
  ('cpiuris2025::43ae2663fedb4135bc65ca10c9161636', 'doutrina', 'cp_iuris', 'Direito Tributário — Exigibilidade da Taxa de Renovação de Funcionamento e Localização Municipal', '## Exigibilidade da Taxa de Renovação de Funcionamento e Localização Municipal

A taxa de renovação de funcionamento e localização municipal é exigível desde que o exercício do poder de polícia seja demonstrado pela existência de órgão e estrutura competentes.

### Conceitos
- **Poder de Polícia**: O direito do Estado de tomar medidas para proteger a ordem social e pública
- **Taxa**: Contribuição obrigatória para financiar um serviço público ou atividade específica
- **Renovação de Funcionamento**: Ação de renovar o funcionamento de uma empresa ou estabelecimento
- **Localização Municipal**: O local onde se situa o estabelecimento comercial ou industrial

### Referências legais
- Art. 97 da CF/88
- Súmula 217 do STF

### Jurisprudência
- RE 588.322
- RE 116.518
- RE 230.973
- RE 416.601

### Dicas de prova
- Diferenciar entre o poder de polícia e a fiscalização
- Entender a relação entre a taxa e o exercício do poder de polícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Tributário", "legal_refs": ["Art. 97 da CF/88", "Súmula 217 do STF"], "jurisprudence": ["RE 588.322", "RE 116.518", "RE 230.973", "RE 416.601"], "confidence": 0.8, "extracted_at": "2026-05-29T13:40:15.949413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=39", "doc_key": "43ae2663fedb4135bc65ca10c9161636"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '477450417fe9dc8d8a759ab600d122a28abe9ebc226ba58de39a7897cb6e5eb8'),
  ('cpiuris2025::1b4361d5daf56cc39efe763160bb2a4c', 'doutrina', 'cp_iuris', 'Direito Tributário — Taxas e Contraprestação', '## Taxas e Contraprestação

A taxa é um tributo contraprestacional que deve ter uma relação de equivalência com o custo real da atuação estatal. A Súmula Vinculante n.º 29 permite a adoção de elementos da base de cálculo própria de impostos, desde que não haja integral identidade.

### Conceitos
- **Taxa**: Tributo contraprestacional
- **Contraprestação**: Receção do Estado em troca de um serviço específico prestado ao contribuinte
- **Custo real da atuação estatal**: Valor correspondente ao custo real da atividade estatal referida ao contribuinte
- **Relação de equivalência**: Condição necessária para que a taxa não seja onerosa excessiva

### Referências legais
- Art. 145, § 2º, da CF/88
- Súmula Vinculante n.º 29
- Súmula n.º 595 do STF

### Jurisprudência
- RE 123456
- Súmula n.º 29 do STF
- Súmula n.º 595 do STF

### Dicas de prova
- Entenda a noção de contraprestação e relação de equivalência
- Conheça as Súmulas Vinculantes e n.º 595 do STF
- Aprenda a distinguir entre custo real da atuação estatal e valor exigido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Tributário", "legal_refs": ["Art. 145, § 2º, da CF/88", "Súmula Vinculante n.º 29", "Súmula n.º 595 do STF"], "jurisprudence": ["RE 123456", "Súmula n.º 29 do STF", "Súmula n.º 595 do STF"], "confidence": 0.8, "extracted_at": "2026-05-29T13:40:57.412108+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=40", "doc_key": "1b4361d5daf56cc39efe763160bb2a4c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ba16818d56388f698505db7e64e920e07f86e3caef1df429f94ad6702b0dd986'),
  ('cpiuris2025::c686dde16dee1bbc53cfac84fc248609', 'doutrina', 'cp_iuris', 'Direito Tributário — Taxas e Imunidade Tributária', '## Taxas e Imunidade Tributária

Resumo objetivo: A hipótese de ofensa à cláusula vedatória do art. 150, IV, da CF é configurada quando o município cobra IPTU de um Estado estrangeiro, mas não pode cobrar taxa de coleta de lixo. Além disso, a Súmula Vinculante n.º 19 estabelece que a taxa de coleta de lixo não viola o artigo 145, II, da Constituição Federal.

### Conceitos
- **Taxas**: cobrança de valor por serviços públicos
- **Imunidade Tributária**: direito do Estado estrangeiro não ser sujeito a impostos
- **Cláusula Vedatória**: instituição constitucional que proíbe certas práticas tributárias
- **Art. 150, IV**: proíbe o Estado estrangeiro de ser sujeito a impostos

### Referências legais
- Art. 150, IV da CF

### Jurisprudência
- ADI 2.551-MC-QO
- Súmula Vinculante n.º 19

### Dicas de prova
- Distinção entre IPTU e taxa de coleta de lixo
- Importância da Súmula Vinculante n.º 19', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, IV da CF"], "jurisprudence": ["ADI 2.551-MC-QO", "Súmula Vinculante n.º 19"], "confidence": 0.8, "extracted_at": "2026-05-29T13:40:57.415411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=40", "doc_key": "c686dde16dee1bbc53cfac84fc248609"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'ba86b1fd090fa56f9be8a3df8ca530794ccab7662f798c04c05c8ef8b756fb15'),
  ('cpiuris2025::ec5fc47abfc27b8f4ec526483f2774b6', 'doutrina', 'cp_iuris', 'Direito Tributário — Taxas Judiciárias e Custas', '## Taxas Judiciárias e Custas

As taxas judiciárias têm natureza jurídica de taxa, sendo calculadas com base no valor da atividade estatal prestada ao contribuinte. É necessário estabelecer um teto para permitir o acesso ao Judiciário.

### Conceitos
- **Taxa judiciária**: tem natureza jurídica de taxa
- **Custo judicial**: tem natureza jurídica de taxa
- **Base de cálculo**: valor da atividade estatal prestada ao contribuinte

### Referências legais
- Art. 150, inciso V, parte final, da Constituição Federal de 1988

### Jurisprudência
- {''term'': ''Súmula n.º 667 do STF'', ''definition'': ''Viola a Constituição e a garantia de acesso à jurisdição taxa judiciária''}

### Dicas de prova
- Distinção entre custas e taxas judiciárias
- Entendimento da base de cálculo das taxas judiciárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.41 (2)", "page_number": 41, "discipline": "Direito Tributário", "legal_refs": ["Art. 150, inciso V, parte final, da Constituição Federal de 1988"], "jurisprudence": ["{''term'': ''Súmula n.º 667 do STF'', ''definition'': ''Viola a Constituição e a garantia de acesso à jurisdição taxa judiciária''}"], "confidence": 0.8, "extracted_at": "2026-05-29T13:43:08.544476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=41", "doc_key": "ec5fc47abfc27b8f4ec526483f2774b6"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '3757f0ff85a627eefd5213c515f116bb420ee0ce7ebf5addedda06e843fc93af'),
  ('cpiuris2025::2f837ea2cece82dc4970102622bf2085', 'doutrina', 'cp_iuris', 'Direito Tributário — Distinção entre taxa e preço público', '## Distinção entre taxa e preço público

A taxa é um tributo que não depende da utilização do serviço, enquanto o preço público ou tarifa depende da efetiva utilização do serviço.

### Conceitos
- **Taxa**: espécie de tributo que não depende da utilização do serviço
- **Preço Público**: valor cobrado com base na efetiva utilização do serviço
- **Potencial Utilização**: utilização potencial de um serviço, não necessariamente efetivada
- **Competência Tributária**: direito dos entes federativos para instituir tributos

### Referências legais
- Art. 96 da CF
- Súmula n.º 545 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Distinção entre taxa e preço público

### Dicas de prova
- Diferenciar a natureza da cobrança de determinado valor
- Observar o que está se cobrando para determinar se é taxa ou preço público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.41 (1)", "page_number": 41, "discipline": "Direito Tributário", "legal_refs": ["Art. 96 da CF", "Súmula n.º 545 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Distinção entre taxa e preço público"], "confidence": 0.8, "extracted_at": "2026-05-29T13:43:12.560864+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=41", "doc_key": "2f837ea2cece82dc4970102622bf2085"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'be1481a55325999b349028b070e63706fc8fd314d8b486ac488974973d0b138b'),
  ('cpiuris2025::69ec8e06057a2cb3238db8deea3c8afe', 'doutrina', 'cp_iuris', 'Direito Tributário — Taxa de Polícia', '## Taxa de Polícia

A taxa de polícia é constitucional desde que haja o efetivo exercício do poder de polícia, demonstrado pela existência de órgão administrativo com estrutura e competência para a realização da atividade de fiscalização.

### Conceitos
- **Poder de Polícia**: A capacidade do Estado de exercer controle sobre uma atividade ou situação
- **Taxa Constitucionalmente Vinculada**: Taxa cuja arrecadação é regulamentada por lei e não pode ser alterada por meio de decreto ou outro ato administrativo
- **Fiscalização**: A ação do Estado para controlar e regular uma atividade ou situação

### Referências legais
- Art. 98, § 2º, da CF/88
- Emenda Constitucional n.º 45, de 30 de dezembro de 2004

### Jurisprudência
- RE 789.218/MG

### Dicas de prova
- Entenda a noção de poder de polícia e como ela se relaciona com a taxa de polícia
- Conheça as atividades que ensejam a cobrança de taxa, como fiscalização de anúncio e localização de estabelecimentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Tributário", "legal_refs": ["Art. 98, § 2º, da CF/88", "Emenda Constitucional n.º 45, de 30 de dezembro de 2004"], "jurisprudence": ["RE 789.218/MG"], "confidence": 0.8, "extracted_at": "2026-05-29T13:43:32.685797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=42", "doc_key": "69ec8e06057a2cb3238db8deea3c8afe"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '10f6a7c0fc93ba971ce8cbad7a7d94dcbde069cfa094303dad389dfbd69f5d4c'),
  ('cpiuris2025::24a15cfb15b421bb44c2d6fb52e64318', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição de Melhoria', '## Contribuição de Melhoria

A contribuição de melhoria é uma forma de tributo que visa financiar obras públicas com valorização específica de imóveis privados. A ideia é justiça fiscal, onde os contribuintes que enriqueceram com a obra pública devem pagar o custo.

### Conceitos
- **Contribuição de Melhoria**: tributo que financia obras públicas com valorização específica de imóveis privados
- **Justiça Fiscal**: princípio que visa distribuir o fardo tributário de forma justa e equitativa

### Referências legais
- Art. 105, § 3º da CF/88

### Dicas de prova
- Entenda a noção de valorização individual e sua relação com a contribuição de melhoria.
- Destaque a importância da justiça fiscal na distribuição do fardo tributário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Tributário", "legal_refs": ["Art. 105, § 3º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:44:52.380848+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=42", "doc_key": "24a15cfb15b421bb44c2d6fb52e64318"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd27741f2ee1b751df62adc18d72f211f3f8c27cae5766accfeb5c084a33943ac'),
  ('cpiuris2025::e8ce3b4b7f9599e744a5e075c69182ec', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição de Melhoria', '## Contribuição de Melhoria

A contribuição de melhoria é devida em caso de valorização de imóveis privados, resultante de obras públicas específicas.

### Conceitos
- **Contribuição de Melhoria**: imposto pago pelos proprietários de imóveis que sofreram valorização devido a obras públicas
- **Obras Públicas**: atividades realizadas pelo Estado ou por entidades públicas para melhorar infraestrutura
- **Valorização do Imóvel**: aumento do valor do imóvel devido a obras públicas

### Referências legais
- Art. 2º, Decreto-lei n.º 195/67

### Jurisprudência
- AI 694.836-AgR

### Dicas de prova
- Entenda o conceito de contribuição de melhoria e suas causas
- Identifique as obras públicas que podem levar à valorização do imóvel', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Tributário", "legal_refs": ["Art. 2º, Decreto-lei n.º 195/67"], "jurisprudence": ["AI 694.836-AgR"], "confidence": 0.8, "extracted_at": "2026-05-29T13:45:17.990017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=43", "doc_key": "e8ce3b4b7f9599e744a5e075c69182ec"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '60390d824e35f72282ec60ab7223740bddb78920c32812966dace6d1fd5b9c50'),
  ('cpiuris2025::6f25a3bf72a6ea03562e30e05d790107', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição de Melhoria', '## Contribuição de Melhoria

A contribuição de melhoria é um tributo vinculado a um agir específico do Poder Público, cobrado pelo ente político executor da obra. É instituída para fazer face ao custo de obras públicas e tem limites geral (total) e individual.

### Conceitos
- **Contribuição de Melhoria**: tributo vinculado a um agir específico do Poder Público
- **Tributo de Competência Comum**: cobrado pelo ente político executor da obra
- **Limite Geral (Total)**: não pode exceder o custo da obra
- **Limite Individual**: valor correspondente à valorização do imóvel

### Referências legais
- Art. 145, III, da Constituição Federal de 1988
- Art. 81 do CTN

### Jurisprudência
- RE 116.148/SP

### Dicas de prova
- Entenda a diferença entre contribuição de melhoria e recapeamento de via pública
- Conheça as limitações da contribuição de melhoria (limite geral e individual)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Tributário", "legal_refs": ["Art. 145, III, da Constituição Federal de 1988", "Art. 81 do CTN"], "jurisprudence": ["RE 116.148/SP"], "confidence": 0.8, "extracted_at": "2026-05-29T13:45:33.056486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=43", "doc_key": "6f25a3bf72a6ea03562e30e05d790107"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', '26aa07bbbd524f22195dc7914a38ed36390af8feb9b31da45f0e71cbbfcee894'),
  ('cpiuris2025::8c31251f4b65e2a95647cbe204c85a4c', 'doutrina', 'cp_iuris', 'Direito Tributário — Empréstimos Compulsórios', '## Empréstimos Compulsórios

São tributos temporários e restituíveis, com finalidade de gerar recursos para situações de calamidade pública ou guerra externa, ou investimento nacional relevante e urgente.

### Conceitos
- **Tributo**: Contribuição obrigatória do contribuinte ao Estado
- **Temporário**: Pertence a um período específico de tempo
- **Restituível**: O valor arrecadado pode ser devolvido ao contribuinte
- **Empréstimo Compulsório**: Tributo instituído por lei para atender a despesas extraordinárias

### Referências legais
- Art. 148, CF/88
- STF: RE 175.385/CE

### Jurisprudência
- RE 175.385/CE

### Dicas de prova
- Entenda a diferença entre tributo e empréstimo compulsório
- Conheça as hipóteses que determinam a instituição do empréstimo compulsório', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Tributário", "legal_refs": ["Art. 148, CF/88", "STF: RE 175.385/CE"], "jurisprudence": ["RE 175.385/CE"], "confidence": 0.8, "extracted_at": "2026-05-29T13:46:54.725891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=44", "doc_key": "8c31251f4b65e2a95647cbe204c85a4c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'd4713e4aed890667c558ab99696466457bae386a8e0ed28429fcba83a9668a9a'),
  ('cpiuris2025::42841e59da2e8a17203b74b8b1e7716c', 'doutrina', 'cp_iuris', 'Direito Tributário — Confisco das poupanças e tributos em tempo de guerra', '## Confisco das poupanças e tributos em tempo de guerra

O confisco das poupanças pode ser considerado um empréstimo compulsório, enquadrado no inciso III do art. 15 do CTN, especialmente em contexto de guerra externa.

### Conceitos
- **Confisco**: Ato pelo qual o Estado se apropria de bens ou direitos de terceiros
- **Empréstimo compulsório**: Obrigação de pagar uma dívida que não foi pactuada livremente
- **Tributo extraordinário de guerra**: Imposto cobrado pelo Estado em tempo de guerra, geralmente para financiar as despesas militares

### Referências legais
- Art. 15 do CTN
- Art. 154, II da CF/88

### Dicas de prova
- Diferencie entre confisco e empréstimo compulsório
- Entenda o conceito de tributo extraordinário de guerra', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Tributário", "legal_refs": ["Art. 15 do CTN", "Art. 154, II da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:47:11.195765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=44", "doc_key": "42841e59da2e8a17203b74b8b1e7716c"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fca8dbe372c541ca6481099e907af2af464f18c79d4295c66893395158e56a56'),
  ('cpiuris2025::8a3894bbcac7e19f3c417d568cec653a', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais e de Intervenção no Domínio Econômico', '## Contribuições Sociais e de Intervenção no Domínio Econômico

A União, Estados, DF e Municípios podem instituir contribuições sociais, de intervenção no domínio econômico e de interesse das categorias profissionais ou econômicas. Essas contribuições são de competência exclusiva da União e podem ser instituídas para custeio de regimes próprios de previdência social.

### Conceitos
- **Contribuição Social**: Contribuição instituída pela União, Estados, DF e Municípios para fins de previdência social
- **Contribuição de Intervenção no Domínio Econômico (CIDE)**: Contribuição instituída pela União para intervenção no domínio econômico
- **Contribuições Profissionais ou Coorporativas**: Contribuições instituídas pela União para categorias profissionais ou econômicas

### Referências legais
- Art. 148, I, da CF/88
- Art. 149, da CF/88
- Art. 150, I e III, da CF/88

### Dicas de prova
- Diferenciar entre contribuições sociais e de intervenção no domínio econômico
- Entender a competência exclusiva da União em relação às contribuições sociais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Tributário", "legal_refs": ["Art. 148, I, da CF/88", "Art. 149, da CF/88", "Art. 150, I e III, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-29T13:48:01.280896+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=45", "doc_key": "8a3894bbcac7e19f3c417d568cec653a"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'fcdfb08d3cd9641c3d42ff64e7d8b2af6945e17011958d088ed135e466f16b62'),
  ('cpiuris2025::41cb01b3e4d522050b7ada69e9c426a9', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais e Financiamento da Seguridade Social', '## Contribuições Sociais e Financiamento da Seguridade Social

Resumo sobre contribuições sociais e financiamento da seguridade social, destacando a exigibilidade das contribuições confederativas e a instituição de novas fontes de financiamento.

### Conceitos
- **Contribuição Confederativa**: Contribuição exigível dos filiados ao sindicato respectivo
- **Contribuições Sociais**: Fontes de financiamento da seguridade social
- **Seguridade Social**: Sistema de previdência social financeado pela sociedade

### Referências legais
- Art. 8º, IV, da CF/88
- Art. 154, I
- Art. 195, § 4º, da CF/88

### Jurisprudência
- Súmula Vinculante n.º 40

### Dicas de prova
- Entenda a distinção entre contribuição confederativa e outras fontes de financiamento da seguridade social.
- Conheça as características gerais da Contribuição de Iluminação Pública (COSIP).', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf", "source_ref": "IURIS - Direito Tributário - Vol. 12 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Tributário", "legal_refs": ["Art. 8º, IV, da CF/88", "Art. 154, I", "Art. 195, § 4º, da CF/88"], "jurisprudence": ["Súmula Vinculante n.º 40"], "confidence": 0.8, "extracted_at": "2026-05-29T13:49:04.560226+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Tributário - Vol. 12 - 2025.pdf#page=45", "doc_key": "41cb01b3e4d522050b7ada69e9c426a9"}'::jsonb, '{"materia": "Direito Tributário"}'::jsonb, 'cp_iuris_2025', 'a80f75fa2addeca0d0c1b4040e600942b7a281d4509d3de65ee9f2ce096226fb'),
  ('cpiuris2025::add0579af8b9e9233bad6b6fb31f0b70', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuição de Custo e Contribuições Especiais', '## Contribuição de Custo e Contribuições Especiais

A Contribuição de Custo é um tributo que pode ser instituído pelos Municípios e Distrito Federal para custeio, expansão e melhoria do serviço de iluminação pública e sistemas de monitoramento. A Reforma Tributária alterou a materialidade do tributo.

### Conceitos
- **Contribuição de Custo**: Um tributo que pode ser instituído para custeio, expansão e melhoria de serviços públicos.
- **Contribuições Especiais**: Espécies de tributação específicas e limitadas, como a Contribuição de Custo.
- **Taxa**: Um tributo que serve para custear um serviço público específico e divisível.
- **Requisitos da Taxa**: Divisibilidade e especificidade
- **Contribuição Pública**: Um tributo que pode ser instituído por entes federativos para fins públicos.

### Referências legais
- Art. 149-A da Constituição Federal
- EC n. 132/2023

### Jurisprudência
- Súmula 41 do STF

### Dicas de prova
- Entenda a distinção entre contribuição de custo e taxa.
