A reforma da previdência alterou a competência tributária das contribuições sociais, permitindo instituição de novas contribuições sociais previdenciárias.

### Conceitos
- **Contribuição Social Previdenciária**: Tributo que custea o sistema de segurança social
- **Contribuição Interventiva**: Tributo que intervém no domínio econômico
- **Contribuição Coorporativa**: Tributo de interesse das categorias profissionais

### Referências legais
- Art. 149 da CF/88 (EC 103/2019)

### Dicas de prova
