  ('cpiuris2025::8db4576d39556ef0f1fac4be81d9e1d5', 'doutrina', 'cp_iuris', 'Direito Tributário — Contribuições Sociais', '## Contribuições Sociais

A União tem competência exclusiva para instituir contribuições sociais, que podem ser ordinárias ou extraordinárias, com objetivo de financiar a previdência social.

### Conceitos
- **Contribuição Social**: instituída pela União para financiar a previdência social
- **Contribuição Ordinária**: incidência sobre os proventos de aposentadoria e pensões
- **Contribuição Extraordinária**: incidência sobre o valor dos proventos de aposentadoria e pensões para equacionar deficit atuarial
- **Deficit Atuarial**: situação em que a previdência social não tem recursos suficientes para pagar benefícios
- **Contribuição Progressiva**: incidência sobre a base de contribuição ou proventos de aposentadoria e pensões

### Referências legais
- Art. 149 da Lei Tributária
- Art. 195, § 6º

### Dicas de prova
- Entenda a competência exclusiva da União para instituir contribuições sociais
